document.querySelectorAll("[data-range]").forEach((btn) => {
  btn.addEventListener("click", () => {
    const range = btn.dataset.range;
    const today = new Date();
    let start, end;

    if (range === "this-month") {
      start = new Date(today.getFullYear(), today.getMonth(), 1);
      end = today;
    } else if (range === "last-month") {
      start = new Date(today.getFullYear(), today.getMonth() - 1, 1);
      end = new Date(today.getFullYear(), today.getMonth(), 0);
    } else {
      const days = parseInt(range, 10);
      start = new Date(today);
      start.setDate(today.getDate() - days);
      end = today;
    }

    document.getElementById("shopify-sales-start-date").value = start
      .toISOString()
      .split("T")[0];
    document.getElementById("shopify-sales-end-date").value = end
      .toISOString()
      .split("T")[0];
    updateShopifySalesFetchBtn();
  });
});

document.getElementById("shopify-sales-fetch-btn")?.addEventListener("click", fetchShopifySales);

async function fetchShopifySales() {
  const fetchBtn = document.getElementById("shopify-sales-fetch-btn");
  const progressEl = document.getElementById("shopify-sales-progress");
  const progressBar = document.getElementById("shopify-sales-progress-bar");
  const progressStatus = document.getElementById("shopify-sales-progress-status");
  const progressItems = document.getElementById("shopify-sales-progress-items");
  const resultsEl = document.getElementById("shopify-sales-results");
  const emptyEl = document.getElementById("shopify-sales-empty");

  const storeIds = Array.from(
    document.querySelectorAll(".shopify-sales-store-cb:checked"),
  ).map((cb) => parseInt(cb.value, 10));
  const startDate = document.getElementById("shopify-sales-start-date").value;
  const endDate = document.getElementById("shopify-sales-end-date").value;

  if (storeIds.length === 0 || !startDate || !endDate) return;

  fetchBtn.disabled = true;
  fetchBtn.textContent = "Fetching...";
  progressEl.style.display = "block";
  progressBar.style.width = "0%";
  progressStatus.textContent = "Connecting to stores...";
  progressItems.innerHTML = "";
  resultsEl.style.display = "none";
  emptyEl.style.display = "none";
  shopifySalesResults = null;

  const storeItemMap = new Map();

  try {
    const response = await fetch(`${API_BASE}/shopify-sales/stream`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        store_ids: storeIds,
        start_date: startDate,
        end_date: endDate,
        use_local_data: shopifySalesUseLocal(),
      }),
    });

    const reader = response.body.getReader();
    const decoder = new TextDecoder();
    let buffer = "";

    while (true) {
      const { done, value } = await reader.read();
      if (done) break;

      buffer += decoder.decode(value, { stream: true });
      const messages = buffer.split("\n\n");
      buffer = messages.pop();

      for (const msg of messages) {
        if (!msg.trim()) continue;

        const eventMatch = msg.match(/event: (\w+)\ndata: (.+)/s);
        if (!eventMatch) continue;

        const [, eventType, dataStr] = eventMatch;
        const data = JSON.parse(dataStr);

        if (eventType === "progress") {
          if (data.status === "started") {
            const src = data.data_source === "local" ? "local data" : "Shopify";
            progressStatus.textContent = `Fetching orders from ${data.total_stores} store(s) via ${src}...`;
          } else if (data.status === "skipped_store") {
            const item = document.createElement("div");
            item.style.cssText = "display: flex; align-items: center; gap: 0.5rem;";
            item.innerHTML = `<span style="color: var(--warning);">&#9679;</span> <span>${escapeHtml(data.store_name)} &mdash; skipped: ${escapeHtml(data.message || "not synced")}</span>`;
            progressItems.appendChild(item);
          } else if (data.status === "searching_store") {
            const item = document.createElement("div");
            item.style.cssText = "display: flex; align-items: center; gap: 0.5rem;";
            const via = data.data_source === "local" ? "reading local data" : "fetching orders";
            item.innerHTML = `<span style="color: var(--accent-primary); animation: pulse 1.5s ease-in-out infinite;">&#9679;</span> <span>${escapeHtml(data.store_name)} — ${via}...</span>`;
            storeItemMap.set(data.store_name, item);
            progressItems.appendChild(item);
          } else if (data.status === "completed_store") {
            const pct = Math.round((data.completed / data.total_stores) * 100);
            progressBar.style.width = `${pct}%`;
            progressStatus.textContent = `${data.completed} of ${data.total_stores} store(s) complete...`;

            const existing = storeItemMap.get(data.store_name);
            if (existing) {
              existing.style.cssText = "display: flex; align-items: center; gap: 0.5rem;";
              existing.innerHTML = `<span style="color: var(--success);">&#10003;</span> <span>${escapeHtml(data.store_name)} &mdash; ${data.orders_found} orders, ${data.line_items} line items</span>`;
            }
          } else if (data.status === "error_store") {
            const pct = Math.round((data.completed / data.total_stores) * 100);
            progressBar.style.width = `${pct}%`;
            progressStatus.textContent = `${data.completed} of ${data.total_stores} store(s) complete...`;

            const existing = storeItemMap.get(data.store_name);
            if (existing) {
              existing.style.cssText = "display: flex; align-items: center; gap: 0.5rem;";
              existing.innerHTML = `<span style="color: var(--danger);">&#10007;</span> <span>${escapeHtml(data.store_name)} &mdash; ${escapeHtml(data.message)}</span>`;
            }
          } else if (data.status === "aggregating") {
            progressBar.style.width = "100%";
            progressStatus.textContent = "Aggregating results...";
          }
        } else if (eventType === "complete") {
          progressStatus.textContent = "Done!";
          shopifySalesResults = data;
          displayShopifySalesResults(data);
        } else if (eventType === "error") {
          progressStatus.textContent = "Error";
          const item = document.createElement("div");
          item.style.color = "var(--danger)";
          item.textContent = data.message || "Unknown error";
          progressItems.appendChild(item);
        }
      }
    }
  } catch (error) {
    console.error("Shopify sales fetch error:", error);
    progressStatus.textContent = "Error";
    const item = document.createElement("div");
    item.style.color = "var(--danger)";
    item.textContent = `Error: ${error.message}`;
    progressItems.appendChild(item);
  } finally {
    fetchBtn.disabled = false;
    fetchBtn.textContent = "Fetch Sales";
  }
}

let shopifySalesSortColumn = "total_revenue";
let shopifySalesSortDirection = "desc";

const shopifySalesNumericColumns = new Set([
  "cost",
  "real_cost",
  "avg_price",
  "today_price",
  "avg_margin",
  "profit_margin",
  "total_quantity",
  "total_revenue",
]);

const SHOPIFY_SALES_COLUMNS = [
  { key: "product_title",  label: "Product",       baseWidth: 30, align: "left" },
  { key: "barcode",        label: "UPC",           baseWidth: 10, align: "left" },
  { key: "sku",            label: "SKU",           baseWidth: 10, align: "left" },
  { key: "cost",           label: "Cost",          baseWidth: 6,  align: "right" },
  { key: "real_cost",      label: "Real Cost",     baseWidth: 6,  align: "right" },
  { key: "avg_price",      label: "Avg Price",     baseWidth: 7,  align: "right" },
  { key: "today_price",    label: "Today's Price", baseWidth: 7,  align: "right" },
  { key: "avg_margin",     label: "Avg Margin %",  baseWidth: 7,  align: "right" },
  { key: "profit_margin",  label: "Margin %",      baseWidth: 6,  align: "right" },
  { key: "total_quantity", label: "Qty",           baseWidth: 6,  align: "right" },
  { key: "total_revenue",  label: "Revenue",       baseWidth: 9,  align: "right" },
];

const SHOPIFY_SALES_HIDDEN_COLUMNS_KEY = "shopify_sales_hidden_columns";

let shopifySalesHiddenColumns = (() => {
  try {
    const arr = JSON.parse(localStorage.getItem(SHOPIFY_SALES_HIDDEN_COLUMNS_KEY) || "[]");
    return Array.isArray(arr) ? arr : [];
  } catch {
    return [];
  }
})();

function getShopifySalesVisibleColumns() {
  return SHOPIFY_SALES_COLUMNS.filter((c) => !shopifySalesHiddenColumns.includes(c.key));
}

function buildShopifySalesColumnPills() {
  const container = document.getElementById("shopify-sales-column-pills");
  if (!container) return;
  container.innerHTML = "";
  SHOPIFY_SALES_COLUMNS.forEach((col) => {
    const isVisible = !shopifySalesHiddenColumns.includes(col.key);
    const label = document.createElement("label");
    label.style.cssText = `display: inline-flex; align-items: center; gap: 0.25rem; font-size: 0.75rem; cursor: pointer; padding: 0.2rem 0.5rem; border-radius: 1rem; border: 1px solid var(--border-color); background: ${isVisible ? "var(--bg-tertiary, rgba(255,255,255,0.08))" : "transparent"}; white-space: nowrap; opacity: ${isVisible ? "1" : "0.5"}; transition: opacity 0.15s, background 0.15s;`;
    const cb = document.createElement("input");
    cb.type = "checkbox";
    cb.checked = isVisible;
    cb.style.cssText = "margin: 0; cursor: pointer;";
    cb.onchange = () => toggleShopifySalesColumn(col.key);
    label.appendChild(cb);
    label.appendChild(document.createTextNode(col.label));
    container.appendChild(label);
  });
}

function toggleShopifySalesColumn(key) {
  const idx = shopifySalesHiddenColumns.indexOf(key);
  if (idx >= 0) {
    shopifySalesHiddenColumns.splice(idx, 1);
  } else {
    if (getShopifySalesVisibleColumns().length <= 1) {
      showToast("At least one column must remain visible", "warning");
      buildShopifySalesColumnPills();
      return;
    }
    shopifySalesHiddenColumns.push(key);
  }
  localStorage.setItem(SHOPIFY_SALES_HIDDEN_COLUMNS_KEY, JSON.stringify(shopifySalesHiddenColumns));
  buildShopifySalesColumnPills();
  if (shopifySalesResults) displayShopifySalesResults(shopifySalesResults);
}

function resetShopifySalesColumns() {
  shopifySalesHiddenColumns = [];
  localStorage.removeItem(SHOPIFY_SALES_HIDDEN_COLUMNS_KEY);
  buildShopifySalesColumnPills();
  if (shopifySalesResults) displayShopifySalesResults(shopifySalesResults);
}

document.getElementById("shopify-sales-columns-reset")?.addEventListener("click", (e) => {
  e.preventDefault();
  resetShopifySalesColumns();
});

function sortShopifySalesResults(results) {
  const col = shopifySalesSortColumn;
  const dir = shopifySalesSortDirection === "asc" ? 1 : -1;
  const isNumeric = shopifySalesNumericColumns.has(col);

  return [...results].sort((a, b) => {
    let av = a[col];
    let bv = b[col];
    if (isNumeric) {
      av = av != null ? parseFloat(av) : -Infinity;
      bv = bv != null ? parseFloat(bv) : -Infinity;
      return (av - bv) * dir;
    }
    av = (av || "").toLowerCase();
    bv = (bv || "").toLowerCase();
    return av < bv ? -dir : av > bv ? dir : 0;
  });
}

// Every whitespace-separated term must appear somewhere in the row's
// description (title + variant), UPC or SKU — so "pipe 5 lb" narrows as you
// type and a pasted UPC matches on its own.
function filterShopifySalesResults(results) {
  const raw = (document.getElementById("shopify-sales-filter")?.value || "").trim().toLowerCase();
  if (!raw) return results;
  const terms = raw.split(/\s+/);
  return results.filter((r) => {
    const haystack = `${r.product_title || ""} ${r.variant_title || ""} ${r.barcode || ""} ${r.sku || ""}`.toLowerCase();
    return terms.every((t) => haystack.includes(t));
  });
}

let shopifySalesFilterTimer = null;
document.getElementById("shopify-sales-filter")?.addEventListener("input", () => {
  clearTimeout(shopifySalesFilterTimer);
  shopifySalesFilterTimer = setTimeout(() => {
    if (shopifySalesResults) displayShopifySalesResults(shopifySalesResults);
  }, 150);
});

function updateShopifySalesSortIndicators() {
  const table = document.getElementById("shopify-sales-table");
  if (!table) return;
  table.querySelectorAll("th[data-sort]").forEach((th) => {
    const indicator = th.querySelector(".sort-indicator");
    if (!indicator) return;
    if (th.dataset.sort === shopifySalesSortColumn) {
      indicator.textContent = shopifySalesSortDirection === "asc" ? "▲" : "▼";
      indicator.style.opacity = "1";
    } else {
      indicator.textContent = "";
      indicator.style.opacity = "0.3";
    }
  });
}

document.getElementById("shopify-sales-table")?.addEventListener("click", (e) => {
  const th = e.target.closest("th[data-sort]");
  if (!th) return;
  const col = th.dataset.sort;
  if (shopifySalesSortColumn === col) {
    shopifySalesSortDirection = shopifySalesSortDirection === "asc" ? "desc" : "asc";
  } else {
    shopifySalesSortColumn = col;
    shopifySalesSortDirection = shopifySalesNumericColumns.has(col) ? "desc" : "asc";
  }
  if (shopifySalesResults) displayShopifySalesResults(shopifySalesResults);
});

function displayShopifySalesResults(data) {
  const resultsEl = document.getElementById("shopify-sales-results");
  const emptyEl = document.getElementById("shopify-sales-empty");
  const tbody = document.getElementById("shopify-sales-tbody");
  const tfoot = document.getElementById("shopify-sales-tfoot");
  const summaryEl = document.getElementById("shopify-sales-summary");

  const results = data.results || [];
  const summary = data.summary || {};

  if (results.length === 0) {
    emptyEl.style.display = "block";
    resultsEl.style.display = "none";
    return;
  }

  const shippingVal = parseFloat(summary.total_shipping || 0);
  const shippingPart = shippingVal > 0 ? ` · $${shippingVal.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })} shipping` : "";
  const sourcePart = summary.data_source === "local" ? " · local data" : "";
  const ordersPart = summary.total_orders != null ? `${summary.total_orders.toLocaleString()} orders · ` : "";
  let summaryHtml = `<div>${ordersPart}${summary.total_items} products · ${summary.total_quantity?.toLocaleString()} units sold · $${parseFloat(summary.total_revenue || 0).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })} total revenue${shippingPart} · ${summary.stores_searched} store(s) · ${summary.date_range?.start} to ${summary.date_range?.end}${sourcePart}</div>`;

  const skippedStores = summary.skipped_stores || [];
  if (skippedStores.length > 0) {
    summaryHtml += `<div style="margin-top:6px;padding:6px 10px;border-left:3px solid var(--warning, #f9ab00);background:var(--bg-tertiary, rgba(255,255,255,0.04));border-radius:4px;font-size:0.85rem;">Skipped (not synced): ${escapeHtml(skippedStores.join(", "))} — run a sync in the Data Sync tab or uncheck Use local data.</div>`;
  }

  const excludedProducts = summary.excluded_products || [];
  if (excludedProducts.length > 0) {
    const exclRev = parseFloat(summary.excluded_total_revenue || 0);
    const exclQty = summary.excluded_total_quantity || 0;
    let exclRows = excludedProducts.map(p => `<div style="display:flex;justify-content:space-between;padding:2px 0;font-size:0.8125rem;"><span>${escapeHtml(p.product_title)}</span><span>${p.quantity.toLocaleString()} units · $${parseFloat(p.revenue).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</span></div>`).join("");
    summaryHtml += `<div style="margin-top:6px;padding:6px 10px;border-left:3px solid var(--warning, #f9ab00);background:var(--bg-tertiary, rgba(255,255,255,0.04));border-radius:4px;font-size:0.85rem;">Excluded: ${excludedProducts.length} product(s) · ${exclQty.toLocaleString()} units · $${exclRev.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })} revenue <a href="#" id="toggle-excluded-details" style="margin-left:8px;font-size:0.8rem;">[show]</a><div id="excluded-details" style="display:none;margin-top:4px;padding-top:4px;border-top:1px solid var(--border-color, rgba(255,255,255,0.1));">${exclRows}</div></div>`;
  }

  summaryEl.innerHTML = summaryHtml;

  const toggleLink = document.getElementById("toggle-excluded-details");
  if (toggleLink) {
    toggleLink.addEventListener("click", (e) => {
      e.preventDefault();
      const details = document.getElementById("excluded-details");
      if (details.style.display === "none") {
        details.style.display = "block";
        toggleLink.textContent = "[hide]";
      } else {
        details.style.display = "none";
        toggleLink.textContent = "[show]";
      }
    });
  }

  const visibleCols = getShopifySalesVisibleColumns();
  const totalBase = visibleCols.reduce((s, c) => s + c.baseWidth, 0);

  const thead = document.getElementById("shopify-sales-thead");
  thead.innerHTML =
    "<tr>" +
    visibleCols
      .map((col) => {
        const width = ((col.baseWidth / totalBase) * 100).toFixed(1);
        const alignStyle = col.align === "right" ? " text-align: right;" : "";
        return `<th style="width: ${width}%;${alignStyle} cursor: pointer; user-select: none;" data-sort="${col.key}">${col.label} <span class="sort-indicator"></span></th>`;
      })
      .join("") +
    "</tr>";

  const money = (v) => (v != null ? "$" + parseFloat(v).toFixed(2) : "\u2014");
  const percent = (v) => (v != null ? parseFloat(v).toFixed(1) + "%" : "\u2014");

  const cellHtml = (col, r) => {
    switch (col.key) {
      case "product_title": {
        const productDisplay = r.variant_title ? `${r.product_title} - ${r.variant_title}` : r.product_title;
        return `<td>${escapeHtml(productDisplay)}</td>`;
      }
      case "barcode":
        return `<td style="font-family: monospace; font-size: 0.8125rem;">${escapeHtml(r.barcode || "")}</td>`;
      case "sku":
        return `<td style="font-size: 0.8125rem;">${escapeHtml(r.sku || "")}</td>`;
      case "cost":
      case "real_cost":
      case "avg_price":
      case "today_price":
        return `<td style="text-align: right;">${money(r[col.key])}</td>`;
      case "avg_margin":
      case "profit_margin":
        return `<td style="text-align: right;">${percent(r[col.key])}</td>`;
      case "total_quantity":
        return `<td style="text-align: right;">${r.total_quantity.toLocaleString()}</td>`;
      case "total_revenue":
        return `<td style="text-align: right;">$${parseFloat(r.total_revenue).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</td>`;
      default:
        return "<td></td>";
    }
  };

  const filtered = filterShopifySalesResults(results);
  const sorted = sortShopifySalesResults(filtered);

  const filterCountEl = document.getElementById("shopify-sales-filter-count");
  if (filterCountEl) {
    filterCountEl.textContent =
      filtered.length === results.length ? "" : `${filtered.length.toLocaleString()} of ${results.length.toLocaleString()} products`;
  }

  tbody.innerHTML = sorted.length
    ? sorted.map((r) => `<tr>${visibleCols.map((col) => cellHtml(col, r)).join("")}</tr>`).join("")
    : `<tr><td colspan="${visibleCols.length}" style="text-align: center; color: var(--text-tertiary); padding: 1.5rem;">No products match the filter.</td></tr>`;

  const totalQty = filtered.reduce((s, r) => s + r.total_quantity, 0);
  const totalRev = filtered.reduce((s, r) => s + parseFloat(r.total_revenue), 0);
  const avgAll = totalQty > 0 ? (totalRev / totalQty).toFixed(2) : "0.00";
  const footerValues = {
    avg_price: `$${avgAll}`,
    total_quantity: totalQty.toLocaleString(),
    total_revenue: `$${totalRev.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`,
  };
  tfoot.innerHTML =
    "<tr>" +
    visibleCols
      .map((col, i) => {
        const val = footerValues[col.key] ?? (i === 0 ? "Totals" : "");
        const alignStyle = col.align === "right" ? "text-align: right; " : "";
        return `<td style="${alignStyle}font-weight: 600;">${val}</td>`;
      })
      .join("") +
    "</tr>";
  tfoot.style.display = "";

  updateShopifySalesSortIndicators();
  resultsEl.style.display = "block";
}

document.getElementById("shopify-sales-export-btn")?.addEventListener("click", exportShopifySalesToExcel);

function exportShopifySalesToExcel() {
  if (!shopifySalesResults || !shopifySalesResults.results || shopifySalesResults.results.length === 0) return;

  const visibleCols = getShopifySalesVisibleColumns();

  const exportValue = (col, r) => {
    switch (col.key) {
      case "product_title":
        return r.variant_title ? `${r.product_title} - ${r.variant_title}` : (r.product_title || "");
      case "barcode":
        return r.barcode || "";
      case "sku":
        return r.sku || "";
      case "cost":
      case "real_cost":
      case "avg_price":
      case "today_price":
      case "avg_margin":
      case "profit_margin":
        return r[col.key] != null ? parseFloat(r[col.key]) : null;
      case "total_quantity":
        return r.total_quantity;
      case "total_revenue":
        return parseFloat(r.total_revenue);
      default:
        return "";
    }
  };

  // A row whose cells align to the visible columns: values placed by column
  // key, an optional label in the first visible column, blanks elsewhere.
  const alignedRow = (valuesByKey, firstColLabel) =>
    visibleCols.map((col, i) => {
      if (valuesByKey[col.key] !== undefined) return valuesByKey[col.key];
      return i === 0 && firstColLabel ? firstColLabel : "";
    });

  const headers = visibleCols.map((col) => col.label);
  const exportRows = filterShopifySalesResults(shopifySalesResults.results);
  const dataRows = sortShopifySalesResults(exportRows).map((r) =>
    visibleCols.map((col) => exportValue(col, r)),
  );

  const totalQty = exportRows.reduce((s, r) => s + r.total_quantity, 0);
  const totalRev = exportRows.reduce((s, r) => s + parseFloat(r.total_revenue), 0);
  const totalsRow = alignedRow({ total_quantity: totalQty, total_revenue: totalRev }, "Totals");

  const extraRows = [];
  const summary = shopifySalesResults.summary || {};
  const shippingTotal = parseFloat(summary.total_shipping || 0);
  if (shippingTotal > 0) {
    extraRows.push(alignedRow({ total_revenue: shippingTotal }, "Shipping Collected"));
  }
  const excludedProducts = summary.excluded_products || [];
  if (excludedProducts.length > 0) {
    const exclRev = parseFloat(summary.excluded_total_revenue || 0);
    const exclQty = summary.excluded_total_quantity || 0;
    extraRows.push(alignedRow({ total_quantity: exclQty, total_revenue: exclRev }, "Excluded Products"));
    excludedProducts.forEach((p) => {
      extraRows.push(alignedRow({ total_quantity: p.quantity, total_revenue: parseFloat(p.revenue) }, p.product_title));
    });
  }

  const wsData = [headers, ...dataRows, totalsRow, ...extraRows];
  const ws = XLSX.utils.aoa_to_sheet(wsData);

  const exportColWidths = {
    product_title: 55,
    barcode: 16,
    sku: 16,
    cost: 10,
    real_cost: 10,
    avg_price: 12,
    today_price: 12,
    avg_margin: 12,
    profit_margin: 10,
    total_quantity: 10,
    total_revenue: 14,
  };
  ws["!cols"] = visibleCols.map((col) => ({ wch: exportColWidths[col.key] || 12 }));

  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, "Shopify Sales");

  const startDate = document.getElementById("shopify-sales-start-date").value;
  const endDate = document.getElementById("shopify-sales-end-date").value;
  XLSX.writeFile(wb, `shopify-sales-${startDate}-to-${endDate}.xlsx`);
}

