// ===== Active users =====

let activeUsersTimer = null;

function isSettingsPageVisible() {
  const page = document.getElementById("settings-page");
  return !!page && page.style.display !== "none";
}

async function loadActiveUsers(showSpinner = true) {
  const loading = document.getElementById("active-users-loading");
  const empty = document.getElementById("active-users-empty");
  const results = document.getElementById("active-users-results");
  const tbody = document.getElementById("active-users-table-body");
  if (!loading || !empty || !results || !tbody) return;

  if (showSpinner) {
    loading.style.display = "block";
    empty.style.display = "none";
    results.style.display = "none";
  }

  let data;
  try {
    const resp = await fetch(`${API_BASE}/active-users`);
    if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
    data = await resp.json();
  } catch (error) {
    loading.style.display = "none";
    if (showSpinner) showToast(`✗ Failed to load active users: ${error.message}`, "error");
    return;
  }

  loading.style.display = "none";
  const users = data.users || [];
  if (users.length === 0) {
    empty.style.display = "block";
    results.style.display = "none";
    return;
  }

  empty.style.display = "none";
  results.style.display = "block";
  document.getElementById("active-users-count").textContent = String(users.length);
  const refreshedEl = document.getElementById("active-users-refreshed-at");
  if (refreshedEl) {
    refreshedEl.textContent = ` — as of ${new Date(data.refreshed_at).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", second: "2-digit" })}`;
  }

  tbody.innerHTML = users
    .map((u) => {
      const idle = formatDuration(u.idle_seconds);
      const dim = u.idle_seconds > 300;
      return `
        <tr${dim ? ' style="color: var(--text-tertiary)"' : ""}>
          <td>${escapeHtml(u.ip)}</td>
          <td>${escapeHtml(u.last_section || "—")}</td>
          <td>${formatDateTime(u.first_seen)}</td>
          <td>${formatDateTime(u.last_seen)}</td>
          <td>${escapeHtml(idle)}</td>
          <td>${Number(u.request_count).toLocaleString()}</td>
        </tr>`;
    })
    .join("");
}

function startActiveUsersAutoRefresh() {
  if (activeUsersTimer) return;
  activeUsersTimer = setInterval(() => {
    if (document.hidden || !isSettingsPageVisible()) return;
    loadActiveUsers(false);
  }, 30000);
}

document
  .getElementById("active-users-refresh")
  ?.addEventListener("click", () => loadActiveUsers(true));

// ===== QuickBooks Online settings =====
//
// Paste-back OAuth: "Connect" opens Intuit in a new tab; the user pastes the
// URL they land on (code/state/realmId) and the backend exchanges it. The
// connection row never returns the secret or tokens — only flags.

const qbState = { conn: null, accounts: [] };

function qbSetStatus(text, cls) {
  const el = document.getElementById("qb-status");
  if (!el) return;
  el.className = `test-status qb-status${cls ? ` ${cls}` : ""}`;
  el.textContent = text || "";
}

function qbFillForm(c) {
  const set = (id, v) => {
    const el = document.getElementById(id);
    if (el) el.value = v == null ? "" : String(v);
  };
  set("qb-client-id", c.client_id);
  set("qb-environment", c.environment || "production");
  set("qb-redirect-uri", c.redirect_uri);
  set("qb-refresh-minutes", c.refresh_minutes || 15);
  const secret = document.getElementById("qb-client-secret");
  if (secret) {
    secret.value = "";
    secret.placeholder = c.has_client_secret ? "•••••••• (unchanged)" : "Client secret";
  }
  const link = document.getElementById("qb-authorize-link");
  if (link && !c.pending_state) link.hidden = true;
}

function renderQuickBooksStatus() {
  const c = qbState.conn;
  const connectBtn = document.getElementById("qb-connect-btn");
  const disconnectBtn = document.getElementById("qb-disconnect-btn");
  const syncBtn = document.getElementById("qb-sync-now");
  const paste = document.getElementById("qb-paste-block");
  const acctWrap = document.getElementById("qb-accounts-wrap");
  if (!c) return;
  const connected = c.status === "connected";
  const needs = c.status === "needs_reconnect";
  if (connectBtn) {
    connectBtn.textContent = connected ? "Reconnect" : "Connect to QuickBooks";
    connectBtn.disabled = !c.configured || !c.redirect_uri;
    connectBtn.title = !c.configured
      ? "Save the Client ID and Client Secret first"
      : !c.redirect_uri ? "Save the Redirect URI first" : "";
  }
  if (disconnectBtn) disconnectBtn.hidden = !(connected || needs);
  if (syncBtn) syncBtn.hidden = !connected;
  if (paste) paste.hidden = !c.pending_state;
  if (acctWrap) acctWrap.hidden = !(connected || needs);
  const env = c.environment === "sandbox" ? "sandbox" : "production";
  if (c.pending_state) {
    qbSetStatus("Waiting for the pasted URL — approve in the QuickBooks tab, then paste the URL you land on below.", "loading");
  } else if (connected) {
    const parts = [`Connected to ${c.company_name || "QuickBooks company"}`, env, `realm ${c.realm_id || "—"}`];
    if (c.last_synced_at) parts.push(`balances synced ${formatRelative(c.last_synced_at)}`);
    if (c.refresh_token_expires_at) {
      parts.push(`refresh token valid until ${new Date(c.refresh_token_expires_at).toLocaleDateString()}`);
    }
    if (c.last_error) parts.push(`last error: ${c.last_error}`);
    qbSetStatus(parts.join(" · "), c.last_error ? "error" : "success");
  } else if (needs) {
    qbSetStatus(
      `Needs reconnect${c.company_name ? ` (${c.company_name})` : ""}: ${c.last_error || "the refresh token was rejected"}. Click Connect to QuickBooks and paste the new URL.`,
      "error",
    );
  } else if (!c.configured) {
    qbSetStatus("Not configured — enter the Intuit Client ID and Client Secret, then Save.", "loading");
  } else {
    qbSetStatus(`Not connected (${env}). Click Connect to QuickBooks.`, "loading");
  }
}

async function qbRequest(path, opts = {}) {
  const resp = await fetch(`${API_BASE}/quickbooks${path}`, {
    headers: { "Content-Type": "application/json" },
    ...opts,
  });
  let data = null;
  try {
    data = await resp.json();
  } catch {
    data = null;
  }
  if (!resp.ok) throw new Error((data && (data.detail || data.message)) || `HTTP ${resp.status}`);
  return data;
}

async function loadQuickBooksSettings() {
  if (!document.getElementById("qb-settings-card")) return;
  try {
    qbState.conn = await qbRequest("/connection");
    qbFillForm(qbState.conn);
    renderQuickBooksStatus();
    if (qbState.conn.status !== "disconnected") await loadQuickBooksAccounts();
    else renderQuickBooksAccounts([]);
  } catch (e) {
    qbSetStatus(`QuickBooks settings unavailable: ${e.message || e}`, "error");
  }
}

async function saveQuickBooksSettings(opts = {}) {
  const body = {
    client_id: (document.getElementById("qb-client-id")?.value || "").trim(),
    environment: document.getElementById("qb-environment")?.value || "production",
    redirect_uri: (document.getElementById("qb-redirect-uri")?.value || "").trim(),
    refresh_minutes: Number(document.getElementById("qb-refresh-minutes")?.value) || 15,
  };
  const secret = (document.getElementById("qb-client-secret")?.value || "").trim();
  if (secret) body.client_secret = secret;
  try {
    qbState.conn = await qbRequest("/connection", { method: "PUT", body: JSON.stringify(body) });
    qbFillForm(qbState.conn);
    renderQuickBooksStatus();
    if (qbState.conn.warning) {
      showToast(`⚠ ${qbState.conn.warning}`, "warning");
      renderQuickBooksAccounts([]);
      qbRefreshDashboard();
    } else if (!opts.quiet) {
      showToast("✓ QuickBooks settings saved", "success");
    }
    return true;
  } catch (e) {
    showToast(`✗ ${e.message || e}`, "error");
    return false;
  }
}

async function quickBooksConnectStart() {
  if (!(await saveQuickBooksSettings({ quiet: true }))) return;
  try {
    const data = await qbRequest("/connect/start", { method: "POST" });
    window.open(data.authorize_url, "_blank", "noopener");
    const link = document.getElementById("qb-authorize-link");
    if (link) {
      link.href = data.authorize_url;
      link.hidden = false;
    }
    qbState.conn = { ...qbState.conn, pending_state: true };
    renderQuickBooksStatus();
    const ta = document.getElementById("qb-callback-input");
    if (ta) {
      ta.value = "";
      ta.focus();
    }
  } catch (e) {
    showToast(`✗ ${e.message || e}`, "error");
  }
}

async function quickBooksConnectComplete() {
  const ta = document.getElementById("qb-callback-input");
  const text = (ta?.value || "").trim();
  if (!text) {
    showToast("Paste the URL from the QuickBooks tab first", "warning");
    ta?.focus();
    return;
  }
  const btn = document.getElementById("qb-connect-complete");
  if (btn) btn.disabled = true;
  qbSetStatus("Exchanging the authorization code with Intuit…", "loading");
  try {
    qbState.conn = await qbRequest("/connect/complete", {
      method: "POST",
      body: JSON.stringify({ callback: text }),
    });
    if (ta) ta.value = "";
    qbFillForm(qbState.conn);
    renderQuickBooksStatus();
    showToast(`✓ Connected to ${qbState.conn.company_name || "QuickBooks"}`, "success");
    await loadQuickBooksAccounts();
    qbRefreshDashboard();
  } catch (e) {
    qbSetStatus(`Connection failed: ${e.message || e}`, "error");
  } finally {
    if (btn) btn.disabled = false;
  }
}

async function quickBooksDisconnect() {
  if (!confirm("Disconnect QuickBooks? Cached balances are cleared; the app keys stay saved.")) return;
  try {
    qbState.conn = await qbRequest("/disconnect", { method: "POST" });
    qbFillForm(qbState.conn);
    renderQuickBooksStatus();
    renderQuickBooksAccounts([]);
    showToast("✓ QuickBooks disconnected", "success");
    qbRefreshDashboard();
  } catch (e) {
    showToast(`✗ ${e.message || e}`, "error");
  }
}

async function loadQuickBooksAccounts() {
  try {
    qbState.accounts = await qbRequest("/accounts");
  } catch {
    qbState.accounts = [];
  }
  renderQuickBooksAccounts(qbState.accounts);
}

function renderQuickBooksAccounts(accounts) {
  const el = document.getElementById("qb-accounts");
  const meta = document.getElementById("qb-accounts-meta");
  if (!el) return;
  const rows = accounts || [];
  if (meta) {
    const newest = rows.map((a) => a.synced_at).filter(Boolean).sort().slice(-1)[0];
    meta.textContent = rows.length
      ? `${rows.length} account${rows.length === 1 ? "" : "s"} · synced ${newest ? formatRelative(newest) : "—"}`
      : "";
  }
  if (!rows.length) {
    el.innerHTML = `<div class="settings-empty-state qb-accounts-empty">No bank or credit-card accounts synced yet.</div>`;
    return;
  }
  el.innerHTML = `<div class="qb-acct-list">${qbAccountsListHtml(rows)}</div>`;
}

// Grouped account rows (Bank / Credit cards) with a checkbox per account.
// Shared by the Settings card (immediate toggles) and the Business Overview
// settings modal (staged toggles via opts.hiddenOf).
function qbAccountsListHtml(accounts, opts = {}) {
  const hiddenOf = opts.hiddenOf || ((a) => !!a.hidden);
  const verb = opts.ariaVerb || "Show";
  const list = accounts || [];
  const groups = [["Bank", "Bank"], ["Credit Card", "Credit cards"]];
  const other = list.filter((a) => !groups.some(([t]) => t === a.account_type));
  if (other.length) groups.push([null, "Other"]);
  return groups
    .map(([type, label]) => {
      const rows = type ? list.filter((a) => a.account_type === type) : other;
      if (!rows.length) return "";
      const body = rows
        .map((a) => {
          const off = hiddenOf(a);
          const sub = `${a.account_sub_type || a.account_type}${a.currency && a.currency !== "USD" ? ` · ${a.currency}` : ""}`;
          return `<label class="qb-acct-row${off ? " is-off" : ""}${a.sub_account ? " is-sub" : ""}">` +
            `<input type="checkbox" data-qb-account="${escapeHtml(a.qbo_id)}"${off ? "" : " checked"} aria-label="${escapeHtml(verb)} ${escapeHtml(a.name)}">` +
            `<span class="qb-acct-main"><span class="qb-acct-name">${escapeHtml(a.name)}</span>${a.sub_account && a.fully_qualified_name ? `<span class="qb-acct-sub">${escapeHtml(a.fully_qualified_name)}</span>` : ""}</span>` +
            `<span class="qb-acct-type">${escapeHtml(sub)}</span>` +
            `<span class="qb-acct-bal bov-num${a.account_type === "Credit Card" ? " bov-bank-owed" : ""}">${escapeHtml(formatCurrency(a.balance || 0))}</span>` +
            `</label>`;
        })
        .join("");
      return `<div class="qb-acct-group"><div class="qb-acct-group-title">${escapeHtml(label)} <span>${rows.length}</span></div>${body}</div>`;
    })
    .join("");
}

async function toggleQuickBooksAccountHidden(qboId, hidden) {
  try {
    const updated = await qbRequest(`/accounts/${encodeURIComponent(qboId)}`, {
      method: "PATCH",
      body: JSON.stringify({ hidden }),
    });
    qbState.accounts = qbState.accounts.map((a) => (a.qbo_id === qboId ? updated : a));
    renderQuickBooksAccounts(qbState.accounts);
    qbRefreshDashboard();
  } catch (e) {
    showToast(`✗ ${e.message || e}`, "error");
    renderQuickBooksAccounts(qbState.accounts);
  }
}

async function quickBooksSyncNow() {
  const btn = document.getElementById("qb-sync-now");
  if (btn) btn.disabled = true;
  try {
    const block = await qbRequest("/sync", { method: "POST" });
    if (block.error) showToast(`⚠ QuickBooks sync: ${block.error}`, "warning");
    else showToast(`✓ Synced ${(block.accounts || []).length} QuickBooks account(s)`, "success");
    await loadQuickBooksSettings();
    qbRefreshDashboard(block);
  } catch (e) {
    showToast(`✗ ${e.message || e}`, "error");
  } finally {
    if (btn) btn.disabled = false;
  }
}

// Keep the Business Overview widget in step with Settings changes.
function qbRefreshDashboard(block) {
  if (!bovState.bound) return;
  if (block && bovState.widgets.bankBalances) {
    const w = bovState.widgets.bankBalances;
    w.data = block;
    w.error = null;
    w.loadedAt = Date.now();
    bovRenderBankBalances();
  } else {
    bovFetchAll({ only: ["bankBalances"], silent: true });
  }
}

document.getElementById("qb-settings-save")?.addEventListener("click", () => saveQuickBooksSettings());
document.getElementById("qb-connect-btn")?.addEventListener("click", quickBooksConnectStart);
document.getElementById("qb-connect-complete")?.addEventListener("click", quickBooksConnectComplete);
document.getElementById("qb-disconnect-btn")?.addEventListener("click", quickBooksDisconnect);
document.getElementById("qb-sync-now")?.addEventListener("click", quickBooksSyncNow);
document.getElementById("qb-accounts")?.addEventListener("change", (e) => {
  const cb = e.target.closest("input[data-qb-account]");
  if (cb) toggleQuickBooksAccountHidden(cb.dataset.qbAccount, !cb.checked);
});

// ============================================================================
// Shopify Data Sync (Shopify Analytics > Data Sync)
//
// Per-store local mirror of Shopify customers + orders. Cards show the last
// successful sync and live progress; the report pages consult the same status
// endpoint to decide whether a run will use local data or the live API.
// ============================================================================

const syncState = {
  stores: [],
  loaded: false,
  running: {}, // store_id -> { abort, phase, detail, objectCount, upserted, lineItems }
};

async function fetchSyncStatus() {
  // Raw fetch, not apiRequest: apiRequest alert()s on failure, and this is
  // polled on every Lost Customers visit / store change where callers degrade
  // silently by design — a backend blip must not produce a modal.
  const response = await fetch(`${API_BASE}/shopify-sync/status`);
  if (!response.ok) throw new Error(`HTTP ${response.status}`);
  const data = await response.json();
  syncState.stores = data.stores || [];
  syncState.loaded = true;
  return syncState.stores;
}

function syncTimeAgo(iso) {
  if (!iso) return "";
  const then = new Date(iso).getTime();
  if (!isFinite(then)) return "";
  const mins = Math.floor((Date.now() - then) / 60000);
  if (mins < 1) return "just now";
  if (mins < 60) return `${mins}m ago`;
  const hours = Math.floor(mins / 60);
  if (hours < 24) return `${hours}h ago`;
  return `${Math.floor(hours / 24)}d ago`;
}

function loadDataSyncPanel() {
  const list = document.getElementById("sync-store-list");
  if (!list) return;
  if (!list.dataset.bound) {
    list.dataset.bound = "1";
    list.addEventListener("click", (e) => {
      const btn = e.target.closest("button[data-sync-action]");
      if (!btn) return;
      const storeId = parseInt(btn.dataset.storeId, 10);
      const action = btn.dataset.syncAction;
      if (action === "sync") {
        startSync(storeId, "incremental");
      } else if (action === "full") {
        if (
          confirm(
            "Full resync re-downloads this store's entire history and can take a while. Continue?",
          )
        ) {
          startSync(storeId, "full");
        }
      } else if (action === "cancel") {
        cancelSync(storeId);
      }
    });
    document
      .getElementById("sync-refresh-btn")
      ?.addEventListener("click", () => loadDataSyncPanel());
  }
  fetchSyncStatus()
    .then(renderSyncStores)
    .catch((e) => {
      list.innerHTML = `<p style="color: var(--danger); font-size: 0.8125rem;">Failed to load sync status: ${escapeHtml(e.message)}</p>`;
    });
}

function syncProgressText(entry) {
  const bits = [];
  if (entry.detail) bits.push(entry.detail);
  if (entry.objectCount != null)
    bits.push(`${entry.objectCount.toLocaleString()} exported`);
  if (entry.upserted != null)
    bits.push(`${entry.upserted.toLocaleString()} saved`);
  if (entry.lineItems != null)
    bits.push(`${entry.lineItems.toLocaleString()} line items`);
  return bits.join(" · ") || "Working…";
}

function updateSyncProgressLine(storeId) {
  const el = document.getElementById(`sync-progress-${storeId}`);
  const entry = syncState.running[storeId];
  if (el && entry) el.textContent = syncProgressText(entry);
}

function renderSyncStores() {
  const list = document.getElementById("sync-store-list");
  if (!list) return;
  if (!syncState.stores.length) {
    list.innerHTML =
      '<p style="color: var(--text-secondary); font-size: 0.8125rem;">No Shopify stores configured.</p>';
    return;
  }
  list.innerHTML = syncState.stores
    .map((s) => {
      const mine = syncState.running[s.store_id];
      const runningElsewhere = !mine && s.status === "running";
      let statusHtml;
      if (mine) {
        statusHtml = `
          <div class="sync-running-row">
            <span class="sync-spinner"></span>
            <span class="sync-progress-line" id="sync-progress-${s.store_id}">${escapeHtml(syncProgressText(mine))}</span>
          </div>`;
      } else if (runningElsewhere) {
        statusHtml = `
          <div class="sync-running-row">
            <span class="sync-spinner"></span>
            <span class="sync-progress-line">Sync in progress (started from another session)</span>
          </div>`;
      } else if (s.last_completed_at) {
        const counts = [
          `${(s.customers_count || 0).toLocaleString()} customers`,
          `${(s.orders_count || 0).toLocaleString()} orders`,
          `${(s.line_items_count || 0).toLocaleString()} line items`,
        ].join(" · ");
        statusHtml = `
          <div class="sync-status-line">
            <span class="sync-badge sync-badge-ok">Synced ${escapeHtml(syncTimeAgo(s.last_completed_at) || "recently")}</span>
            <span style="color: var(--text-secondary);">${counts}</span>
          </div>`;
      } else {
        statusHtml = `
          <div class="sync-status-line">
            <span class="sync-badge sync-badge-never">Never synced</span>
            <span style="color: var(--text-secondary);">Reports use the live Shopify API for this store</span>
          </div>`;
      }
      const errorHtml =
        !mine && s.status === "error" && s.error && s.error !== "cancelled"
          ? `<div class="sync-error-line">Last sync failed: ${escapeHtml(s.error)}</div>`
          : "";
      // Inactive stores are excluded from every report (including cross-store
      // checks), so syncing one is wasted API work — activate it first.
      const busy = Boolean(mine || runningElsewhere) || !s.is_active;
      const buttons = mine
        ? `<button type="button" class="btn btn-secondary sync-btn" data-sync-action="cancel" data-store-id="${s.store_id}">Cancel</button>`
        : `
          <button type="button" class="btn btn-primary sync-btn" data-sync-action="sync" data-store-id="${s.store_id}" ${busy ? "disabled" : ""}>
            ${s.last_completed_at ? "Sync" : "Sync now"}
          </button>
          <button type="button" class="btn btn-secondary sync-btn" data-sync-action="full" data-store-id="${s.store_id}" ${busy || !s.last_completed_at ? "disabled" : ""}${!s.last_completed_at ? ' title="The first sync is always a full download - use Sync now. Full resync becomes available after it completes."' : ""}>
            Full resync
          </button>`;
      return `
        <div class="sync-store-card${s.is_active ? "" : " sync-store-inactive"}">
          <div class="sync-store-head">
            <span class="sync-store-name">${escapeHtml(s.name)}${s.is_active ? "" : ' <span class="sync-badge sync-badge-never">inactive</span>'}</span>
            <div class="sync-store-actions">${buttons}</div>
          </div>
          ${statusHtml}
          ${errorHtml}
        </div>`;
    })
    .join("");
}

async function startSync(storeId, mode) {
  if (syncState.running[storeId]) return;
  const abort = new AbortController();
  syncState.running[storeId] = { abort, phase: "starting", detail: "Starting…" };
  renderSyncStores();
  try {
    const response = await fetch(`${API_BASE}/shopify-sync/${storeId}/stream`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ mode }),
      signal: abort.signal,
    });
    if (!response.ok) {
      let msg = `HTTP ${response.status}`;
      try {
        const j = await response.json();
        if (typeof j.detail === "string") {
          msg = j.detail;
        } else if (Array.isArray(j.detail)) {
          // FastAPI 422 validation shape: [{loc, msg, type}, ...]
          msg = j.detail.map((d) => d.msg || "").filter(Boolean).join("; ") || msg;
        } else {
          msg = j.error?.message || msg;
        }
      } catch (e) {
        /* not json */
      }
      throw new Error(msg);
    }
    const reader = response.body.getReader();
    const decoder = new TextDecoder();
    let buffer = "";
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      buffer += decoder.decode(value, { stream: true });
      const messages = buffer.split("\n\n");
      buffer = messages.pop();
      for (const raw of messages) {
        const msg = raw.trim();
        if (!msg || msg.startsWith(":")) continue;
        const match = msg.match(/event: (\w+)\ndata: (.+)/s);
        if (!match) continue;
        let data;
        try {
          data = JSON.parse(match[2]);
        } catch (e) {
          continue;
        }
        handleSyncEvent(storeId, match[1], data);
      }
    }
  } catch (err) {
    if (err.name !== "AbortError") {
      showToast(`✗ Sync failed: ${err.message}`, "error");
    }
  } finally {
    const wasAborted = abort.signal.aborted;
    delete syncState.running[storeId];
    renderSyncStores();
    if (wasAborted) {
      // The backend releases the claim asynchronously after the disconnect
      // lands; an immediate refetch can still see "running" and briefly show
      // the just-cancelled card as a sync from another session.
      setTimeout(() => {
        loadDataSyncPanel();
        sacrUpdateDataSourceNote();
      }, 800);
    } else {
      loadDataSyncPanel();
      // A sync finishing changes what the Lost Customers panel should say the
      // next run will use — refresh the note even if the user is sitting there.
      sacrUpdateDataSourceNote();
    }
  }
}

function handleSyncEvent(storeId, type, data) {
  const entry = syncState.running[storeId];
  if (type === "progress") {
    if (!entry) return;
    entry.phase = data.phase || entry.phase;
    if (data.detail) entry.detail = data.detail;
    if (data.object_count != null) entry.objectCount = data.object_count;
    if (data.upserted != null) entry.upserted = data.upserted;
    if (data.line_items != null) entry.lineItems = data.line_items;
    updateSyncProgressLine(storeId);
  } else if (type === "complete") {
    const totals = data.totals || {};
    showToast(
      `✓ Sync complete — ${(totals.customers || 0).toLocaleString()} customers, ${(totals.orders || 0).toLocaleString()} orders`,
      "success",
    );
  } else if (type === "error") {
    showToast(`✗ Sync failed: ${data.message || "unknown error"}`, "error");
  }
}

function cancelSync(storeId) {
  const entry = syncState.running[storeId];
  if (entry?.abort) entry.abort.abort();
}

// Data-source note on the Lost Customers panel: tells the user before they run
// whether this store will be served from local synced data or the live API.
async function sacrUpdateDataSourceNote() {
  const el = document.getElementById("sacr-data-source");
  if (!el) return;
  try {
    await fetchSyncStatus();
  } catch (e) {
    el.textContent = "";
    return;
  }
  const ids = sacrSelectedStoreIds();
  if (!ids.length) {
    el.textContent = "";
    return;
  }
  const byId = new Map(syncState.stores.map((s) => [s.store_id, s]));
  const sel = byId.get(ids[0]);
  const unsyncedOthers = syncState.stores.filter(
    (s) => s.is_active && !s.last_completed_at && s.store_id !== ids[0],
  ).length;
  if (sel?.last_completed_at) {
    let txt = `Local data — synced ${syncTimeAgo(sel.last_completed_at)}`;
    if (unsyncedOthers) {
      txt += ` · ${unsyncedOthers} other store(s) not synced; cross-store checks use the Shopify API for them`;
    }
    el.innerHTML = `<span style="color: var(--success);">●</span> ${escapeHtml(txt)}`;
  } else {
    el.innerHTML =
      `<span style="color: var(--warning);">●</span> ` +
      escapeHtml(
        "Not synced — this report will use the live Shopify API. Sync this store in the Data Sync tab for faster, more reliable runs.",
      );
  }
}

