// ---------------------------------------------------------------------------
// Ops card: purchase orders
// ---------------------------------------------------------------------------

function bovRenderPurchases() {
  const body = document.getElementById("bov-purchases-body");
  const meta = document.getElementById("bov-purchases-meta");
  const foot = document.getElementById("bov-purchases-foot");
  if (!body) return;
  const tab = bovState.tabs.purchases;
  const key = bovActivePurchasesKey();
  const w = bovState.widgets[key];
  const inc = bovState.widgets.purchasesIncoming.data;
  const pur = bovState.widgets.purchasesPurchased.data;
  const rec = bovState.widgets.purchasesReceived.data;
  const setCount = (id, v) => { const el = document.getElementById(id); if (el) el.textContent = v; };
  setCount("bov-tab-count-incoming", inc && inc.configured && !inc.error ? bovInt(inc.count || 0) : "");
  setCount("bov-tab-count-purchased", pur && pur.configured && !pur.error ? bovInt(pur.count || 0) : "");
  setCount("bov-tab-count-received", rec && rec.configured && !rec.error && rec.totals ? bovInt((rec.totals.current || {}).purchase_orders || 0) : "");
  document.querySelectorAll('[data-bov-tab="purchases"]').forEach((b) => b.classList.toggle("active", b.dataset.value === tab));
  const purchasedBtn = document.querySelector('[data-bov-tab="purchases"][data-value="purchased"]');
  if (purchasedBtn) purchasedBtn.hidden = !!bovState.widgets.purchasesPurchased.unsupported;

  if (!w.data && !w.error) {
    if (!w.loading) bovPaintSkeleton(key);
    return;
  }
  if (foot) foot.innerHTML = "";
  if (w.error && !w.data) {
    body.innerHTML = bovInlineErrorHtml(key, w.error, "Purchase orders could not load");
    if (meta) meta.textContent = "";
    return;
  }
  const d = w.data;
  if (!d.configured) {
    body.innerHTML = bovUnconfiguredHtml("Purchases source not set", "Pick the BackOffice store that holds the purchase orders.", "config");
    if (meta) meta.textContent = "";
    return;
  }
  if (d.filtered_out) {
    body.innerHTML = bovFilteredOutHtml();
    if (meta) meta.textContent = "";
    return;
  }
  if (d.error) {
    body.innerHTML = bovInlineErrorHtml(key, d.error, "Purchase orders unavailable");
    if (meta) meta.textContent = d.store_name ? `Source: ${d.store_name}` : "";
    return;
  }
  const allRows = d.purchase_orders || [];
  const rows = bovApplyCardFilters("purchases", allRows, {
    storeOf: (r) => r.store_name || d.store_name || "",
    searchFields: ["po_number", "business_name", "account_no"],
  });
  const filtersOn = bovCardFiltersActive("purchases");
  const sourceFoot = d.store_name ? `Source: ${escapeHtml(d.store_name)}` : "";
  let cols;
  let sortKey;
  if (tab === "incoming") {
    sortKey = "purchasesIncoming";
    if (meta) meta.textContent = `${bovInt(d.count || 0)} open · ${bovCompactMoney(d.outstanding_value || 0)} outstanding · ${bovInt(d.qty_outstanding || 0)} units · still waiting on goods (any PO date)`;
    if (!rows.length) {
      body.innerHTML = bovEmptyHtml(filtersOn ? "No purchase orders match the filters." : "No open purchase orders.");
      if (foot) foot.innerHTML = `<span class="bov-foot-left">${sourceFoot}</span>`;
      return;
    }
    cols = bovPoCols("incoming");
  } else if (tab === "purchased") {
    sortKey = "purchasesPurchased";
    if (meta) meta.textContent = `${bovInt(d.count || 0)} placed · ${bovCompactMoney(d.po_total || 0)} · awaiting vendor confirmation (any PO date)`;
    if (!rows.length) {
      body.innerHTML = bovEmptyHtml(filtersOn ? "No purchase orders match the filters." : "No purchase orders awaiting vendor confirmation.");
      return;
    }
    cols = bovPoCols("purchased");
  } else {
    sortKey = "purchasesReceived";
    const cur = (d.totals && d.totals.current) || {};
    const prv = (d.totals && d.totals.previous) || {};
    if (meta) meta.textContent = `${bovInt(cur.purchase_orders || 0)} PO with goods received in period · ${bovInt(cur.qty || 0)} units · ${bovCompactMoney(cur.value || 0)}${prv.value != null ? ` · prev ${bovCompactMoney(prv.value || 0)}` : ""}`;
    if (!rows.length) {
      body.innerHTML = bovEmptyHtml(filtersOn ? "No purchase orders match the filters." : "Nothing received in this period.");
      return;
    }
    cols = bovPoCols("received");
  }
  const sorted = bovSortRows(rows, bovState.sort[sortKey]);
  const shown = sorted;  // every row is shown; the card body scrolls
  body.innerHTML = bovTableHtml(sortKey, cols, shown, { rowAttrs: bovPoRowAttrs });
  if (foot) foot.innerHTML = bovFootHtml("purchases", rows.length, shown.length, sourceFoot);
}

function bovPoRowAttrs(r) {
  return `data-bov-open="po" data-bov-id="${r.po_id}"`;
}

function bovPoCols(tab) {
  if (tab === "incoming") {
    return [
      { key: "po_number", label: "PO #", width: "16%", render: (r) => `<span class="bov-cell-mono">${escapeHtml(r.po_number || String(r.po_id))}</span>` },
      { key: "business_name", label: "Supplier", width: "32%", render: (r) => bovCustomerCell(r.business_name, r.account_no) },
      { key: "po_date", label: "Ordered", width: "14%", render: (r) => escapeHtml(bovDateMdy(r.po_date)) },
      { key: "qty_outstanding", label: "Outstanding", num: true, width: "14%", render: (r) => `${bovInt(r.qty_outstanding)}<span class="bov-cell-sub">of ${bovInt(r.tot_qty_ord)}</span>` },
      { key: "outstanding_value", label: "Open $", num: true, width: "12%", render: (r) => bovMoney(r.outstanding_value) },
      { key: "po_total", label: "PO total", num: true, width: "12%", render: (r) => bovMoney(r.po_total) },
    ];
  }
  if (tab === "purchased") {
    return [
      { key: "po_number", label: "PO #", width: "16%", render: (r) => `<span class="bov-cell-mono">${escapeHtml(r.po_number || String(r.po_id))}</span>` },
      { key: "business_name", label: "Supplier", width: "34%", render: (r) => bovCustomerCell(r.business_name, r.account_no) },
      { key: "po_date", label: "Ordered", width: "14%", render: (r) => escapeHtml(bovDateMdy(r.po_date)) },
      { key: "required_date", label: "Required by", width: "12%", render: (r) => escapeHtml(r.required_date ? bovDateMdy(r.required_date) : "—") },
      { key: "tot_qty_ord", label: "Qty", num: true, width: "10%", render: (r) => bovInt(r.tot_qty_ord) },
      { key: "po_total", label: "Total", num: true, width: "14%", render: (r) => bovMoney(r.po_total) },
    ];
  }
  const poState = (r) => {
    const outstanding = Math.max(0, bovNum(r.tot_qty_ord) - bovNum(r.tot_qty_rcv));
    if (r.status === 1 || outstanding <= 0) return `<span class="qip-status-chip complete">Complete</span>`;
    return `<span class="qip-status-chip picking" title="${bovInt(outstanding)} still outstanding — also listed under Incoming">Partial · ${bovInt(outstanding)} left</span>`;
  };
  return [
    { key: "po_number", label: "PO #", width: "14%", render: (r) => `<span class="bov-cell-mono">${escapeHtml(r.po_number || String(r.po_id))}</span>` },
    { key: "business_name", label: "Supplier", width: "28%", render: (r) => bovCustomerCell(r.business_name, r.account_no) },
    { key: "last_received", label: "Received", width: "12%", render: (r) => escapeHtml(bovDateMdy(r.last_received)) },
    { key: "status", label: "PO state", width: "14%", render: poState },
    { key: "qty_received", label: "Qty in period", num: true, width: "12%", render: (r) => `${bovInt(r.qty_received)}<span class="bov-cell-sub">of ${bovInt(r.tot_qty_ord)} ordered</span>` },
    { key: "received_value", label: "Value", num: true, width: "10%", render: (r) => bovMoney(r.received_value) },
    { key: "po_total", label: "PO total", num: true, width: "10%", render: (r) => bovMoney(r.po_total) },
  ];
}

// ---------------------------------------------------------------------------
// Full-list modal (shared by the three ops cards)
// ---------------------------------------------------------------------------

function bovSourceDbLabel(sourceDb) {
  const raw = (sourceDb || "").trim();
  if (!raw) return "";
  const opts = (bovState.options && bovState.options.mssql_stores) || [];
  const hit = opts.find((s) => s.database_name && String(s.database_name).toLowerCase() === raw.toLowerCase());
  return hit ? hit.name : raw;
}

function bovSetTrendCollapsedSub() {
  const subEl = document.getElementById("bov-trend-sub");
  if (subEl) subEl.textContent = "Revenue, cost, profit and margin over the selected period — open the charts to see the trend.";
  const legend = document.getElementById("bov-trend-legend");
  if (legend) legend.innerHTML = "";
}

function bovSetChartsOpen(open) {
  bovState.chartsOpen = !!open;
  bovSavePrefs();
  const page = document.getElementById("business-overview-page");
  if (page) page.classList.toggle("is-charts-open", bovState.chartsOpen);
  const btn = document.getElementById("bov-charts-toggle");
  if (btn) {
    btn.textContent = bovState.chartsOpen ? "Hide charts" : "Show charts";
    btn.setAttribute("aria-expanded", bovState.chartsOpen ? "true" : "false");
  }
  if (bovState.chartsOpen) {
    const w = bovState.widgets.trend;
    if (!w.data && !w.loading) bovFetchAll({ only: ["trend"] });
    else bovScheduleChartRender();
  } else {
    bovSetTrendCollapsedSub();
  }
}

// ---------------------------------------------------------------------------
// Drill-in modals
// ---------------------------------------------------------------------------

function bovOpenRow(rowEl) {
  const kind = rowEl.dataset.bovOpen;
  const id = rowEl.dataset.bovId;
  if (!kind || id == null) return;
  if (kind === "invoice" || kind === "shopify-order") {
    // Month End rows carry data-me-key → enable Prev/Next + the viewed-row highlight.
    monthEndState.navActive = !!rowEl.dataset.meKey;
    if (rowEl.dataset.meKey) {
      monthEndState.viewedKey = rowEl.dataset.meKey;
      meApplyViewedHighlight();
    }
  }
  if (kind === "quotation") bovOpenQuotationModal(id);
  else if (kind === "product") bovOpenProductModal(parseInt(id, 10));
  else if (kind === "invoice") bovOpenInvoiceModal(parseInt(id, 10), rowEl.dataset.bovStore ? parseInt(rowEl.dataset.bovStore, 10) : null);
  else if (kind === "po") bovOpenPoModal(parseInt(id, 10));
  else if (kind === "shopify-order") {
    // Month End rows carry the order's real shipping cost from shipper parcels.
    const ctx = rowEl.dataset.meShipCost != null || rowEl.dataset.meShipMissing != null
      ? { shipping_cost: rowEl.dataset.meShipCost != null ? parseFloat(rowEl.dataset.meShipCost) : null,
          parcels: rowEl.dataset.meParcels != null ? parseInt(rowEl.dataset.meParcels, 10) : null,
          shipping_missing: rowEl.dataset.meShipMissing === "1",
          estimated: rowEl.dataset.meShipEst === "1" }
      : null;
    bovOpenShopifyOrderModal(parseInt(rowEl.dataset.bovStore, 10), id, ctx);
  }
  if (kind === "invoice" || kind === "shopify-order") meUpdateModalNav();
}

function bovKv(label, valueHtml) {
  return `<div class="bov-kv"><span class="bov-kv-label">${escapeHtml(label)}</span><span class="bov-kv-value">${valueHtml == null || valueHtml === "" ? "—" : valueHtml}</span></div>`;
}

function bovModalLoading(bodyEl, text) {
  bodyEl.innerHTML = `<p class="bov-modal-note">${escapeHtml(text || "Loading…")}</p>`;
}

function bovModalError(bodyEl, message) {
  bodyEl.innerHTML = `<p class="bov-modal-note bov-modal-error">${escapeHtml(message || "Could not load")}</p>`;
}

async function bovOpenQuotationModal(quotationNumber) {
  const title = document.getElementById("bov-quotation-title");
  const body = document.getElementById("bov-quotation-body");
  if (!body) return;
  const row = ((bovState.widgets.quotations.data || {}).quotations || []).find((q) => q.quotation_number === quotationNumber) || {};
  if (title) title.textContent = `Quotation ${quotationNumber}${row.business_name ? ` — ${row.business_name}` : ""}`;
  openModal("bov-quotation-modal");
  const cache = bovState.modalCache.quotation;
  const cacheKey = `${bovCostParams().cost_mode}:${quotationNumber}`;
  if (cache.has(cacheKey)) {
    bovRenderQuotationModal(cache.get(cacheKey), row, quotationNumber);
    return;
  }
  bovModalLoading(body, "Loading quotation…");
  try {
    const resp = await fetch(`${API_BASE}/quotations/in-progress/${encodeURIComponent(quotationNumber)}/products?cost_mode=${encodeURIComponent(bovCostParams().cost_mode)}`);
    if (!resp.ok) {
      let detail = `HTTP ${resp.status}`;
      try { detail = (await resp.json()).detail || detail; } catch (e) { /* keep */ }
      throw new Error(detail);
    }
    const data = await resp.json();
    cache.set(cacheKey, data);
    bovRenderQuotationModal(data, row, quotationNumber);
  } catch (e) {
    bovModalError(body, `Could not load this quotation: ${e.message || e}`);
  }
}

function bovRenderQuotationModal(data, row, quotationNumber) {
  const body = document.getElementById("bov-quotation-body");
  if (!body) return;
  const h = data.header || {};
  const products = data.products || [];
  const status = h.status || row.status;
  const total = h.quotation_total != null && h.quotation_total !== "" ? parseFloat(String(h.quotation_total).replace(/[^0-9.-]/g, "")) : row.quotation_total;
  const shipTo = [h.shipto, h.ship_address1, h.ship_address2, [h.ship_city, h.ship_state, h.ship_zip_code].filter(Boolean).join(" ")].filter((x) => x && String(x).trim()).join(", ");
  const kv = [
    bovKv("Customer", `${escapeHtml(h.business_name || row.business_name || "—")}${(h.account_no || row.account_no) ? `<span class="bov-cell-sub">${escapeHtml(h.account_no || row.account_no)}</span>` : ""}`),
    bovKv("Sales rep", escapeHtml(h.sales_rep || row.sales_rep || "—")),
    bovKv("Status", `${bovStatusChip(status)}${h.user_status ? ` <span class="bov-cell-sub">${escapeHtml(h.user_status)}</span>` : ""}`),
    bovKv("Source", escapeHtml(h.source_db || row.source_db || "—")),
    bovKv("Packer", escapeHtml(h.packer || row.packer || "—")),
    bovKv("Checker", escapeHtml(h.checker || row.checker || "—")),
    bovKv("Started", escapeHtml(bovDateTime(row.start_date))),
    bovKv("Scan-in / out", `${escapeHtml(h.dop2 && String(h.dop2).trim() ? h.dop2 : "—")} / ${escapeHtml(h.dop3 && String(h.dop3).trim() ? h.dop3 : "—")}`),
    bovKv("Quotation total", escapeHtml(isFinite(total) && total != null ? formatCurrency(total) : "—")),
    bovKv("Total qty", escapeHtml(bovInt(h.total_qty != null ? h.total_qty : row.total_qty))),
    bovKv("Invoice #", escapeHtml(h.invoice_number || row.invoice_number || "—")),
    bovKv("Ship to", escapeHtml(shipTo || "—")),
  ].join("");

  let sumQty = 0;
  let sumCost = 0;
  let sumPrice = 0;
  const lines = products.map((p) => {
    const qty = bovNum(p.qty);
    const cost = p.unit_cost != null ? bovNum(p.unit_cost) : null;
    const price = p.price != null ? bovNum(p.price) : null;
    const lineTotal = price != null ? price * qty : null;
    const lineCost = cost != null ? cost * qty : null;
    sumQty += qty;
    if (lineCost != null) sumCost += lineCost;
    if (lineTotal != null) sumPrice += lineTotal;
    const margin = lineTotal && lineCost != null && lineTotal > 0 ? ((lineTotal - lineCost) / lineTotal) * 100 : null;
    return `<tr><td><span class="bov-cell-main">${escapeHtml(p.product_description || "—")}</span><span class="bov-cell-sub bov-cell-mono">${escapeHtml([p.product_sku, p.product_upc].filter(Boolean).join(" · "))}</span></td><td class="bov-num">${bovInt(qty)}</td><td class="bov-num">${cost != null ? bovMoney(cost) : "—"}</td><td class="bov-num">${price != null ? bovMoney(price) : "—"}</td><td class="bov-num">${lineTotal != null ? bovMoney(lineTotal) : "—"}</td><td class="bov-num">${margin != null ? bovPct(margin) : "—"}</td></tr>`;
  }).join("");
  const marginTot = sumPrice > 0 ? ((sumPrice - sumCost) / sumPrice) * 100 : null;
  const basis = {
    sale: { label: "Stamped cost", note: "Price and cost come from the quotation's own lines in the source store (blank/$0 line cost → its current Items_tbl.UnitCost)." },
    current: { label: "Current cost", note: "Price is the quoted price from the source store; cost is that store's Items_tbl.UnitCost today." },
    s2s: { label: "S2S cost", note: "Price is the quoted price from the source store; cost is S2S Items_tbl.UnitCost." },
  }[bovCostParams().cost_mode] || { label: "Unit cost", note: "" };
  body.innerHTML =
    `<div class="bov-kv-grid">${kv}</div>` +
    (products.length
      ? `<div class="bov-table-scroll"><table class="data-table bov-mini-table bov-modal-table"><thead><tr><th style="width:44%">Product</th><th class="bov-num" style="width:9%">Qty</th><th class="bov-num" style="width:12%">${escapeHtml(basis.label)}</th><th class="bov-num" style="width:12%">Price</th><th class="bov-num" style="width:13%">Line total</th><th class="bov-num" style="width:10%">Margin</th></tr></thead><tbody>${lines}</tbody><tfoot><tr><td>${bovInt(products.length)} lines</td><td class="bov-num">${bovInt(sumQty)}</td><td class="bov-num">${sumCost ? bovMoney(sumCost) : "—"}</td><td></td><td class="bov-num">${sumPrice ? bovMoney(sumPrice) : "—"}</td><td class="bov-num">${marginTot != null ? bovPct(marginTot) : "—"}</td></tr></tfoot></table></div>${basis.note ? `<p class="bov-modal-note">${escapeHtml(basis.note)}</p>` : ""}`
      : `<p class="bov-modal-note">No products on this quotation.</p>`);
}

async function bovOpenInvoiceModal(invoiceId, storeId) {
  const title = document.getElementById("bov-invoice-title");
  const body = document.getElementById("bov-invoice-body");
  if (!body) return;
  if (title) title.textContent = `Invoice`;
  openModal("bov-invoice-modal");
  // InvoiceID is only unique within one BackOffice DB — key the cache and the
  // request by store when several sales stores are selected.
  const ids = bovSalesStoreIds();
  const sid = storeId != null ? storeId : (ids.length === 1 ? ids[0] : null);
  const cacheKey = `${sid == null ? "" : sid}:${invoiceId}`;
  const cache = bovState.modalCache.invoice;
  if (cache.has(cacheKey)) {
    bovRenderInvoiceModal(cache.get(cacheKey));
    return;
  }
  bovModalLoading(body, "Loading invoice…");
  try {
    const data = await bovFetchJson(`/invoices/${invoiceId}`, { ...(sid != null ? { store_id: sid } : {}), ...bovCostParams() });
    cache.set(cacheKey, data);
    bovRenderInvoiceModal(data);
  } catch (e) {
    bovModalError(body, `Could not load this invoice: ${e.message || e}`);
  }
}

function bovRenderInvoiceModal(data) {
  const title = document.getElementById("bov-invoice-title");
  const body = document.getElementById("bov-invoice-body");
  if (!body) return;
  bovState.invoiceModalData = data;
  const h = data.header || {};
  const lines = data.lines || [];
  if (title) title.textContent = `Invoice ${h.invoice_number || h.invoice_id || ""}${h.business_name ? ` — ${h.business_name}` : ""}${data.store_name && bovSalesStoreIds().length > 1 ? ` · ${data.store_name}` : ""}`;
  const shipTo = [h.ship_to, h.ship_address1, h.ship_address2, [h.ship_city, h.ship_state, h.ship_zip_code].filter(Boolean).join(" ")].filter((x) => x && String(x).trim()).join(", ");
  const statusChip = h.void
    ? `<span class="qip-status-chip pending">Void</span>`
    : h.is_shipped
      ? `<span class="qip-status-chip complete">Shipped</span>`
      : `<span class="qip-status-chip picking">Open</span> ${bovAgeChip(h.age_days)}`;
  const kv = [
    bovKv("Customer", `${escapeHtml(h.business_name || "—")}${h.account_no ? `<span class="bov-cell-sub">${escapeHtml(h.account_no)}</span>` : ""}`),
    bovKv("Sales rep", escapeHtml(h.sales_rep || "—")),
    bovKv("Status", statusChip),
    bovKv("Invoice date", escapeHtml(bovDateMdy(h.invoice_date))),
    bovKv("Ship date", escapeHtml(h.ship_date ? bovDateMdy(h.ship_date) : "—")),
    bovKv("Shipper", escapeHtml(h.shipper || "—")),
    bovKv("Tracking", h.tracking_no ? `<span class="bov-cell-mono">${escapeHtml(h.tracking_no)}</span>` : "—"),
    bovKv("PO #", escapeHtml(h.po_number || "—")),
    bovKv("Terms", escapeHtml(h.term || "—")),
    bovKv("Ship to", escapeHtml(shipTo || "—")),
    bovKv("Boxes / weight", `${h.no_boxes != null ? bovInt(h.no_boxes) : "—"} / ${h.total_weight != null ? bovNum(h.total_weight).toLocaleString() : "—"}`),
    bovKv("Subtotal", escapeHtml(bovMoney(h.invoice_subtotal))),
    bovKv("Taxes / shipping", `${escapeHtml(bovMoney(h.total_taxes))} / ${escapeHtml(bovMoney(h.shipping_cost))}`),
    bovKv("Invoice total", `<strong>${escapeHtml(bovMoney(h.invoice_total))}</strong>`),
    bovKv("Paid / credits", `${escapeHtml(bovMoney(h.total_payments))} / ${escapeHtml(bovMoney(h.total_credits))}`),
    bovKv("Profit", (() => {
      const net = h.net_profit != null ? h.net_profit : h.profit;
      if (net == null) return "—";
      const netPct = bovNum(h.revenue) > 0 ? (bovNum(net) / bovNum(h.revenue)) * 100 : null;
      const sub = `product ${bovMoney(h.profit)} − shipping ${bovMoney(h.shipping_cost || 0)}`;
      return `<strong class="bov-profit${bovNum(net) < 0 ? " is-neg" : ""}">${escapeHtml(bovMoney(net))}</strong>${netPct != null ? ` <span class="sa-kpi-pct">${escapeHtml(bovPct(netPct))}</span>` : ""}<span class="bov-cell-sub" title="${escapeHtml(sub)}">${escapeHtml(sub)}</span>`;
    })()),
    bovKv("Cost basis", data.cost_basis === "s2s"
      ? `<span class="bov-cost-basis is-s2s" title="S2S cost is on — every line costed from the Item Tracker S2S Items_tbl.UnitCost by UPC">S2S UnitCost</span>`
      : data.cost_basis === "current"
        ? `<span class="bov-cost-basis" title="Each line costed from this store's Items_tbl.UnitCost by UPC today (invoice line cost when the item is missing)">Current cost (Items_tbl)</span>`
        : `<span class="bov-cost-basis" title="Each line costed from the cost stamped on the invoice line when it was sold (blank/$0 → current Items_tbl.UnitCost)">Sale cost (invoice line)</span>`),
  ].join("");
  const tfoot = `<tfoot><tr><td class="bov-num bov-line-no"></td><td>${bovInt(lines.length)} lines</td>` +
    `<td class="bov-num">${bovInt(lines.reduce((a, l) => a + bovNum(l.qty_shipped), 0))}</td><td></td>` +
    `<td class="bov-num">${bovMoney(h.cost)}</td><td class="bov-num">${bovMoney(h.revenue)}</td>` +
    `<td class="bov-num" title="Product profit before shipping — real profit after shipping is shown above">${bovMoney(h.profit)}</td>` +
    `<td class="bov-num">${h.margin_pct != null ? escapeHtml(bovPct(h.margin_pct)) : "—"}</td></tr></tfoot>`;
  body.innerHTML =
    `<div class="bov-kv-grid">${kv}</div>` +
    (lines.length
      ? bovTableHtml("invoiceLines", bovInvoiceLineCols(), bovSortRows(lines, bovState.sort.invoiceLines),
                     { tfoot, plainRows: true, rowAttrs: (l) => (l.void ? 'style="opacity:.55" title="Voided line"' : "") })
      : `<p class="bov-modal-note">No line items on this invoice.</p>`) +
    (h.notes ? `<p class="bov-modal-note">Notes: ${escapeHtml(h.notes)}</p>` : "");
}

function bovLineProfitCell(profit) {
  if (profit == null) return `<span class="bov-cell-muted">—</span>`;
  return `<span class="bov-profit${bovNum(profit) < 0 ? " is-neg" : ""}">${escapeHtml(bovMoney(profit))}</span>`;
}

function bovLineMarginCell(pct) {
  if (pct == null) return `<span class="bov-cell-muted">—</span>`;
  const m = bovNum(pct);
  const tone = m < 0 ? " is-neg" : (m < 15 ? " is-low" : "");
  return `<span class="bov-margin${tone}">${escapeHtml(bovPct(m))}</span>`;
}

function bovInvoiceLineCols() {
  return [
    { key: "product_description", label: "Product", width: "36%", render: (l) => `<span class="bov-cell-main">${escapeHtml(l.product_description || "—")}</span><span class="bov-cell-sub bov-cell-mono">${escapeHtml([l.product_sku, l.product_upc].filter(Boolean).join(" · "))}${l.unit_desc ? ` · ${escapeHtml(l.unit_desc)}` : ""}</span>` },
    { key: "qty_shipped", label: "Qty", num: true, width: "8%", render: (l) => { const qty = bovNum(l.qty_shipped); return `${bovInt(qty)}${l.qty_ordered != null && bovNum(l.qty_ordered) !== qty ? `<span class="bov-cell-sub">of ${bovInt(l.qty_ordered)}</span>` : ""}`; } },
    { key: "unit_price", label: "Price", num: true, width: "10%", render: (l) => bovMoney(l.unit_price) },
    { key: "unit_cost", label: "Cost", num: true, width: "11%", render: (l) => `${l.unit_cost != null ? bovMoney(l.unit_cost) : "—"}${l.line_unit_cost != null && l.unit_cost != null && Math.abs(bovNum(l.line_unit_cost) - bovNum(l.unit_cost)) > 0.004 ? `<span class="bov-cell-sub" title="Cost stamped on the invoice line">line ${escapeHtml(bovMoney(l.line_unit_cost))}</span>` : ""}` },
    { key: "extended_price", label: "Line total", num: true, width: "12%", render: (l) => bovMoney(l.extended_price) },
    { key: "line_profit", label: "Profit", num: true, width: "12%", render: (l) => bovLineProfitCell(l.line_profit) },
    { key: "margin_pct", label: "Margin", num: true, width: "9%", render: (l) => bovLineMarginCell(l.margin_pct) },
  ];
}

// ---- Product drill-in (Products tab row → every invoice / order line) -------

function bovProductRowAttrs(r) {
  return r._idx == null ? "" : `data-bov-open="product" data-bov-id="${r._idx}"`;
}

// The range the request will carry (bovRangeParams), so the cache key and the
// header label always match the lines fetched — not the widget's last period.
function bovProductPeriod() {
  const r = bovState.range || bovPresetToDates("today");
  return { start: r.from, end: r.to };
}

async function bovOpenProductModal(idx) {
  const title = document.getElementById("bov-product-title");
  const meta = document.getElementById("bov-product-meta");
  const body = document.getElementById("bov-product-body");
  if (!body) return;
  const row = ((bovState.widgets.products.data || {}).rows || [])[idx];
  if (!row) return;
  const period = bovProductPeriod();
  bovState.productModalData = null;
  if (title) title.textContent = row.description || row.sku || row.upc || "Product";
  if (meta) {
    meta.textContent = [
      bovStoreShort(row.store_name),
      row.upc ? `UPC ${row.upc}` : "no UPC",
      row.sku && row.sku !== row.upc ? `SKU ${row.sku}` : null,
      period.start ? bovFmtRangeLabel(period.start, period.end) : null,
    ].filter(Boolean).join(" · ");
  }
  openModal("bov-product-modal");
  const cacheKey = `${row.store_id}:${row.store_type}:${row.upc || ""}:${row.variant_shopify_id || ""}:${row.upc ? "" : (row.description || "")}:${period.start || ""}:${period.end || ""}:${bovState.costMode}`;
  const cache = bovState.modalCache.product;
  if (cache.has(cacheKey)) {
    bovRenderProductModal(cache.get(cacheKey));
    return;
  }
  bovModalLoading(body, row.store_type === "shopify" ? "Loading order lines…" : "Loading invoice lines…");
  const params = { store_id: row.store_id, ...bovRangeParams(), ...bovCostParams() };
  if (row.upc) params.upc = row.upc;
  else {
    if (row.variant_shopify_id) params.variant_id = row.variant_shopify_id;
    // Shopify blank-barcode rows without a variant id are matched by product title.
    if (row.store_type === "shopify" && !row.variant_shopify_id) params.title = (row.description || "").split(" — ")[0];
  }
  try {
    const data = await bovFetchJson("/products/lines", params);
    data._row = row;
    cache.set(cacheKey, data);
    bovRenderProductModal(data);
  } catch (e) {
    bovModalError(body, `Could not load the lines for this product: ${e.message || e}`);
  }
}

function bovProductBasisKv(label, cost, profit, pct, unit, hint) {
  if (cost == null) return bovKv(label, `<span class="bov-cell-muted" title="${escapeHtml(hint || "")}">—</span>`);
  const p = bovNum(profit);
  const m = pct != null ? bovNum(pct) : null;
  const tone = m == null ? "" : (m < 0 ? " is-neg" : (m < 15 ? " is-low" : ""));
  return bovKv(label,
    `<strong>${escapeHtml(bovMoney(cost))}</strong>` +
    `${unit != null ? `<span class="bov-cell-sub">${escapeHtml(bovMoney(unit))} / unit</span>` : ""}` +
    `<span class="bov-cell-sub">profit <span class="bov-profit${p < 0 ? " is-neg" : ""}">${escapeHtml(bovMoney(p))}</span>` +
    `${m != null ? ` · <span class="bov-margin${tone}">${escapeHtml(bovPct(m))}</span>` : ""}</span>`);
}

function bovRenderProductModal(data) {
  const body = document.getElementById("bov-product-body");
  if (!body) return;
  bovState.productModalData = data;
  const row = data._row || {};
  const shop = data.store_type === "shopify";
  const docWord = shop ? "order" : "invoice";
  if (data.error) {
    bovModalError(body, data.error === "not synced" ? `${data.store_name || "This store"} has no local Shopify mirror yet — run a Data Sync first.` : data.error);
    return;
  }
  const rows = data.rows || [];
  const t = data.totals || {};
  const lb = bovLocalBasis();
  const kv = [
    bovKv("Qty sold", `<strong>${bovInt(t.units)}</strong><span class="bov-cell-sub">${bovInt(t.lines)} line${t.lines === 1 ? "" : "s"} on ${bovInt(t.orders)} ${docWord}${t.orders === 1 ? "" : "s"}</span>`),
    bovKv("Revenue", `<strong>${escapeHtml(bovMoney(t.revenue))}</strong>${t.avg_price != null ? `<span class="bov-cell-sub">avg ${escapeHtml(bovMoney(t.avg_price))} / unit</span>` : ""}`),
    bovProductBasisKv(shop ? "Local cost" : lb.label, t.local_cost, t.local_profit, t.local_margin_pct, row.local_unit_cost,
      shop ? "S2S UnitPriceC not found for this barcode" : "No cost on this store's items table or invoice lines"),
    bovProductBasisKv("S2S cost", t.s2s_cost, t.s2s_profit, t.s2s_margin_pct, row.s2s_unit_cost,
      data.cost_store_name ? `UPC not found on ${data.cost_store_name}` : "Item Tracker S2S store is not configured"),
    bovKv("Cost basis", shop
      ? `<span class="bov-cost-basis" title="Local = Item Tracker S2S Items_tbl.UnitPriceC by barcode; S2S = Items_tbl.UnitCost">UnitPriceC / UnitCost</span>${data.cost_store_name ? `<span class="bov-cell-sub">${escapeHtml(data.cost_store_name)}</span>` : ""}`
      : `<span class="bov-cost-basis" title="${escapeHtml(`${lb.short} = ${lb.title}; S2S = Item Tracker S2S Items_tbl.UnitCost`)}">${escapeHtml(lb.key === "sale" ? "Invoice line cost / S2S UnitCost" : "Store UnitCost / S2S UnitCost")}</span>${data.cost_store_name ? `<span class="bov-cell-sub">S2S: ${escapeHtml(data.cost_store_name)}</span>` : ""}`),
  ].join("");
  const notes = [];
  if (data.truncated) notes.push(`Showing the first ${bovInt(rows.length)} lines — narrow the period to see the rest.`);
  (data.warnings || []).forEach((w) => notes.push(w));
  const cell = (v) => v == null ? `<span class="bov-cell-muted">—</span>` : escapeHtml(bovMoney(v));
  const tfoot = `<tfoot><tr><td class="bov-num bov-line-no"></td><td>${bovInt(t.lines)} line${t.lines === 1 ? "" : "s"}</td>` +
    `<td>${bovInt(t.orders)} ${docWord}${t.orders === 1 ? "" : "s"}</td><td></td><td></td>` +
    `<td class="bov-num">${bovInt(t.units)}</td><td class="bov-num">${cell(t.avg_price)}</td><td class="bov-num">${cell(t.revenue)}</td>` +
    `<td class="bov-num">${cell(t.local_cost)}</td><td class="bov-num">${bovLineProfitCell(t.local_profit)}</td><td class="bov-num">${bovLineMarginCell(t.local_margin_pct)}</td>` +
    `<td class="bov-num">${cell(t.s2s_cost)}</td><td class="bov-num">${bovLineProfitCell(t.s2s_profit)}</td><td class="bov-num">${bovLineMarginCell(t.s2s_margin_pct)}</td></tr></tfoot>`;
  const openKind = shop ? "shopify-order" : "invoice";
  body.innerHTML =
    `<div class="bov-kv-grid">${kv}</div>` +
    (rows.length
      ? bovTableHtml("productLines", bovProductLineCols(shop, lb), bovSortRows(rows, bovState.sort.productLines), {
          tfoot,
          rowAttrs: (l) => `data-bov-open="${openKind}" data-bov-id="${escapeHtml(l.doc_id)}" data-bov-store="${data.store_id}" title="Open ${docWord}"`,
        })
      : bovEmptyHtml(`No ${docWord} lines for this product in the period.`)) +
    (notes.length ? `<p class="bov-modal-note">${notes.map(escapeHtml).join(" · ")}</p>` : "");
}

function bovProductLineCols(shop, lb) {
  const docLabel = shop ? "Order" : "Invoice";
  const loc = shop ? "Local" : lb.short;
  return [
    { key: "doc_date", label: "Date", width: "7%", render: (l) => escapeHtml(bovDateMdy(l.doc_date)) },
    { key: "doc_number", label: docLabel, width: "8%", render: (l) => `<span class="bov-cell-main bov-cell-mono">${escapeHtml(l.doc_number || l.doc_id || "—")}</span><span class="bov-cell-sub">${escapeHtml(shop ? (l.status || "") : (l.shipped ? "Shipped" : "Not shipped"))}</span>` },
    { key: "customer", label: "Customer", width: "11%", render: (l) => bovCustomerCell(l.customer, l.sku && l.sku !== ((bovState.productModalData || {})._row || {}).sku ? `SKU ${l.sku}` : null) },
    { key: "ship_state", label: "State", width: "5%", render: (l) => `<span class="bov-cell-mono">${escapeHtml(l.ship_state || "—")}</span>` },
    { key: "qty", label: "Qty", num: true, width: "4%", render: (l) => bovInt(l.qty) },
    { key: "unit_price", label: "Price", num: true, width: "7%", render: (l) => {
      const main = l.unit_price != null ? escapeHtml(bovMoney(l.unit_price)) : `<span class="bov-cell-muted">—</span>`;
      if (shop && l.list_price != null && l.unit_price != null && Math.abs(bovNum(l.list_price) - bovNum(l.unit_price)) > 0.004) {
        return `${main}<span class="bov-cell-sub" title="Original unit price before discounts">list ${escapeHtml(bovMoney(l.list_price))}</span>`;
      }
      return main;
    } },
    { key: "revenue", label: "Revenue", num: true, width: "7%", render: (l) => escapeHtml(bovMoney(l.revenue)) },
    { key: "local_cost", label: `${loc} unit cost`, num: true, width: "10%", render: (l) => bovProductLineCostCell(l, "local_unit_cost", "local_cost") },
    { key: "local_profit", label: `${loc} profit`, num: true, width: "8%", render: (l) => bovLineProfitCell(l.local_profit) },
    { key: "local_margin_pct", label: `${loc} mgn`, num: true, width: "8%", render: (l) => bovLineMarginCell(l.local_margin_pct) },
    { key: "s2s_cost", label: "S2S unit cost", num: true, width: "10%", render: (l) => bovProductLineCostCell(l, "s2s_unit_cost", "s2s_cost") },
    { key: "s2s_profit", label: "S2S profit", num: true, width: "8%", render: (l) => bovLineProfitCell(l.s2s_profit) },
    { key: "s2s_margin_pct", label: "S2S mgn", num: true, width: "8%", render: (l) => bovLineMarginCell(l.s2s_margin_pct) },
  ];
}

// Unit cost leads (that is what a single item cost); the line total sits
// under it. Cost/profit always use the items-table cost, never the cost
// stamped on the invoice line (that only backs a UPC missing from Items_tbl).
function bovProductLineCostCell(l, unitKey, totalKey) {
  if (l[totalKey] == null) return `<span class="bov-cell-muted">—</span>`;
  const unit = l[unitKey];
  if (unit == null) return escapeHtml(bovMoney(l[totalKey]));
  return `<span class="bov-cell-main" title="Unit cost">${escapeHtml(bovMoney(unit))}</span>` +
    `<span class="bov-cell-sub" title="Line cost = qty × unit cost">${escapeHtml(bovMoney(l[totalKey]))} total</span>`;
}

async function bovOpenPoModal(poId) {
  const title = document.getElementById("bov-po-title");
  const body = document.getElementById("bov-po-body");
  if (!body) return;
  if (title) title.textContent = "Purchase order";
  openModal("bov-po-modal");
  const cache = bovState.modalCache.po;
  if (cache.has(poId)) {
    bovRenderPoModal(cache.get(poId));
    return;
  }
  bovModalLoading(body, "Loading purchase order…");
  try {
    const data = await bovFetchJson(`/purchases/${poId}`);
    cache.set(poId, data);
    bovRenderPoModal(data);
  } catch (e) {
    bovModalError(body, `Could not load this purchase order: ${e.message || e}`);
  }
}

function bovRenderPoModal(data) {
  const title = document.getElementById("bov-po-title");
  const body = document.getElementById("bov-po-body");
  if (!body) return;
  bovState.poModalData = data;
  const h = data.header || {};
  const lines = data.lines || [];
  const excludedCount = lines.filter((l) => l.excluded).length;
  if (title) title.textContent = `PO ${h.po_number || h.po_id || ""}${h.business_name ? ` — ${h.business_name}` : ""}`;
  const shipTo = [h.ship_to, h.ship_address1, h.ship_address2, [h.ship_city, h.ship_state, h.ship_zip_code].filter(Boolean).join(" ")].filter((x) => x && String(x).trim()).join(", ");
  const outstanding = h.qty_outstanding != null ? bovNum(h.qty_outstanding) : Math.max(0, bovNum(h.tot_qty_ord) - bovNum(h.tot_qty_rcv));
  const statusChip = h.is_received || h.status === 1
    ? `<span class="qip-status-chip complete">Received</span>`
    : outstanding > 0
      ? `<span class="qip-status-chip picking">Open · ${bovInt(outstanding)} outstanding</span>`
      : `<span class="qip-status-chip pending">Open</span>`;
  const kv = [
    bovKv("Supplier", `${escapeHtml(h.business_name || "—")}${h.account_no ? `<span class="bov-cell-sub">${escapeHtml(h.account_no)}</span>` : ""}`),
    bovKv("Contact", `${escapeHtml(h.supplier_contact || "—")}${h.supplier_phone ? `<span class="bov-cell-sub">${escapeHtml(h.supplier_phone)}</span>` : ""}`),
    bovKv("Status", statusChip),
    bovKv("PO date", escapeHtml(bovDateMdy(h.po_date))),
    bovKv("Required by", escapeHtml(h.required_date ? bovDateMdy(h.required_date) : "—")),
    bovKv("Ordered / received", `${bovInt(h.tot_qty_ord)} / ${bovInt(h.tot_qty_rcv)}`),
    bovKv("Outstanding value", escapeHtml(h.outstanding_value != null ? bovMoney(h.outstanding_value) : "—")),
    bovKv("PO total", `<strong>${escapeHtml(bovMoney(h.po_total))}</strong>`),
    bovKv("Ship to", escapeHtml(shipTo || "—")),
    bovKv("Title", escapeHtml(h.po_title || "—")),
  ].join("");
  const rowsHtml = lines.map((l, idx) => {
    const out = bovNum(l.qty_outstanding);
    const action = l.excluded
      ? `<button type="button" class="btn btn-secondary bov-btn-xs" data-bov-po-include="${l.exclusion_id}" title="Count this product in PO calculations again">Include again</button>`
      : l.product_id != null
        ? `<button type="button" class="btn btn-secondary bov-btn-xs" data-bov-po-exclude="${idx}" title="Exclude this product from PO calculations (all POs)">Exclude</button>`
        : "";
    return `<tr${l.excluded ? ` class="bov-po-line-excluded"` : ""}><td><span class="bov-cell-main">${escapeHtml(l.product_description || "—")}</span><span class="bov-cell-sub bov-cell-mono">${escapeHtml([l.product_sku, l.product_upc, l.supplier_sku].filter(Boolean).join(" · "))}</span>${l.excluded ? `<span class="bov-cell-sub">Excluded from calculations</span>` : ""}</td><td class="bov-num">${bovInt(l.qty_ordered)}</td><td class="bov-num">${bovInt(l.qty_received)}${l.date_received ? `<span class="bov-cell-sub">${escapeHtml(bovDateMdy(l.date_received))}</span>` : ""}</td><td class="bov-num">${out > 0 && !l.excluded ? `<span class="dashboard-activity-status warn bov-age-chip">${bovInt(out)}</span>` : bovInt(out)}</td><td class="bov-num">${bovMoney(l.unit_cost)}</td><td class="bov-num">${bovMoney(l.extended_cost)}</td><td class="bov-num">${action}</td></tr>`;
  }).join("");
  const sums = lines.filter((l) => !l.excluded).reduce((a, l) => {
    a.ord += bovNum(l.qty_ordered); a.rcv += bovNum(l.qty_received); a.out += bovNum(l.qty_outstanding); a.ext += bovNum(l.extended_cost); return a;
  }, { ord: 0, rcv: 0, out: 0, ext: 0 });
  body.innerHTML =
    `<div class="bov-kv-grid">${kv}</div>` +
    (lines.length
      ? `<div class="bov-table-scroll"><table class="data-table bov-mini-table bov-modal-table"><thead><tr><th style="width:29%">Product</th><th class="bov-num" style="width:10%">Ordered</th><th class="bov-num" style="width:12%">Received</th><th class="bov-num" style="width:12%">Outstanding</th><th class="bov-num" style="width:11%">Unit cost</th><th class="bov-num" style="width:13%">Ext. cost</th><th class="bov-num" style="width:13%"></th></tr></thead><tbody>${rowsHtml}</tbody><tfoot><tr><td>${bovInt(lines.length)} lines${excludedCount ? ` · ${bovInt(excludedCount)} excluded` : ""}</td><td class="bov-num">${bovInt(sums.ord)}</td><td class="bov-num">${bovInt(sums.rcv)}</td><td class="bov-num">${bovInt(sums.out)}</td><td></td><td class="bov-num">${bovMoney(sums.ext)}</td><td></td></tr></tfoot></table></div>`
      : `<p class="bov-modal-note">No line items on this purchase order.</p>`) +
    (h.notes ? `<p class="bov-modal-note">Notes: ${escapeHtml(h.notes)}</p>` : "");
}

async function bovExcludePoLine(idx) {
  const d = bovState.poModalData;
  const l = d && (d.lines || [])[idx];
  if (!l || l.product_id == null) return;
  try {
    const resp = await fetch(`${API_BASE}/business-overview/purchases/exclusions`, {
      method: "POST", headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ product_id: l.product_id, product_sku: l.product_sku, product_upc: l.product_upc, description: l.product_description }),
    });
    if (!resp.ok) {
      let detail = `HTTP ${resp.status}`;
      try { const j = await resp.json(); if (j && j.detail) detail = typeof j.detail === "string" ? j.detail : JSON.stringify(j.detail); } catch (e) { /* keep */ }
      throw new Error(detail);
    }
    showToast(`✓ Excluded “${l.product_description || l.product_sku || l.product_id}” from PO calculations`, "success");
    await bovPoExclusionChanged();
  } catch (e) {
    showToast(`✗ Could not exclude: ${e.message || e}`, "error");
  }
}

async function bovIncludePoExclusion(id) {
  try {
    const resp = await fetch(`${API_BASE}/business-overview/purchases/exclusions/${id}`, { method: "DELETE" });
    if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
    showToast("✓ Product counted in PO calculations again", "success");
    await bovPoExclusionChanged();
  } catch (e) {
    showToast(`✗ Could not remove the exclusion: ${e.message || e}`, "error");
  }
}

async function bovPoExclusionChanged() {
  bovState.modalCache.po.clear(); // product exclusions are global — every cached PO may change
  const poId = bovState.poModalData && bovState.poModalData.header && bovState.poModalData.header.po_id;
  if (poId != null) await bovOpenPoModal(poId);
  bovFetchAll({ only: ["purchasesIncoming", "purchasesPurchased", "purchasesReceived", "summary", "alerts"], silent: true });
}

// ---------------------------------------------------------------------------
// Configuration (sources) — collapsed bar + setup/edit form
// ---------------------------------------------------------------------------

async function bovLoadConfig() {
  const results = await Promise.allSettled([
    bovFetchJson("/config"),
    bovFetchJson("/config/options"),
  ]);
  bovState.config = results[0].status === "fulfilled" ? results[0].value : null;
  bovState.options = results[1].status === "fulfilled" ? results[1].value : null;
  if (results[0].status === "rejected") {
    console.warn("[bov] config load failed", results[0].reason);
    if (results[0].reason && results[0].reason.status !== 404) {
      showToast(`Overview config could not load: ${results[0].reason.message}`, "error");
    }
  }
  if (!bovState.config) {
    bovState.config = { id: 0, configured: false, sales_store_ids: [], sales_store_names: [], sales_store_id: null, purchases_store_id: null, shopify_store_ids: [], shopify_store_names: [], quotation_statuses: ["In Progress", "Locked"], timezone: "America/Chicago", sales_exclusions_count: 0 };
  }
}

function bovSalesStoreIds(cfg) {
  cfg = cfg || bovState.config || {};
  const ids = Array.isArray(cfg.sales_store_ids) && cfg.sales_store_ids.length ? cfg.sales_store_ids : (cfg.sales_store_id ? [cfg.sales_store_id] : []);
  return ids.map(Number).filter((n) => !isNaN(n));
}

function bovSalesStoreLabel(cfg) {
  cfg = cfg || bovState.config || {};
  const names = (cfg.sales_store_names && cfg.sales_store_names.length) ? cfg.sales_store_names : (cfg.sales_store_name ? [cfg.sales_store_name] : []);
  return names.join(", ");
}

function bovConfigDot(ok, warnOnly) {
  return `<span class="bov-config-dot ${ok ? "ok" : warnOnly ? "warn" : "off"}" aria-hidden="true"></span>`;
}

// Topbar "Sources" pill: status dot + "N not set" (the modal's rail badges carry the detail).
function bovRenderConfigBar() {
  const bar = document.getElementById("bov-config-bar");
  const summary = document.getElementById("bov-config-summary");
  const cfg = bovState.config || {};
  if (!bar || !summary) return;
  if (bovView()) { bar.hidden = true; return; }   // limited views never expose the sources
  bar.hidden = false;
  const shopN = (cfg.shopify_store_ids || []).length;
  const salesN = bovSalesStoreIds(cfg).length;
  const issues = [salesN > 0, !!cfg.purchases_store_id, shopN > 0, !!cfg.admin_store_id].filter((ok) => !ok).length;
  summary.innerHTML = `${bovConfigDot(issues === 0, issues > 0)}<span class="bov-config-pill-text">Sources</span>${issues ? `<span class="bov-config-pill-issues">${issues} not set</span>` : ""}`;
  document.getElementById("bov-config-head")?.classList.toggle("is-warn", issues > 0);
}

function bovAlertRulesSummary(rules) {
  rules = rules || {};
  const keys = Object.keys(BOV_ALERT_RULE_FIELDS);
  const on = keys.filter((k) => rules[k] && rules[k].enabled !== false).length;
  const bits = [`${on} of ${keys.length} rules on`];
  if (rules.unshipped_cutoff && rules.unshipped_cutoff.enabled !== false && rules.unshipped_cutoff.cutoff) bits.push(`cutoff ${bovFmtClock(rules.unshipped_cutoff.cutoff)}`);
  if (rules.margin_floor && rules.margin_floor.enabled !== false && rules.margin_floor.pct != null) bits.push(`margin floor ${rules.margin_floor.pct}%`);
  if (rules.revenue_drop && rules.revenue_drop.enabled !== false && rules.revenue_drop.pct != null) bits.push(`revenue drop ${rules.revenue_drop.pct}%`);
  const optOut = new Set();
  Object.keys(BOV_PER_STORE_RULES).forEach((k) => Object.entries((rules[k] && rules[k].stores) || {}).forEach(([sid, o]) => { if (o && o.enabled === false) optOut.add(sid); }));
  if (optOut.size) {
    const cfg = bovState.config || {};
    const ids = bovSalesStoreIds(cfg).map(String);
    const names = (cfg.sales_store_names || []);
    const lab = Array.from(optOut).map((sid) => names[ids.indexOf(sid)] || `store ${sid}`);
    bits.push(`invoice rules off for ${lab.join(", ")}`);
  }
  return bits.join(" · ");
}

function bovFmtClock(hhmm) {
  const m = /^(\d{1,2}):(\d{2})$/.exec(String(hhmm || ""));
  if (!m) return String(hhmm || "");
  const h = parseInt(m[1], 10);
  const ap = h >= 12 ? "pm" : "am";
  const h12 = h % 12 === 0 ? 12 : h % 12;
  return `${h12}:${m[2]} ${ap}`;
}

// Rules that can be tuned per sales store (stores without tracking numbers opt out).
const BOV_PER_STORE_RULES = { unshipped_cutoff: "cutoff", open_invoice_age: "days", margin_floor: "pct" };
// Rules whose per-store overrides also apply to Shopify stores (margin is computed per store for both).
const BOV_PER_STORE_INCLUDES_SHOPIFY = { margin_floor: true };

function bovPopulateAlertRules(rules) {
  rules = rules || {};
  Object.entries(BOV_ALERT_RULE_FIELDS).forEach(([key, fields]) => {
    const r = rules[key] || {};
    const en = document.getElementById(`bov-rule-${key}-enabled`);
    if (en) en.checked = r.enabled !== false;
    fields.forEach((f) => {
      const el = document.getElementById(`bov-rule-${key}-${f}`);
      if (!el) return;
      if (el.type === "checkbox") el.checked = !!r[f];
      else el.value = r[f] != null ? r[f] : "";
    });
    if (BOV_PER_STORE_RULES[key]) bovPopulateRuleStores(key, BOV_PER_STORE_RULES[key], r);
  });
}

function bovPopulateRuleStores(key, field, rule) {
  const wrap = document.getElementById(`bov-rule-${key}-stores`);
  if (!wrap) return;
  const cfg = bovState.config || {};
  const ids = bovSalesStoreIds(cfg);
  const names = (cfg.sales_store_names && cfg.sales_store_names.length) ? cfg.sales_store_names : (cfg.sales_store_name ? [cfg.sales_store_name] : []);
  // The form may be editing a not-yet-saved store selection: read the checked sales pills when present.
  const pills = Array.from(document.querySelectorAll(".bov-cfg-sales-cb"));
  let stores = ids.map((id, i) => ({ id, name: names[i] || `Store ${id}` }));
  if (pills.length) {
    const opts = (bovState.options && bovState.options.mssql_stores) || [];
    stores = pills.filter((p) => p.checked).map((p) => ({ id: parseInt(p.value, 10), name: (opts.find((o) => String(o.id) === p.value) || {}).name || `Store ${p.value}` }));
  }
  if (BOV_PER_STORE_INCLUDES_SHOPIFY[key]) {
    const shopPills = Array.from(document.querySelectorAll(".bov-cfg-shopify-cb"));
    const shopOpts = (bovState.options && bovState.options.shopify_stores) || [];
    const shops = shopPills.length
      ? shopPills.filter((p) => p.checked).map((p) => ({ id: parseInt(p.value, 10), name: (shopOpts.find((o) => String(o.id) === p.value) || {}).name || `Store ${p.value}`, shopify: true }))
      : (cfg.shopify_store_ids || []).map((id, i) => ({ id, name: (cfg.shopify_store_names || [])[i] || `Store ${id}`, shopify: true }));
    stores = stores.concat(shops);
  }
  const minStores = BOV_PER_STORE_INCLUDES_SHOPIFY[key] ? 1 : 2;
  if (stores.length < minStores) { wrap.hidden = true; wrap.innerHTML = ""; return; }
  const ov = (rule && rule.stores) || {};
  const isTime = field === "cutoff";
  const unit = isTime ? "" : (field === "pct" ? "%" : "days");
  const max = field === "pct" ? ' max="100"' : "";
  wrap.hidden = false;
  wrap.innerHTML =
    `<div class="bov-rule-stores-title">Per store <small>(blank = use the value above; untick to skip that store)</small></div>` +
    stores.map((s) => {
      const o = ov[String(s.id)] || {};
      const en = o.enabled !== false;
      const val = o[field] != null ? o[field] : "";
      const input = isTime
        ? `<input type="time" class="dark-input bov-rule-store-val" data-rule="${key}" data-store="${s.id}" data-field="${field}" step="60" value="${escapeHtml(String(val))}">`
        : `<input type="number" class="dark-input bov-rule-store-val" data-rule="${key}" data-store="${s.id}" data-field="${field}" min="0"${max} step="0.5" placeholder="default" value="${escapeHtml(String(val))}">`;
      return `<label class="bov-rule-store${en ? "" : " is-off"}"><input type="checkbox" class="bov-rule-store-en" data-rule="${key}" data-store="${s.id}"${en ? " checked" : ""}> <span class="bov-rule-store-name">${escapeHtml(s.name)}${s.shopify && !/shopify/i.test(s.name) ? ` <span class="bov-cell-store">Shopify</span>` : ""}</span> ${input}<span class="bov-rule-store-unit">${unit}</span></label>`;
    }).join("");
}

function bovCollectAlertRules() {
  const out = {};
  Object.entries(BOV_ALERT_RULE_FIELDS).forEach(([key, fields]) => {
    const en = document.getElementById(`bov-rule-${key}-enabled`);
    if (!en) return;
    const r = { enabled: !!en.checked };
    fields.forEach((f) => {
      const el = document.getElementById(`bov-rule-${key}-${f}`);
      if (!el) return;
      if (el.type === "checkbox") r[f] = !!el.checked;
      else if (el.type === "time") { if (el.value) r[f] = el.value; }
      else if (el.value !== "") r[f] = Number(el.value);
    });
    if (BOV_PER_STORE_RULES[key]) {
      const field = BOV_PER_STORE_RULES[key];
      const stores = {};
      document.querySelectorAll(`.bov-rule-store-en[data-rule="${key}"]`).forEach((cb) => {
        const sid = cb.dataset.store;
        const valEl = document.querySelector(`.bov-rule-store-val[data-rule="${key}"][data-store="${sid}"]`);
        const entry = {};
        if (!cb.checked) entry.enabled = false;
        if (valEl && valEl.value !== "") entry[field] = valEl.type === "time" ? valEl.value : Number(valEl.value);
        if (Object.keys(entry).length) stores[sid] = entry;
      });
      r.stores = stores;   // {} clears overrides server-side
    }
    out[key] = r;
  });
  return out;
}

function bovPillCheck(cls, value, label, checked, extraHtml) {
  return `<label class="bov-pill-check"><input type="checkbox" class="${cls}" value="${escapeHtml(String(value))}"${checked ? " checked" : ""}> <span>${escapeHtml(label)}</span>${extraHtml || ""}</label>`;
}

function bovPopulateConfigForm(cfg) {
  cfg = cfg || {};
  const options = bovState.options || {};
  const mssql = (options.mssql_stores || []).filter((s) => s.is_active !== false);
  const shopify = (options.shopify_stores || []).filter((s) => s.is_active !== false);

  const fill = (id, selectedId) => {
    const sel = document.getElementById(id);
    if (!sel) return;
    sel.innerHTML = `<option value="">— Not set —</option>` + mssql.map((s) => `<option value="${s.id}"${String(s.id) === String(selectedId || "") ? " selected" : ""}>${escapeHtml(s.name)}</option>`).join("");
    if (!mssql.length) sel.innerHTML += `<option value="" disabled>No active MSSQL stores</option>`;
  };
  fill("bov-cfg-purchases", cfg.purchases_store_id);
  fill("bov-cfg-admin", cfg.admin_store_id);

  const salesWrap = document.getElementById("bov-cfg-sales");
  if (salesWrap) {
    const chosen = new Set(bovSalesStoreIds(cfg).map(String));
    salesWrap.innerHTML = mssql.length
      ? mssql.map((s) => bovPillCheck("bov-cfg-sales-cb", s.id, s.name, chosen.has(String(s.id)))).join("")
      : `<span class="bov-field-help">No active MSSQL stores.</span>`;
  }

  const shopWrap = document.getElementById("bov-cfg-shopify");
  if (shopWrap) {
    const chosen = new Set((cfg.shopify_store_ids || []).map(String));
    shopWrap.innerHTML = shopify.length
      ? shopify.map((s) => bovPillCheck("bov-cfg-shopify-cb", s.id, s.name, chosen.has(String(s.id)), `<span class="bov-pill-badge ${s.synced ? "ok" : "warn"}" title="${escapeHtml(s.synced ? `Synced ${s.last_synced_at ? formatRelative(s.last_synced_at) : ""}` : "No completed Data Sync yet — skipped in sales totals")}">${s.synced ? "synced" : "not synced"}</span>`)).join("")
      : `<span class="bov-field-help">No active Shopify stores.</span>`;
  }

  const stWrap = document.getElementById("bov-cfg-statuses");
  if (stWrap) {
    const chosen = (cfg.quotation_statuses && cfg.quotation_statuses.length ? cfg.quotation_statuses : ["In Progress", "Locked"]).map((s) => String(s));
    const discovered = (options.quotation_statuses || []).map((s) => String(s));
    const all = [];
    chosen.concat(discovered).forEach((s) => {
      if (s && !all.some((x) => x.toLowerCase() === s.toLowerCase())) all.push(s);
    });
    stWrap.innerHTML = all.map((s) => bovStatusPillHtml(s, chosen.some((c) => c.toLowerCase() === s.toLowerCase()))).join("");
    if (!options.admin_configured) {
      stWrap.insertAdjacentHTML("beforeend", `<span class="bov-field-help bov-field-help-inline">Admin DB not set — statuses cannot be discovered until it is chosen above.</span>`);
    }
  }
  const tz = document.getElementById("bov-cfg-tz");
  if (tz) tz.value = cfg.timezone || "America/Chicago";
  bovPopulateAlertRules(cfg.alert_rules);

  const costNote = document.getElementById("bov-cfg-cost-note");
  if (costNote) {
    costNote.textContent = cfg.cost_store_name
      ? `Product cost for Shopify sales comes from ${cfg.cost_store_name}.`
      : "Product cost for Shopify sales comes from the Item Tracker S2S store, else the first sales store here.";
  }
}

function bovStatusPillHtml(status, checked) {
  return `<label class="bov-pill-check"><input type="checkbox" class="bov-cfg-status-cb" value="${escapeHtml(status)}"${checked ? " checked" : ""}> <span>${escapeHtml(status)}</span><button type="button" class="bov-pill-remove" data-bov-remove-status title="Remove from list" aria-label="Remove ${escapeHtml(status)}">×</button></label>`;
}

function bovAddStatusPill() {
  const input = document.getElementById("bov-cfg-status-add");
  const wrap = document.getElementById("bov-cfg-statuses");
  if (!input || !wrap) return;
  const val = input.value.trim();
  if (!val) return;
  const exists = Array.from(wrap.querySelectorAll(".bov-cfg-status-cb")).find((cb) => cb.value.toLowerCase() === val.toLowerCase());
  if (exists) {
    exists.checked = true;
  } else {
    wrap.insertAdjacentHTML("beforeend", bovStatusPillHtml(val, true));
  }
  input.value = "";
}

async function bovSaveConfig() {
  const btn = document.getElementById("bov-config-save");
  const salesIds = Array.from(document.querySelectorAll(".bov-cfg-sales-cb:checked")).map((cb) => parseInt(cb.value, 10)).filter((n) => !isNaN(n));
  const purchId = document.getElementById("bov-cfg-purchases")?.value || "";
  const shopIds = Array.from(document.querySelectorAll(".bov-cfg-shopify-cb:checked")).map((cb) => parseInt(cb.value, 10)).filter((n) => !isNaN(n));
  const statuses = Array.from(document.querySelectorAll(".bov-cfg-status-cb:checked")).map((cb) => cb.value.trim()).filter(Boolean);
  const tz = (document.getElementById("bov-cfg-tz")?.value || "").trim() || "America/Chicago";
  if (!salesIds.length && !purchId && !shopIds.length) {
    bovCfgSetTab("sources");
    bovCfgRenderFooter("Pick at least one BackOffice or Shopify source");
    showToast("Pick at least one data source", "warning");
    return;
  }
  const badInput = document.querySelector("#bov-cfg-rules input:invalid");
  if (badInput) {
    bovCfgSetTab("alerts");
    bovCfgRenderFooter("Check the highlighted threshold");
    try { badInput.reportValidity(); } catch (e) { /* ignore */ }
    return;
  }
  const payload = {
    sales_store_ids: salesIds,
    purchases_store_id: purchId ? parseInt(purchId, 10) : null,
    shopify_store_ids: shopIds,
    quotation_statuses: statuses,
    timezone: tz,
    alert_rules: bovCollectAlertRules(),
  };
  if (btn) btn.disabled = true;
  try {
    // Admin DB lives in the shared `admin_store_id` setting (same as Settings → Roles).
    const adminSel = document.getElementById("bov-cfg-admin");
    const adminVal = adminSel ? (adminSel.value || "") : null;
    const adminCur = bovState.config && bovState.config.admin_store_id != null ? String(bovState.config.admin_store_id) : "";
    if (adminVal !== null && adminVal !== adminCur) {
      await bovSaveAdminStore(adminVal);
    }
    const resp = await fetch(`${API_BASE}/business-overview/config`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
    });
    if (!resp.ok) {
      let detail = `HTTP ${resp.status}`;
      try { const j = await resp.json(); detail = (j && j.detail) ? (typeof j.detail === "string" ? j.detail : JSON.stringify(j.detail)) : detail; } catch (e) { /* keep */ }
      throw new Error(detail);
    }
    bovState.config = await resp.json();
    try { bovState.options = await bovFetchJson("/config/options"); } catch (e) { /* keep old options */ }
    // Staged bank-account toggles go last: the sources are already saved by now.
    let bankErr = null;
    try { await bovCfgApplyBank(); } catch (e) { bankErr = e; }
    bovValidateStoreFilter();
    bovSavePrefs();
    bovRenderStoreChips();
    if (bankErr) {
      const msg = `Sources saved, but bank accounts failed: ${bankErr.message || bankErr}`;
      showToast(`⚠ ${msg}`, "warning");
      bovState.cfgFirstRun = false;
      bovState.cfgDirty = true;
      const cancel = document.getElementById("bov-config-cancel");
      if (cancel) cancel.hidden = false;
      bovCfgSetTab("bank");
      bovCfgRenderFooter(msg);
    } else {
      showToast("✓ Overview settings saved", "success");
      bovCloseConfigModal();
    }
    bovShowSetup(false);
    bovRenderConfigBar();
    // Reset widget state so unconfigured→configured transitions repaint from a skeleton.
    Object.keys(bovState.widgets).forEach((k) => { bovState.widgets[k] = bovEmptyWidget(); });
    if (!bovState.range) bovApplyPreset(bovState.preset, { fetch: false });
    bovFetchAll();
    startBovAutoRefresh();
    bovScheduleChartRender();
  } catch (e) {
    showToast(`✗ ${e.message || "Could not save"}`, "error");
  } finally {
    if (btn) btn.disabled = false;
  }
}

async function bovSaveAdminStore(value) {
  const patch = await fetch(`${API_BASE}/settings/admin_store_id`, {
    method: "PATCH",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ value }),
  });
  if (patch.ok) return;
  const post = await fetch(`${API_BASE}/settings`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ key: "admin_store_id", value, description: "DB_ADMIN store for Quotations In Progress" }),
  });
  if (!post.ok) throw new Error("Could not save the Admin DB setting");
}

// ----- Exclusions manager (shared SalesExclusion list) -----

async function bovLoadExclusions() {
  const list = document.getElementById("bov-excl-list");
  if (!list) return;
  list.innerHTML = bovSkeletonHtml(2);
  try {
    const resp = await fetch(`${API_BASE}/sales/exclusions`);
    if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
    const data = await resp.json();
    bovState.exclusions = data.exclusions || [];
    if (bovState.config) bovState.config.sales_exclusions_count = data.total != null ? data.total : bovState.exclusions.length;
    bovRenderExclusions();
    bovRenderConfigBar();
    bovCfgRenderBadges();
  } catch (e) {
    list.innerHTML = `<p class="bov-modal-note bov-modal-error">Could not load exclusions: ${escapeHtml(e.message || e)}</p>`;
  }
}

function bovRenderExclusions() {
  const list = document.getElementById("bov-excl-list");
  if (!list) return;
  const rows = bovState.exclusions || [];
  if (!rows.length) {
    list.innerHTML = `<p class="bov-field-help">No customers excluded. Totals include every account.</p>`;
    return;
  }
  list.innerHTML = `<div class="bov-excl-chips">${rows
    .map((e) => {
      const scope = e.void_status === null || e.void_status === undefined ? "all events" : e.void_status === 0 ? "sales" : "voided only";
      return `<span class="bov-excl-chip" title="Excluded ${escapeHtml(e.excluded_at ? formatRelative(e.excluded_at) : "")}"><span class="bov-excl-chip-name">${escapeHtml(e.business_name)}</span><span class="bov-excl-chip-scope">${escapeHtml(scope)}</span><button type="button" class="bov-pill-remove" data-bov-excl-remove="${e.id}" aria-label="Remove ${escapeHtml(e.business_name)}">×</button></span>`;
    })
    .join("")}</div>`;
}

async function bovAddExclusion() {
  const input = document.getElementById("bov-excl-name");
  const scopeSel = document.getElementById("bov-excl-scope");
  if (!input) return;
  const name = input.value.trim();
  if (!name) {
    showToast("Enter a business / account name", "warning");
    return;
  }
  const scopeVal = scopeSel ? scopeSel.value : "0";
  const voidStatus = scopeVal === "" ? null : parseInt(scopeVal, 10);
  try {
    const resp = await fetch(`${API_BASE}/sales/exclusions`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ business_name: name, void_status: voidStatus }),
    });
    if (!resp.ok) {
      let detail = `HTTP ${resp.status}`;
      try { detail = (await resp.json()).detail || detail; } catch (e) { /* keep */ }
      throw new Error(detail);
    }
    input.value = "";
    bovHideExclAutocomplete();
    showToast(`✓ ${name} excluded from sales totals`, "success");
    await bovLoadExclusions();
    bovFetchAll({ only: ["summary", "trend", "top", "quotations", "invoicesPeriod", "invoicesOpen"] });
  } catch (e) {
    showToast(`✗ ${e.message || "Could not add exclusion"}`, "error");
  }
}

async function bovRemoveExclusion(id) {
  if (!id) return;
  try {
    const resp = await fetch(`${API_BASE}/sales/exclusions/${id}`, { method: "DELETE" });
    if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
    showToast("Exclusion removed", "success");
    await bovLoadExclusions();
    bovFetchAll({ only: ["summary", "trend", "top", "quotations", "invoicesPeriod", "invoicesOpen"] });
  } catch (e) {
    showToast(`✗ ${e.message || "Could not remove"}`, "error");
  }
}

function bovHideExclAutocomplete() {
  const box = document.getElementById("bov-excl-autocomplete");
  if (box) box.hidden = true;
}

function bovExclAutocomplete() {
  const input = document.getElementById("bov-excl-name");
  const box = document.getElementById("bov-excl-autocomplete");
  if (!input || !box) return;
  const q = input.value.trim();
  if (bovState.exclTimer) clearTimeout(bovState.exclTimer);
  if (q.length < 2) {
    box.hidden = true;
    return;
  }
  bovState.exclTimer = setTimeout(async () => {
    try {
      const resp = await fetch(`${API_BASE}/sales/business-names?query=${encodeURIComponent(q)}`);
      if (!resp.ok) { box.hidden = true; return; }
      const data = await resp.json();
      const names = (data && (data.results || data.names || (Array.isArray(data) ? data : []))) || [];
      if (!names.length) { box.hidden = true; return; }
      box.innerHTML = names.slice(0, 20).map((n) => `<button type="button" class="bov-excl-option" data-bov-name="${escapeHtml(n)}">${escapeHtml(n)}</button>`).join("");
      box.hidden = false;
    } catch (e) {
      box.hidden = true;
    }
  }, 250);
}

// ===== End Business Overview =====

// ============================================================================
// Month End — combined BackOffice + Shopify order list with real shipping cost
// ============================================================================

const ME_PREFS_KEY = "month_end_prefs";
const monthEndState = {
  initialized: false,
  loading: false,
  data: null,
  filters: { type: "all", stores: new Set(), search: "", reps: null }, // empty stores set = all · reps null = all
  repOptions: [],
  abort: null,
  progressLog: [],
  viewedKey: null, // row_key of the last order opened from the list — drives the row highlight
  navActive: false, // whether the open drill-in modal was reached from Month End (shows Prev/Next)
};

function meShow(id, visible, text) {
  const el = document.getElementById(id);
  if (!el) return;
  el.style.display = visible ? "" : "none";
  if (text !== undefined) el.textContent = text;
}

function meLoadPrefs() {
  try {
    const p = JSON.parse(localStorage.getItem(ME_PREFS_KEY) || "{}");
    if (["all", "backoffice", "shopify"].includes(p.type)) monthEndState.filters.type = p.type;
    if (p.sort && p.sort.key) bovState.sort.monthEnd = { key: String(p.sort.key), dir: p.sort.dir === "asc" ? "asc" : "desc" };
  } catch (e) { /* corrupt prefs — defaults win */ }
}

function meSavePrefs() {
  try {
    localStorage.setItem(ME_PREFS_KEY, JSON.stringify({ type: monthEndState.filters.type, sort: bovState.sort.monthEnd }));
  } catch (e) { /* storage full/blocked — non-fatal */ }
}

// Month End follows the period AND store filter selected in the Business
// Overview topbar — unselected stores are not queried at all.
function monthEndPeriodParams() {
  return { ...bovRangeParams(), ...bovStoreParams(), ...bovCostParams() };
}

function loadMonthEndPage() {
  if (!monthEndState.initialized) {
    monthEndState.initialized = true;
    meLoadPrefs();
    document.querySelectorAll('#me-type-chips [data-me-type]').forEach((b) =>
      b.classList.toggle("is-active", b.dataset.meType === monthEndState.filters.type));

    document.getElementById("me-run")?.addEventListener("click", () => fetchMonthEnd());
    document.getElementById("me-idle-run")?.addEventListener("click", () => fetchMonthEnd());

    document.getElementById("me-type-chips")?.addEventListener("click", (e) => {
      const b = e.target.closest("[data-me-type]");
      if (!b) return;
      monthEndState.filters.type = b.dataset.meType;
      document.querySelectorAll('#me-type-chips [data-me-type]').forEach((x) =>
        x.classList.toggle("is-active", x === b));
      meSavePrefs();
      renderMonthEnd();
    });
    document.getElementById("me-store-chips")?.addEventListener("click", (e) => {
      const b = e.target.closest("[data-me-store]");
      if (!b) return;
      const id = parseInt(b.dataset.meStore, 10);
      const sel = monthEndState.filters.stores;
      if (sel.has(id)) sel.delete(id); else sel.add(id);
      renderMonthEnd();
    });

    document.getElementById("me-reps-trigger")?.addEventListener("click", (e) => {
      e.stopPropagation();
      bovTogglePopover("me-reps-popover");
    });
    document.getElementById("me-reps-list")?.addEventListener("click", (e) => {
      const item = e.target.closest("[data-me-rep]");
      if (item) meToggleRep(item.dataset.meRep);
    });

    let searchTimer = null;
    document.getElementById("me-search")?.addEventListener("input", (e) => {
      clearTimeout(searchTimer);
      searchTimer = setTimeout(() => {
        monthEndState.filters.search = (e.target.value || "").trim().toLowerCase();
        renderMonthEnd();
      }, 200);
    });

    // Sortable headers ride the Business Overview page delegation:
    // th[data-bov-sort] → bovToggleSort("monthEnd", key) → bovRenderCard("monthEnd").
  }
  // Opening the tab never runs the report — it is heavy (every invoice and
  // Shopify order in the period plus cost and parcel lookups), so it waits
  // for the Run button.
  if (!monthEndState.data && !monthEndState.loading) meShowIdle(null);
}

function meSetRunning(on) {
  ["me-run", "me-idle-run"].forEach((id) => {
    const b = document.getElementById(id);
    if (b) b.disabled = !!on;
  });
}

// Idle panel: nothing loaded for the current period / stores / cost basis.
// `reason` "changed" = a loaded result was discarded by a topbar change.
function meShowIdle(reason) {
  const badge = document.getElementById("bov-nav-count-month-end");
  if (badge) { badge.hidden = true; badge.textContent = ""; }
  ["me-not-configured", "me-warnings", "me-summary", "me-loading", "me-error", "me-empty", "me-table-card"]
    .forEach((id) => meShow(id, false));
  meShow("me-toolbar", true);
  const rangeEl = document.getElementById("me-range-label");
  if (rangeEl) {
    const r = bovRangeParams();
    rangeEl.textContent = r.date_from ? `${bovDateMdy(r.date_from)} – ${bovDateMdy(r.date_to)}` : "";
  }
  const chips = document.getElementById("me-store-chips");
  if (chips) chips.innerHTML = "";
  const reps = document.getElementById("me-rep-filter");
  if (reps) reps.hidden = true;
  const exportBar = document.getElementById("me-export-bar");
  if (exportBar) exportBar.innerHTML = "";
  const title = document.getElementById("me-idle-title");
  if (title) {
    title.textContent = reason === "changed"
      ? "Period, stores or cost basis changed — run the report again"
      : "Month End has not been run for this period";
  }
  meSetRunning(false);
  meShow("me-idle", true);
}

function meSetProgress(message) {
  const el = document.getElementById("me-loading");
  if (!el) return;
  if (message == null) { monthEndState.progressLog = []; return; }
  const log = monthEndState.progressLog;
  log.push(message);
  while (log.length > 6) log.shift();
  el.innerHTML =
    `<div class="me-progress">` +
    log.map((m, i) => `<div class="me-progress-line${i === log.length - 1 ? " is-current" : " is-done"}">` +
      `<span class="me-progress-dot"></span>${escapeHtml(m)}</div>`).join("") +
    `</div>`;
}

function meFail(message) {
  const el = document.getElementById("me-error");
  if (el) { el.textContent = `Could not load Month End: ${message}`; el.style.display = ""; }
  meShow("me-loading", false);
}

async function fetchMonthEnd() {
  const params = monthEndPeriodParams();
  if (monthEndState.abort) monthEndState.abort.abort();
  const ctl = new AbortController();
  monthEndState.abort = ctl;
  monthEndState.loading = true;
  meShow("me-idle", false);
  meShow("me-error", false);
  meSetRunning(true);
  meSetProgress(null);
  meSetProgress("Starting…");
  meShow("me-loading", true);
  if (!monthEndState.data) {
    meShow("me-summary", false);
    meShow("me-table-card", false);
    meShow("me-empty", false);
  }
  const finish = () => {
    if (monthEndState.abort === ctl) {
      monthEndState.loading = false;
      meShow("me-loading", false);
      meSetRunning(false);
    }
  };
  try {
    // SSE: progress events while the backend computes, then one `result` event.
    const qs = new URLSearchParams(Object.entries(params).filter(([, v]) => v != null && v !== ""));
    const resp = await fetch(`${API_BASE}/business-overview/month-end/stream?${qs}`, { signal: ctl.signal });
    if (!resp.ok || !resp.body) throw new Error(`HTTP ${resp.status}`);
    const reader = resp.body.getReader();
    const decoder = new TextDecoder();
    let buffer = "";
    let gotResult = false;
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      buffer += decoder.decode(value, { stream: true });
      const chunks = buffer.split("\n\n");
      buffer = chunks.pop();
      for (const chunk of chunks) {
        const m = chunk.match(/event: (\w+)\ndata: (.+)/s);
        if (!m) continue;
        const [, ev, dataStr] = m;
        if (ev === "progress") {
          try { meSetProgress(JSON.parse(dataStr).message); } catch (e) { /* malformed frame */ }
        } else if (ev === "result") {
          monthEndState.data = JSON.parse(dataStr);
          gotResult = true;
          finish();
          renderMonthEnd();
        } else if (ev === "error") {
          let msg = "server error";
          try { msg = JSON.parse(dataStr).message || msg; } catch (e) { /* keep default */ }
          throw new Error(msg);
        }
      }
    }
    if (!gotResult) throw new Error("stream ended without a result");
  } catch (e) {
    if (e.name === "AbortError" || ctl.signal.aborted) return;
    // Stream failed — fall back to the plain JSON endpoint once.
    try {
      meSetProgress("Retrying without progress stream…");
      const data = await bovFetchJson("/month-end", params, ctl.signal);
      if (ctl.signal.aborted) return;
      monthEndState.data = data;
      finish();
      renderMonthEnd();
    } catch (e2) {
      if (e2.name === "AbortError" || ctl.signal.aborted) return;
      meFail(e2.message || e2);
      finish();
    }
  } finally {
    finish();
  }
}

function meApplyEstimate(r) {
  // Materialize the estimate onto a row copy so sorting, totals, cells and the
  // modal handoff all see the estimated shipping cost + recomputed profit.
  // Applies when the real cost is unknown: no parcel, or a $0-cost parcel.
  if (r.source !== "shopify" || r.shipping_estimate == null || bovNum(r.shipping_cost) > 0) return r;
  const profit = r.product_profit != null
    ? Math.round((r.product_profit + (r.shipping_collected || 0) - r.shipping_estimate) * 100) / 100
    : null;
  return { ...r, shipping_cost: r.shipping_estimate, profit, _estimated: true };
}

// Profit % = net profit ÷ order total (invoice total / Shopify total_price), as a
// real numeric key on the row so the generic column sort orders it correctly.
function meProfitPct(profit, total) {
  return profit != null && bovNum(total) > 0 ? Math.round((bovNum(profit) / bovNum(total)) * 10000) / 100 : null;
}

function meDerive(r) {
  return { ...r, profit_pct: meProfitPct(r.profit, r.total) };
}

function monthEndVisibleRows() {
  const d = monthEndState.data;
  let rows = (d && d.rows) || [];
  if (bovState.estShipping) rows = rows.map(meApplyEstimate);
  rows = rows.map(meDerive);
  const f = monthEndState.filters;
  if (f.type !== "all") rows = rows.filter((r) => r.source === f.type);
  if (f.stores.size) rows = rows.filter((r) => f.stores.has(r.store_id));
  if (f.type === "backoffice" && f.reps != null) rows = rows.filter((r) => f.reps.includes(meRepKey(r)));
  if (f.search) {
    rows = rows.filter((r) =>
      String(r.number || "").toLowerCase().includes(f.search) ||
      String(r.customer || "").toLowerCase().includes(f.search) ||
      String(r.ship_state || "").toLowerCase() === f.search);
  }
  return bovSortRows(rows, bovState.sort.monthEnd);
}

// --- Modal Prev/Next over the Month End list + last-viewed row highlight ---
// The cycle order is monthEndVisibleRows(), recomputed on every step, so it
// always matches the table exactly as sorted/filtered right now.

function meApplyViewedHighlight() {
  const table = document.getElementById("me-table");
  if (!table) return;
  table.querySelectorAll("tr.bov-row-viewed").forEach((tr) => tr.classList.remove("bov-row-viewed"));
  if (!monthEndState.viewedKey) return;
  const row = table.querySelector(`tr[data-me-key="${CSS.escape(monthEndState.viewedKey)}"]`);
  if (row) row.classList.add("bov-row-viewed");
}

function meUpdateModalNav() {
  const rows = monthEndState.navActive && monthEndState.viewedKey ? monthEndVisibleRows() : [];
  const idx = rows.findIndex((r) => r.row_key === monthEndState.viewedKey);
  document.querySelectorAll(".me-modal-nav").forEach((el) => {
    if (idx < 0) { el.hidden = true; return; }
    el.hidden = false;
    const pos = el.querySelector(".me-nav-pos");
    if (pos) pos.textContent = `${bovInt(idx + 1)} of ${bovInt(rows.length)}`;
    const prev = el.querySelector('[data-me-nav="prev"]');
    const next = el.querySelector('[data-me-nav="next"]');
    if (prev) prev.disabled = idx <= 0;
    if (next) next.disabled = idx >= rows.length - 1;
  });
}

function meNavGo(dir) {
  if (!monthEndState.navActive || !monthEndState.viewedKey) return;
  const rows = monthEndVisibleRows();
  const idx = rows.findIndex((r) => r.row_key === monthEndState.viewedKey);
  if (idx < 0) return;
  const r = rows[dir === "prev" ? idx - 1 : idx + 1];
  if (!r) return;
  monthEndState.viewedKey = r.row_key;
  meApplyViewedHighlight();
  const hl = document.querySelector(`#me-table tr[data-me-key="${CSS.escape(r.row_key)}"]`);
  if (hl) hl.scrollIntoView({ behavior: "smooth", block: "center" });
  const id = String(r.row_key || "").split(":")[2] || "";
  const openInvoice = r.source === "backoffice";
  // The two sources use different modal elements — close the other one so
  // stacking (and Escape, which closes the topmost) stays sane.
  const other = document.getElementById(openInvoice ? "bov-shopify-order-modal" : "bov-invoice-modal");
  if (other && other.classList.contains("active")) closeModal(other.id);
  if (openInvoice) {
    bovOpenInvoiceModal(parseInt(id, 10), r.store_id);
  } else {
    bovOpenShopifyOrderModal(r.store_id, id, {
      shipping_cost: r.shipping_cost != null ? r.shipping_cost : null,
      parcels: r.parcels != null ? r.parcels : null,
      shipping_missing: !!r.shipping_missing,
      estimated: !!r._estimated,
    });
  }
  meUpdateModalNav();
}

// Sales-rep multiselect: BackOffice invoices only (Employees_tbl.FirstName via
// SalesRepID), so it is shown just while the BackOffice chip is active and reset
// otherwise. Options are keyed by lowercased name over ALL loaded BackOffice rows
// (not the checked store chips) so the same rep merges across stores and the
// selection survives store toggles.
function meRepKey(r) {
  return (r.sales_rep == null ? "" : String(r.sales_rep).trim().toLowerCase()) || "—";
}

function meRenderRepFilter(d) {
  const bar = document.getElementById("me-rep-filter");
  const list = document.getElementById("me-reps-list");
  if (!bar || !list) return;
  const f = monthEndState.filters;
  const boRows = f.type === "backoffice"
    ? ((d && d.rows) || []).filter((r) => r.source === "backoffice")
    : [];
  const counts = new Map();
  boRows.forEach((r) => {
    const k = meRepKey(r);
    const e = counts.get(k);
    if (e) e.count += 1;
    else counts.set(k, { label: k === "—" ? "No rep" : String(r.sales_rep).trim(), count: 1 });
  });
  const options = Array.from(counts.entries()).sort((a, b) => a[1].label.localeCompare(b[1].label));
  monthEndState.repOptions = options.map(([key]) => key);
  const val = document.getElementById("me-reps-value");
  const cnt = document.getElementById("me-reps-count");
  const trig = document.getElementById("me-reps-trigger");
  if (!options.length) {
    f.reps = null;
    bar.hidden = true;
    list.innerHTML = "";
    if (val) val.textContent = "All reps";
    if (cnt) cnt.hidden = true;
    trig?.classList.remove("has-selection");
    return;
  }
  bar.hidden = false;
  if (f.reps != null) {
    f.reps = f.reps.filter((n) => counts.has(n));
    if (f.reps.length >= options.length) f.reps = null;
  }
  const isAll = f.reps == null;
  const item = (value, label, on, n) =>
    `<button type="button" class="bov-ms-item${on ? " active" : ""}" role="checkbox" aria-checked="${on}" data-me-rep="${escapeHtml(value)}" title="${escapeHtml(label)}">` +
    `<span class="bov-ms-check" aria-hidden="true"></span><span class="bov-ms-label">${escapeHtml(label)}</span><span class="bov-store-chip-tag">${bovInt(n)}</span></button>`;
  list.innerHTML = [item("all", "All reps", isAll, options.length)]
    .concat(options.map(([key, o]) => item(key, o.label, isAll || f.reps.includes(key), o.count)))
    .join("");
  if (val) {
    if (isAll) val.textContent = "All reps";
    else if (f.reps.length <= 2) val.textContent = f.reps.map((k) => counts.get(k)?.label ?? k).join(", ") || "None";
    else val.textContent = `${f.reps.length} of ${options.length} reps`;
  }
  if (cnt) {
    cnt.hidden = isAll;
    cnt.textContent = isAll ? "0" : String(f.reps.length);
  }
  trig?.classList.toggle("has-selection", !isAll);
}

function meToggleRep(value) {
  const f = monthEndState.filters;
  const options = monthEndState.repOptions || [];
  if (value === "all") {
    f.reps = f.reps == null ? [] : null;   // select-all toggle: all checked <-> none checked
  } else {
    const cur = f.reps == null ? options.slice() : f.reps.slice();
    const i = cur.indexOf(value);
    if (i >= 0) cur.splice(i, 1); else cur.push(value);
    f.reps = cur.length >= options.length ? null : cur;
  }
  renderMonthEnd();
}

function meTotals(rows) {
  const t = { orders: rows.length, total: 0, revenue: 0, product_profit: 0,
              shipping_collected: 0, shipping_cost: 0, profit: 0, profit_known: 0, profit_base: 0,
              profit_pct: null, ship_missing: 0, est_orders: 0, est_amount: 0 };
  rows.forEach((r) => {
    t.total += bovNum(r.total);
    t.revenue += bovNum(r.revenue);
    t.product_profit += bovNum(r.product_profit);
    t.shipping_collected += bovNum(r.shipping_collected);
    t.shipping_cost += bovNum(r.shipping_cost);
    if (r.profit != null) { t.profit += bovNum(r.profit); t.profit_known++; t.profit_base += bovNum(r.total); }
    if (r.shipping_missing) t.ship_missing++;
    if (r._estimated) { t.est_orders++; t.est_amount += bovNum(r.shipping_cost); }
  });
  t.profit_pct = t.profit_known ? meProfitPct(t.profit, t.profit_base) : null;
  return t;
}

function meStoreCell(r) {
  const badge = r.source === "shopify"
    ? `<span class="me-badge me-badge-shopify">Shopify</span>`
    : `<span class="me-badge me-badge-bo">BO</span>`;
  return `${badge}<span class="me-store-name">${escapeHtml(bovStoreShort(r.store_name))}</span>`;
}

function meShipCollectedCell(r) {
  if (r.shipping_collected == null) {
    return `<span class="bov-cell-muted" title="${r.source === "backoffice" ? "BackOffice invoices do not collect shipping separately" : ""}">—</span>`;
  }
  return bovMoney(r.shipping_collected);
}

// Why a Shopify row's shipping cost is an estimate (table tooltip + export note).
function meShipEstimateWhy(r) {
  const scope = r.shipping_estimate_cross ? "across all stores" : "same store";
  const basis = r.shipping_estimate_near
    ? `the ${bovInt(r.shipping_estimate_n || 0)} order${r.shipping_estimate_n === 1 ? "" : "s"} closest by total — no comparable within ±$10/±10%`
    : `${bovInt(r.shipping_estimate_n || 0)} similar order${r.shipping_estimate_n === 1 ? "" : "s"} (total ±$10 or ±10%)`;
  const reason = r.shipping_missing ? "no parcel found for this order" : "the matched parcel has no recorded cost";
  return `Estimated from ${basis}, ${scope}, shipped to ${r.ship_state || "any state"}, last 90 days — ${reason}`;
}

function meShipCostCell(r) {
  if (r._estimated) {
    const why = meShipEstimateWhy(r);
    const tags = [`est · ${bovInt(r.shipping_estimate_n || 0)}`];
    if (r.shipping_estimate_near) tags.push("nearest");
    if (r.shipping_estimate_cross) tags.push("all stores");
    return `<span class="me-ship-est" title="${escapeHtml(why)}">~${escapeHtml(bovMoney(r.shipping_cost))}</span>` +
      `<span class="bov-cell-sub">${tags.join(" · ")}</span>`;
  }
  if (r.shipping_cost == null) {
    const why = r.source === "shopify"
      ? (r.shipping_missing ? "No parcel found in the shipper database for this order — profit computed with $0 shipping" : "Shipping cost unavailable")
      : "";
    return `<span class="bov-cell-muted${r.shipping_missing ? " me-ship-missing" : ""}" title="${escapeHtml(why)}">${r.shipping_missing ? "no parcel" : "—"}</span>`;
  }
  if (r.source === "shopify" && bovNum(r.shipping_cost) === 0) {
    return `<span class="me-ship-missing" title="Parcel matched but no cost recorded in the shipper database — profit computed with $0 shipping">$0.00</span>`;
  }
  const boxes = r.parcels && r.parcels > 1 ? `<span class="bov-cell-sub">${bovInt(r.parcels)} boxes</span>` : "";
  return `${bovMoney(r.shipping_cost)}${boxes}`;
}

function meProfitCell(r) {
  if (r.profit == null) {
    const why = r.revenue != null && r.cost == null
      ? "Product cost unknown — the order's barcodes were not found in the S2S items table"
      : "";
    return `<span class="bov-cell-muted" title="${escapeHtml(why)}">—</span>`;
  }
  const n = bovNum(r.profit);
  const breakdown = r.source === "shopify"
    ? `Product profit ${bovMoney(r.product_profit)} + shipping collected ${bovMoney(r.shipping_collected || 0)} − ${r._estimated ? "estimated " : ""}shipping cost ${bovMoney(r.shipping_cost || 0)}`
    : `Product profit ${bovMoney(r.product_profit)} − shipping cost ${bovMoney(r.shipping_cost || 0)}`;
  const cov = r.cost_coverage != null && r.cost_coverage < 0.999
    ? `<span class="bov-cell-sub">cost ${Math.round(r.cost_coverage * 100)}% known</span>` : "";
  const est = r._estimated ? `<span class="bov-cell-sub">est. shipping</span>` : "";
  return `<span class="bov-profit${n < 0 ? " is-neg" : ""}" title="${escapeHtml(breakdown)}">${escapeHtml(bovMoney(n))}</span>${est}${cov}`;
}

function meProfitPctTone(pct) {
  const m = bovNum(pct);
  return m < 0 ? " is-neg" : (m < 15 ? " is-low" : "");
}

function meProfitPctCell(r) {
  if (r.profit_pct == null) {
    const why = r.profit == null
      ? (r.revenue != null && r.cost == null ? "Product cost unknown — the order's barcodes were not found in the S2S items table" : "")
      : "Order total is zero";
    return `<span class="bov-cell-muted" title="${escapeHtml(why)}">—</span>`;
  }
  const title = `Profit ${bovMoney(r.profit)} on order total ${bovMoney(r.total)}${r._estimated ? " (estimated shipping)" : ""}`;
  const est = r._estimated ? `<span class="bov-cell-sub">est. shipping</span>` : "";
  return `<span class="bov-margin${meProfitPctTone(r.profit_pct)}" title="${escapeHtml(title)}">${escapeHtml(bovPct(r.profit_pct))}</span>${est}`;
}

function meStateCell(r) {
  const st = String(r.ship_state || "").trim();
  return st ? `<span class="bov-cell-mono">${escapeHtml(st.toUpperCase())}</span>` : `<span class="bov-cell-muted">—</span>`;
}

function meColumns() {
  return [
    { key: "date", label: "Date", width: "8%", render: (r) => escapeHtml(bovDateMdy(r.date)) },
    { key: "number", label: "Number", width: "10%", render: (r) => `<span class="bov-cell-mono">${escapeHtml(r.number || "—")}</span>` },
    { key: "store_name", label: "Store", width: "12%", render: meStoreCell },
    { key: "customer", label: "Customer", width: "17%", render: (r) => escapeHtml(r.customer || "—") },
    { key: "ship_state", label: "State", width: "6%", render: meStateCell },
    { key: "total", label: "Total", num: true, width: "10%", render: (r) => bovMoney(r.total) },
    { key: "shipping_collected", label: "Ship collected", num: true, width: "10%", render: meShipCollectedCell },
    { key: "shipping_cost", label: "Ship cost", num: true, width: "10%", render: meShipCostCell },
    { key: "profit", label: "Profit", num: true, width: "10%", render: meProfitCell },
    { key: "profit_pct", label: "Profit %", num: true, width: "7%", render: meProfitPctCell },
  ];
}

function meRowAttrs(r) {
  const id = String(r.row_key || "").split(":")[2] || "";
  const key = ` data-me-key="${escapeHtml(String(r.row_key || ""))}"`;
  if (r.source === "backoffice") {
    return `data-bov-open="invoice" data-bov-id="${escapeHtml(id)}" data-bov-store="${r.store_id}"${key}`;
  }
  return `data-bov-open="shopify-order" data-bov-id="${escapeHtml(id)}" data-bov-store="${r.store_id}"${key}` +
    (r.shipping_cost != null ? ` data-me-ship-cost="${r.shipping_cost}"` : "") +
    (r.parcels != null ? ` data-me-parcels="${r.parcels}"` : "") +
    ` data-me-ship-missing="${r.shipping_missing ? "1" : "0"}"` +
    (r._estimated ? ` data-me-ship-est="1"` : "");
}

function meTfootHtml(t) {
  return `<tfoot><tr>` +
    `<td class="bov-num bov-line-no"></td>` +
    `<td colspan="5">${bovInt(t.orders)} orders${t.profit_known < t.orders ? ` · profit known for ${bovInt(t.profit_known)}` : ""}</td>` +
    `<td class="bov-num">${bovMoney(t.total)}</td>` +
    `<td class="bov-num">${bovMoney(t.shipping_collected)}</td>` +
    `<td class="bov-num">${bovMoney(t.shipping_cost)}</td>` +
    `<td class="bov-num"><span class="bov-profit${t.profit < 0 ? " is-neg" : ""}">${escapeHtml(bovMoney(t.profit))}</span></td>` +
    `<td class="bov-num">${t.profit_pct != null ? `<span class="bov-margin${meProfitPctTone(t.profit_pct)}" title="${escapeHtml(`Profit ${bovMoney(t.profit)} on ${bovMoney(t.profit_base)} of orders with a known profit`)}">${escapeHtml(bovPct(t.profit_pct))}</span>` : "—"}</td>` +
    `</tr></tfoot>`;
}

function meSummaryHtml(t) {
  const tile = (label, value, sub, cls) =>
    `<div class="me-tile${cls ? ` ${cls}` : ""}"><div class="me-tile-label">${escapeHtml(label)}</div>` +
    `<div class="me-tile-value">${value}</div>${sub ? `<div class="me-tile-sub">${escapeHtml(sub)}</div>` : ""}</div>`;
  return [
    tile("Orders", bovInt(t.orders)),
    tile("Total", escapeHtml(bovMoney(t.total))),
    tile("Shipping collected", escapeHtml(bovMoney(t.shipping_collected))),
    tile("Shipping cost", escapeHtml(bovMoney(t.shipping_cost)),
      t.est_orders ? `incl. ~${bovMoney(t.est_amount)} estimated on ${bovInt(t.est_orders)} order${t.est_orders === 1 ? "" : "s"}` : ""),
    tile("Profit", `<span class="bov-profit${t.profit < 0 ? " is-neg" : ""}">${escapeHtml(bovMoney(t.profit))}</span>`,
      t.profit_known < t.orders ? `${bovInt(t.orders - t.profit_known)} orders without a known profit` : ""),
    tile("Profit %", t.profit_pct != null
      ? `<span class="bov-margin${meProfitPctTone(t.profit_pct)}">${escapeHtml(bovPct(t.profit_pct))}</span>` : "—",
      t.profit_pct != null && t.profit_known < t.orders ? `of ${bovMoney(t.profit_base)} in orders with a known profit` : ""),
  ].join("");
}

function meRenderStoreChips(d) {
  const wrap = document.getElementById("me-store-chips");
  if (!wrap) return;
  const sel = monthEndState.filters.stores;
  const known = new Set((d.stores || []).map((s) => s.store_id));
  [...sel].forEach((id) => { if (!known.has(id)) sel.delete(id); });
  wrap.innerHTML = (d.stores || []).map((s) => {
    const active = sel.has(s.store_id);
    const err = s.error ? ` title="${escapeHtml(s.error)}"` : ` title="${escapeHtml(`${s.store_name} · ${bovInt(s.count || 0)} orders`)}"`;
    return `<button type="button" class="me-chip${active ? " is-active" : ""}${s.error ? " is-error" : ""}" data-me-store="${s.store_id}"${err}>` +
      `${escapeHtml(bovStoreShort(s.store_name))}${s.error ? " ⚠" : ` · ${bovInt(s.count || 0)}`}</button>`;
  }).join("");
}

function meRenderWarnings(d, visibleTotals) {
  const el = document.getElementById("me-warnings");
  if (!el) return;
  const notes = [];
  (d.warnings || []).forEach((w) => notes.push(w));
  if (d.truncated) notes.push(`Some stores hit the ${bovInt(d.limit)}-row limit — totals cover the listed orders only`);
  if (d.shipper && d.shipper.configured && d.shipper.unmatched > 0) {
    notes.push(`No parcel found for ${bovInt(d.shipper.unmatched)} Shopify order${d.shipper.unmatched === 1 ? "" : "s"} — their profit assumes $0 shipping cost`);
  }
  if (d.shipper && d.shipper.easyship_matched > 0) {
    notes.push(`${bovInt(d.shipper.easyship_matched)} shipping cost${d.shipper.easyship_matched === 1 ? "" : "s"} filled in from EasyShip`);
  }
  if (!notes.length) { el.style.display = "none"; el.innerHTML = ""; return; }
  el.style.display = "";
  el.innerHTML = notes.map((n) => `<div class="me-warning">${escapeHtml(n)}</div>`).join("");
}

function renderMonthEnd() {
  const d = monthEndState.data;
  if (!d) return;
  const configured = !!d.configured;
  const badge = document.getElementById("bov-nav-count-month-end");
  if (badge) {
    const n = configured && d.totals ? d.totals.orders : null;
    badge.hidden = n == null;
    badge.textContent = n == null ? "" : bovInt(n);
  }
  meShow("me-not-configured", !configured);
  meShow("me-toolbar", configured && !d.filtered_out);
  if (configured && d.filtered_out) {
    meShow("me-summary", false);
    meShow("me-table-card", false);
    meShow("me-warnings", false);
    meShow("me-empty", true);
    const empty = document.querySelector("#me-empty p");
    if (empty) empty.textContent = "The store filter in the topbar excludes every Month End source — pick at least one sales or Shopify store.";
    return;
  }
  const rangeEl = document.getElementById("me-range-label");
  if (rangeEl) {
    const p = d.period || {};
    rangeEl.textContent = p.start ? `${bovDateMdy(p.start)} – ${bovDateMdy(p.end)}` : "";
  }
  if (!configured) {
    meShow("me-summary", false);
    meShow("me-table-card", false);
    meShow("me-empty", false);
    meShow("me-warnings", false);
    return;
  }
  meRenderStoreChips(d);
  meRenderRepFilter(d);
  bovRenderExportBar("monthEnd");
  const rows = monthEndVisibleRows();
  const t = meTotals(rows);
  meRenderWarnings(d, t);

  const summary = document.getElementById("me-summary");
  if (summary) { summary.innerHTML = meSummaryHtml(t); summary.style.display = ""; }

  const tableCard = document.getElementById("me-table-card");
  const table = document.getElementById("me-table");
  const foot = document.getElementById("me-foot");
  if (!rows.length) {
    meShow("me-table-card", false);
    const filtered = (d.rows || []).length > 0;
    meShow("me-empty", true);
    const empty = document.querySelector("#me-empty p");
    if (empty) empty.textContent = filtered ? "No orders match the filters." : "No orders in this period.";
    return;
  }
  meShow("me-empty", false);
  if (table) table.innerHTML = bovTableHtml("monthEnd", meColumns(), rows, { tfoot: meTfootHtml(t), rowAttrs: meRowAttrs, select: { keyOf: BOV_EXPORTS.monthEnd.keyOf } });
  meApplyViewedHighlight();
  if (foot) {
    const p = d.period || {};
    foot.innerHTML = `<span>${bovInt(rows.length)} of ${bovInt((d.rows || []).length)} orders · ${escapeHtml(p.start || "")} → ${escapeHtml(p.end || "")}</span>`;
  }
  if (tableCard) tableCard.style.display = "";
}

// ===== End Month End =====

// ===== BOV Inventory tab =====
// Clone of the Sales report as a Business Overview tab. Config is read-only
// from the Sales page (GET /sales/config); the period follows the BOV topbar.

const INV_COLUMNS = [
  { key: "upc",            label: "UPC",         soldOnly: false, baseWidth: 10, align: "left",  thStyle: "",                    tdStyle: "font-family: monospace; font-size: 0.8125rem",                                                                      hasFilter: true },
  { key: "description",    label: "Description", soldOnly: false, baseWidth: 25, align: "left",  thStyle: "",                    tdStyle: "font-size: 0.8125rem; overflow: hidden; text-overflow: ellipsis; white-space: nowrap",                               hasFilter: true },
  { key: "subcategory",    label: "Subcategory", soldOnly: false, baseWidth: 12, align: "left",  thStyle: "",                    tdStyle: "font-size: 0.8125rem; color: var(--text-secondary); overflow: hidden; text-overflow: ellipsis; white-space: nowrap", hasFilter: true },
  { key: "bin_location",   label: "Bin",         soldOnly: false, baseWidth: 8,  align: "left",  thStyle: "",                    tdStyle: "font-size: 0.8125rem",                                                                                              hasFilter: false },
  { key: "reorder_level",  label: "Reorder",     soldOnly: false, baseWidth: 6,  align: "right", thStyle: "text-align: right;",  tdStyle: "text-align: right; font-size: 0.8125rem",                                                                           hasFilter: true },
  { key: "quant_on_hand",  label: "On Hand",     soldOnly: false, baseWidth: 7,  align: "right", thStyle: "text-align: right;",  tdStyle: "text-align: right; font-size: 0.8125rem",                                                                           hasFilter: false },
  { key: "s2s_cost",       label: "S2S Cost",    soldOnly: false, baseWidth: 7,  align: "right", thStyle: "text-align: right;",  tdStyle: "text-align: right; font-size: 0.8125rem",                                                                           hasFilter: false, money: true },
  { key: "total_cost",     label: "Total Cost",  soldOnly: false, baseWidth: 7,  align: "right", thStyle: "text-align: right;",  tdStyle: "text-align: right; font-size: 0.8125rem; font-weight: 600",                                                         hasFilter: false, money: true },
  { key: "total_sold",     label: "Sold",        soldOnly: true,  baseWidth: 6,  align: "right", thStyle: "text-align: right;",  tdStyle: "text-align: right; font-size: 0.8125rem",                                                                           hasFilter: false },
  { key: "total_returned", label: "Returns",     soldOnly: true,  baseWidth: 6,  align: "right", thStyle: "text-align: right;",  tdStyle: "text-align: right; font-size: 0.8125rem; color: var(--warning)",                                                    hasFilter: false },
  { key: "net_sold",       label: "Net Sold",    soldOnly: true,  baseWidth: 7,  align: "right", thStyle: "text-align: right;",  tdStyle: "text-align: right; font-size: 0.8125rem; font-weight: 600",                                                         hasFilter: false },
];

let invState = {
  initialized: false,
  isLoading: false,
  hasData: false,
  abort: null,
  allProducts: [],
  filteredProducts: [],
  viewMode: "all",
  sortColumn: "net_sold",
  sortDirection: "desc",
  currentPage: 0,
  pageSize: parseInt(localStorage.getItem("inv_page_size") || "100"),
  summary: null,
  stores: [],
  config: null,
  subcategories: [],
  allSubcategories: [],
  selectedSubcategories: [],
  excludedSubcategories: [],
  searchFilter: "",
  selectedReorderLevels: [],
  binsFilter: "",
  hiddenColumns: JSON.parse(localStorage.getItem("inv_hidden_columns") || "[]"),
};

function invGetVisibleColumns(isSold) {
  const cols = INV_COLUMNS.filter(col => {
    if (col.soldOnly && !isSold) return false;
    return !invState.hiddenColumns.includes(col.key);
  });
  const totalBase = cols.reduce((s, c) => s + c.baseWidth, 0);
  const target = 98;
  cols.forEach(col => {
    col.width = ((col.baseWidth / totalBase) * target).toFixed(1) + "%";
  });
  return cols;
}

function invBuildColumnTogglePills() {
  const container = document.getElementById("inv-column-pills");
  if (!container) return;
  container.innerHTML = "";
  INV_COLUMNS.forEach(col => {
    const isVisible = !invState.hiddenColumns.includes(col.key);
    const label = document.createElement("label");
    label.style.cssText = `display: inline-flex; align-items: center; gap: 0.25rem; font-size: 0.75rem; cursor: pointer; padding: 0.2rem 0.5rem; border-radius: 1rem; border: 1px solid var(--border-color); background: ${isVisible ? "var(--bg-tertiary, rgba(255,255,255,0.08))" : "transparent"}; white-space: nowrap; opacity: ${isVisible ? "1" : "0.5"}; transition: opacity 0.15s, background 0.15s;`;
    const cb = document.createElement("input");
    cb.type = "checkbox";
    cb.checked = isVisible;
    cb.style.cssText = "margin: 0; cursor: pointer;";
    cb.onchange = () => invToggleColumn(col.key);
    label.appendChild(cb);
    label.appendChild(document.createTextNode(col.label));
    container.appendChild(label);
  });
}

function invToggleColumn(key) {
  const idx = invState.hiddenColumns.indexOf(key);
  if (idx >= 0) {
    invState.hiddenColumns.splice(idx, 1);
  } else {
    const visibleCount = INV_COLUMNS.filter(c => !invState.hiddenColumns.includes(c.key)).length;
    if (visibleCount <= 1) {
      showToast("At least one column must remain visible", "warning");
      invBuildColumnTogglePills();
      return;
    }
    invState.hiddenColumns.push(key);
  }
  localStorage.setItem("inv_hidden_columns", JSON.stringify(invState.hiddenColumns));
  invBuildColumnTogglePills();
  const filterRow = document.getElementById("inv-table-filters");
  if (filterRow) filterRow.dataset.viewKey = "";
  renderInvTable();
}

function resetInvColumns() {
  invState.hiddenColumns = [];
  localStorage.removeItem("inv_hidden_columns");
  invBuildColumnTogglePills();
  const filterRow = document.getElementById("inv-table-filters");
  if (filterRow) filterRow.dataset.viewKey = "";
  renderInvTable();
}

async function loadInventoryTab() {
  if (!invState.initialized) {
    invState.initialized = true;
    invBuildColumnTogglePills();
    const refreshBtn = document.getElementById("inv-refresh");
    if (refreshBtn) refreshBtn.addEventListener("click", () => {
      invState.hasData = false;
      fetchInventoryReport();
    });
  }

  try {
    const config = await apiRequest("/sales/config");
    if (!config || !config.s2s_store_id) {
      document.getElementById("inv-not-configured").style.display = "block";
      document.getElementById("inv-toolbar").style.display = "none";
      return;
    }
    invState.config = config;
    invState.excludedSubcategories = config.excluded_subcategories || [];
    document.getElementById("inv-not-configured").style.display = "none";
    document.getElementById("inv-toolbar").style.display = "block";
    const sources = document.getElementById("inv-sources-line");
    if (sources) {
      const stores = (config.mssql_store_names || []).concat(config.shopify_store_names || []);
      sources.textContent = `S2S: ${config.s2s_store_name || "?"} · Stores: ${stores.join(", ") || "None"}`;
    }
  } catch (e) {
    document.getElementById("inv-not-configured").style.display = "block";
    document.getElementById("inv-toolbar").style.display = "none";
    return;
  }

  if (!invState.hasData && !invState.isLoading) fetchInventoryReport();
}

async function fetchInventoryReport() {
  const config = invState.config;
  if (!config || !config.s2s_store_id) return;

  const mssqlStoreIds = config.mssql_store_ids || [];
  const shopifyStoreIds = config.shopify_store_ids || [];
  if (mssqlStoreIds.length === 0 && shopifyStoreIds.length === 0) {
    document.getElementById("inv-error").style.display = "block";
    document.getElementById("inv-error").textContent = "No sales stores configured — pick at least one on the Sales page.";
    return;
  }

  // The topbar period can change mid-stream: abort the previous fetch.
  if (invState.abort) invState.abort.abort();
  const controller = new AbortController();
  invState.abort = controller;
  invState.isLoading = true;

  const range = bovRangeParams();
  const rangeEl = document.getElementById("inv-range-label");
  if (rangeEl) rangeEl.textContent = `${bovDateMdy(range.date_from)} – ${bovDateMdy(range.date_to)}`;

  document.getElementById("inv-results").style.display = "none";
  document.getElementById("inv-empty").style.display = "none";
  document.getElementById("inv-summary").style.display = "none";
  document.getElementById("inv-error").style.display = "none";
  document.getElementById("inv-progress").style.display = "block";
  const progressList = document.getElementById("inv-progress-list");
  progressList.innerHTML = "";

  try {
    const response = await fetch(`${API_BASE}/sales/report/stream`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      signal: controller.signal,
      body: JSON.stringify({
        mssql_store_ids: mssqlStoreIds,
        shopify_store_ids: shopifyStoreIds,
        date_from: range.date_from || null,
        date_to: range.date_to || null,
      }),
    });

    const reader = response.body.getReader();
    const decoder = new TextDecoder();
    let buffer = "";

    while (true) {
      const { value, done } = await reader.read();
      if (done) break;

      buffer += decoder.decode(value, { stream: true });
      const lines = buffer.split("\n");
      buffer = lines.pop() || "";

      for (const line of lines) {
        if (line.startsWith("data: ")) {
          try {
            const data = JSON.parse(line.substring(6));
            invHandleProgress(data, progressList);
          } catch (e) {
            // skip malformed
          }
        }
      }
    }
  } catch (e) {
    if (e.name !== "AbortError") {
      invAddProgressItem(progressList, `Error: ${e.message}`, "var(--danger)");
    }
  } finally {
    if (invState.abort === controller) {
      invState.abort = null;
      invState.isLoading = false;
    }
  }
}

function invHandleProgress(data, progressList) {
  if (data.message && !data.status) {
    invAddProgressItem(progressList, data.message, "var(--danger)");
    return;
  }

  switch (data.status) {
    case "fetching_products":
      invAddProgressItem(progressList, "Fetching active products from primary database...", "var(--text-secondary)");
      break;
    case "products_fetched":
      invAddProgressItem(progressList, `Found ${data.count.toLocaleString()} active products`, "var(--success)");
      break;
    case "searching_store":
      invAddProgressItem(progressList, `Searching ${data.store_name} (${data.store_type})...`, "var(--text-secondary)");
      break;
    case "completed_store":
      invAddProgressItem(progressList, `${data.store_name}: ${data.products_found.toLocaleString()} products with sales (${data.completed}/${data.total_stores})`, "var(--success)");
      break;
    case "error_store":
      invAddProgressItem(progressList, `${data.store_name}: ${data.message}`, "var(--danger)");
      break;
    case "merging":
      invAddProgressItem(progressList, "Merging results...", "var(--text-secondary)");
      break;
  }

  if (data.products) {
    document.getElementById("inv-progress").style.display = "none";
    if (data.products.length === 0) {
      document.getElementById("inv-empty").style.display = "block";
    } else {
      displayInventoryResults(data);
    }
  }
}

function invAddProgressItem(container, text, color) {
  const li = document.createElement("li");
  li.style.cssText = `padding: 0.25rem 0; color: ${color};`;
  li.textContent = text;
  container.appendChild(li);
}

function displayInventoryResults(data) {
  invState.hasData = true;
  data.products.forEach((p) => {
    p.total_cost = (p.quant_on_hand || 0) * (p.s2s_cost || 0);
  });
  invState.allProducts = data.products;
  invState.summary = data.summary;
  invState.stores = data.stores || [];
  invState.allSubcategories = data.subcategories || [];
  invState.subcategories = data.subcategories || [];
  invState.selectedSubcategories = [];

  const savedView = localStorage.getItem("inv_view_mode");
  invState.viewMode = savedView || "all";
  invState.sortColumn = invState.viewMode === "sold" ? "net_sold" : "description";
  invState.sortDirection = invState.viewMode === "sold" ? "desc" : "asc";
  invState.currentPage = 0;

  document.querySelectorAll(".inv-toggle-btn").forEach((b) => b.classList.remove("active"));
  const activeBtn = document.querySelector(`.inv-toggle-btn[data-view="${invState.viewMode}"]`);
  if (activeBtn) activeBtn.classList.add("active");

  invState.searchFilter = localStorage.getItem("inv_filter_search") || "";

  const savedReorder = JSON.parse(localStorage.getItem("inv_filter_reorder") || "[]");
  if (savedReorder.length > 0) {
    invState.selectedReorderLevels = savedReorder;
  }

  const savedSubcats = JSON.parse(localStorage.getItem("inv_filter_subcategories") || "[]");
  if (savedSubcats.length > 0 && savedSubcats.length < (data.subcategories || []).length) {
    invState.selectedSubcategories = savedSubcats.filter((s) => (data.subcategories || []).includes(s));
  }

  applyInvFilters();

  const instockEl = document.getElementById("inv-filter-instock");
  const binsEl = document.getElementById("inv-filter-bins");
  if (instockEl) instockEl.checked = localStorage.getItem("inv_filter_instock") === "1";
  const savedBins = localStorage.getItem("inv_filter_bins") || "";
  invState.binsFilter = savedBins;
  if (binsEl) binsEl.value = savedBins;

  applyInvFilters();
  document.getElementById("inv-results").style.display = "block";
}

function toggleInventoryView(mode) {
  invState.viewMode = mode;
  invState.currentPage = 0;
  localStorage.setItem("inv_view_mode", mode);

  if (mode === "sold" || mode === "all") {
    invState.sortColumn = "net_sold";
    invState.sortDirection = "desc";
  } else {
    invState.sortColumn = "description";
    invState.sortDirection = "asc";
  }

  document.querySelectorAll(".inv-toggle-btn").forEach((b) => b.classList.remove("active"));
  const activeBtn = document.querySelector(`.inv-toggle-btn[data-view="${mode}"]`);
  if (activeBtn) activeBtn.classList.add("active");

  applyInvFilters();
}

function applyInvFilters() {
  const searchEl = document.getElementById("inv-filter-search");
  const searchFilter = searchEl ? searchEl.value.toLowerCase().trim() : (invState.searchFilter || "");
  const subcatFilters = invState.selectedSubcategories || [];
  const reorderFilters = invState.selectedReorderLevels || [];
  const instockEl = document.getElementById("inv-filter-instock");
  const binsEl = document.getElementById("inv-filter-bins");
  const instockOnly = instockEl ? instockEl.checked : false;
  const binsFilter = binsEl ? binsEl.value : (invState.binsFilter || "");

  invState.searchFilter = searchFilter;
  invState.binsFilter = binsFilter;

  localStorage.setItem("inv_filter_search", searchFilter);
  localStorage.setItem("inv_filter_reorder", JSON.stringify(reorderFilters));
  localStorage.setItem("inv_filter_subcategories", JSON.stringify(subcatFilters));
  localStorage.setItem("inv_filter_instock", instockOnly ? "1" : "0");
  localStorage.setItem("inv_filter_bins", binsFilter);

  const allReorderLevels = [...new Set(invState.allProducts.map(p => p.reorder_level || 0))];
  const reorderActive = reorderFilters.length > 0 && reorderFilters.length < allReorderLevels.length;

  const matchesFilters = (p) => {
    if (searchFilter && !p.upc.toLowerCase().includes(searchFilter) && !p.description.toLowerCase().includes(searchFilter)) return false;
    if (subcatFilters.length > 0 && !subcatFilters.includes(p.subcategory || "")) return false;
    if (reorderActive && !reorderFilters.includes(p.reorder_level || 0)) return false;
    return true;
  };

  let filtered = invState.allProducts.filter((p) => {
    if (invState.viewMode === "sold" && p.net_sold <= 0) return false;
    if (invState.viewMode === "not-sold" && p.net_sold > 0) return false;
    if (instockOnly && p.quant_on_hand <= 0) return false;
    if (binsFilter === "no-bins" && p.bin_location) return false;
    if (binsFilter === "bins-only" && !p.bin_location) return false;
    return matchesFilters(p);
  });

  invState.filteredProducts = filtered;
  sortInvProducts();
  invState.currentPage = 0;

  const soldCount = invState.allProducts.filter((p) => {
    if (p.net_sold <= 0) return false;
    return matchesFilters(p);
  }).length;
  const notSoldCount = invState.allProducts.filter((p) => {
    if (p.net_sold > 0) return false;
    return matchesFilters(p);
  }).length;
  const soldBtn = document.querySelector('.inv-toggle-btn[data-view="sold"]');
  const notSoldBtn = document.querySelector('.inv-toggle-btn[data-view="not-sold"]');
  const allBtn = document.querySelector('.inv-toggle-btn[data-view="all"]');
  if (soldBtn) soldBtn.textContent = `Sold (${soldCount.toLocaleString()})`;
  if (notSoldBtn) notSoldBtn.textContent = `Not Sold (${notSoldCount.toLocaleString()})`;
  if (allBtn) allBtn.textContent = `All (${(soldCount + notSoldCount).toLocaleString()})`;

  renderInvTable();
  invRenderSummaryTiles();
}

function clearInvFilters() {
  invState.searchFilter = "";
  invState.binsFilter = "";
  const searchEl = document.getElementById("inv-filter-search");
  if (searchEl) searchEl.value = "";
  invState.selectedSubcategories = [...(invState.subcategories || [])];
  document.querySelectorAll(".inv-subcat-cb").forEach((cb) => (cb.checked = true));
  invUpdateSubcatLabel();
  const reorderLevels = [...new Set(invState.allProducts.map(p => p.reorder_level || 0))].sort((a, b) => a - b);
  invState.selectedReorderLevels = [...reorderLevels];
  document.querySelectorAll(".inv-reorder-cb").forEach((cb) => (cb.checked = true));
  invUpdateReorderLabel();
  const instockEl = document.getElementById("inv-filter-instock");
  const binsEl = document.getElementById("inv-filter-bins");
  if (instockEl) instockEl.checked = false;
  if (binsEl) binsEl.value = "";
  localStorage.removeItem("inv_filter_search");
  localStorage.removeItem("inv_filter_reorder");
  localStorage.removeItem("inv_filter_subcategories");
  localStorage.removeItem("inv_filter_instock");
  localStorage.removeItem("inv_filter_bins");
  applyInvFilters();
}

function sortInvProducts() {
  const col = invState.sortColumn;
  const dir = invState.sortDirection === "asc" ? 1 : -1;

  invState.filteredProducts.sort((a, b) => {
    let va = a[col];
    let vb = b[col];
    if (typeof va === "string" || typeof vb === "string") {
      return (va || "").localeCompare(vb || "") * dir;
    }
    return ((va || 0) - (vb || 0)) * dir;
  });
}

function handleInvSort(column) {
  if (invState.sortColumn === column) {
    invState.sortDirection = invState.sortDirection === "asc" ? "desc" : "asc";
  } else {
    invState.sortColumn = column;
    invState.sortDirection = column === "description" || column === "upc" ? "asc" : "desc";
  }
  sortInvProducts();
  invState.currentPage = 0;
  renderInvTable();
}

function invComputeTotals() {
  let onHand = 0, value = 0, sold = 0, returned = 0, net = 0;
  invState.filteredProducts.forEach((p) => {
    onHand += p.quant_on_hand || 0;
    value += (p.quant_on_hand || 0) * (p.s2s_cost || 0);
    sold += p.total_sold || 0;
    returned += p.total_returned || 0;
    net += p.net_sold || 0;
  });
  return { products: invState.filteredProducts.length, onHand, value, sold, returned, net };
}

function invRenderSummaryTiles() {
  const el = document.getElementById("inv-summary");
  if (!el) return;
  const t = invComputeTotals();
  const tile = (label, value, sub) =>
    `<div class="me-tile"><div class="me-tile-label">${escapeHtml(label)}</div>` +
    `<div class="me-tile-value">${value}</div>${sub ? `<div class="me-tile-sub">${escapeHtml(sub)}</div>` : ""}</div>`;
  el.innerHTML = [
    tile("Products", bovInt(t.products)),
    tile("On Hand", bovInt(t.onHand)),
    tile("Inventory Value", escapeHtml(bovMoney(t.value)), "Σ On Hand × S2S Cost"),
    tile("Sold", bovInt(t.sold)),
    tile("Returns", bovInt(t.returned)),
    tile("Net Sold", bovInt(t.net)),
  ].join("");
  el.style.display = "grid";
}

function renderInvTable() {
  const isSold = invState.viewMode === "sold" || invState.viewMode === "all";
  const thead = document.getElementById("inv-table-head");
  const filterRow = document.getElementById("inv-table-filters");
  const tbody = document.getElementById("inv-table-body");
  const tfoot = document.getElementById("inv-table-foot");
  const visibleCols = invGetVisibleColumns(isSold);

  const sortIcon = (col) => {
    if (invState.sortColumn !== col) return "";
    return invState.sortDirection === "asc" ? " ▲" : " ▼";
  };
  const sortStyle = 'cursor: pointer; user-select: none;';

  let headHtml = `<th style="width: 20px; text-align: center">#</th>`;
  visibleCols.forEach(col => {
    const widthStyle = col.width ? `width: ${col.width};` : "";
    headHtml += `<th style="${widthStyle} ${col.thStyle} ${sortStyle}" onclick="handleInvSort('${col.key}')">${col.label}${sortIcon(col.key)}</th>`;
  });
  thead.innerHTML = headHtml;

  // Build filter row — only rebuild when view mode or visible columns change
  const filterCacheKey = `${isSold ? "sold" : "not-sold"}|${invState.hiddenColumns.join(",")}`;
  if (filterRow.dataset.viewKey !== filterCacheKey) {
    filterRow.dataset.viewKey = filterCacheKey;

    const subcatTrigger = `<div id="inv-subcat-trigger" onclick="invToggleSubcatDropdown()" class="dark-input" style="cursor: pointer; display: flex; justify-content: space-between; align-items: center; font-size: 0.75rem; padding: 0.2rem 0.4rem; user-select: none;">
      <span id="inv-subcat-label" style="overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">All</span>
      <span style="font-size: 0.5rem; color: var(--text-tertiary);">▼</span>
    </div>
    <div id="inv-subcat-dropdown" style="display: none; position: fixed; z-index: 100; max-height: 500px; overflow-y: auto; background: var(--bg-secondary); border: 1px solid var(--border-color); border-radius: var(--radius-md); box-shadow: var(--shadow-md); min-width: 280px;"></div>`;

    const reorderTrigger = `<div id="inv-reorder-trigger" onclick="invToggleReorderDropdown()" class="dark-input" style="cursor: pointer; display: flex; justify-content: space-between; align-items: center; font-size: 0.75rem; padding: 0.2rem 0.4rem; user-select: none;">
      <span id="inv-reorder-label" style="overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">All</span>
      <span style="font-size: 0.5rem; color: var(--text-tertiary);">▼</span>
    </div>
    <div id="inv-reorder-dropdown" style="display: none; position: fixed; z-index: 100; max-height: 500px; overflow-y: auto; background: var(--bg-secondary); border: 1px solid var(--border-color); border-radius: var(--radius-md); box-shadow: var(--shadow-md); min-width: 180px;"></div>`;

    let filterHtml = `<td style="width: 20px;"></td>`;
    // One combined UPC/Description search field spanning both columns when visible
    const searchSpan = visibleCols.filter(c => c.key === "upc" || c.key === "description").length;
    let searchPlaced = false;
    visibleCols.forEach(col => {
      const w = col.width ? `width: ${col.width};` : "";
      if (col.key === "upc" || col.key === "description") {
        if (!searchPlaced) {
          filterHtml += `<td colspan="${searchSpan}"><input type="text" id="inv-filter-search" class="dark-input" placeholder="UPC / Description..." oninput="applyInvFilters()" style="width: 100%;"></td>`;
          searchPlaced = true;
        }
      } else if (col.key === "subcategory") {
        filterHtml += `<td style="${w}">${subcatTrigger}</td>`;
      } else if (col.key === "reorder_level") {
        filterHtml += `<td style="${w}">${reorderTrigger}</td>`;
      } else if (col.key === "bin_location") {
        filterHtml += `<td style="${w}"><select id="inv-filter-bins" class="dark-input" onchange="applyInvFilters()" style="font-size: 0.75rem; padding: 0.2rem 0.3rem;"><option value="">All</option><option value="no-bins">No Bins</option><option value="bins-only">Bins Only</option></select></td>`;
      } else if (col.key === "quant_on_hand") {
        filterHtml += `<td style="${w}"><label style="display: flex; align-items: center; gap: 0.25rem; font-size: 0.75rem; cursor: pointer; white-space: nowrap;"><input type="checkbox" id="inv-filter-instock" onchange="applyInvFilters()"> In Stock</label></td>`;
      } else {
        filterHtml += `<td style="${w}"></td>`;
      }
    });
    filterRow.innerHTML = filterHtml;

    // Restore filter input values from state
    const searchEl = document.getElementById("inv-filter-search");
    if (searchEl) searchEl.value = invState.searchFilter || "";

    // Rebuild subcategory dropdown, preserving any saved selections
    const savedSubcats = invState.selectedSubcategories ? [...invState.selectedSubcategories] : [];
    invBuildSubcatDropdown(invState.allSubcategories || invState.subcategories || []);
    if (savedSubcats.length > 0 && savedSubcats.length < (invState.subcategories || []).length) {
      invState.selectedSubcategories = savedSubcats.filter(s => (invState.subcategories || []).includes(s));
      document.querySelectorAll(".inv-subcat-cb").forEach(cb => {
        cb.checked = invState.selectedSubcategories.includes(cb.value);
      });
    }
    invUpdateSubcatLabel();

    // Build reorder dropdown, preserving any saved selections
    const reorderLevels = [...new Set(invState.allProducts.map(p => p.reorder_level || 0))].sort((a, b) => a - b);
    const savedReorders = invState.selectedReorderLevels.length > 0 ? [...invState.selectedReorderLevels] : [];
    invBuildReorderDropdown(reorderLevels);
    if (savedReorders.length > 0 && savedReorders.length < reorderLevels.length) {
      invState.selectedReorderLevels = savedReorders.filter(v => reorderLevels.includes(v));
      document.querySelectorAll(".inv-reorder-cb").forEach(cb => {
        cb.checked = invState.selectedReorderLevels.includes(Number(cb.value));
      });
    }
    invUpdateReorderLabel();

    // Restore bins dropdown
    const binsEl = document.getElementById("inv-filter-bins");
    if (binsEl) binsEl.value = invState.binsFilter || "";
  } else {
    // Update reorder dropdown options without full rebuild (dataset may have changed)
    const reorderLevels = [...new Set(invState.allProducts.map(p => p.reorder_level || 0))].sort((a, b) => a - b);
    const currentSelected = invState.selectedReorderLevels;
    invBuildReorderDropdown(reorderLevels);
    if (currentSelected.length > 0 && currentSelected.length < reorderLevels.length) {
      invState.selectedReorderLevels = currentSelected.filter(v => reorderLevels.includes(v));
      document.querySelectorAll(".inv-reorder-cb").forEach(cb => {
        cb.checked = invState.selectedReorderLevels.includes(Number(cb.value));
      });
    }
    invUpdateReorderLabel();
  }

  const start = invState.currentPage * invState.pageSize;
  const end = Math.min(start + invState.pageSize, invState.filteredProducts.length);
  const pageData = invState.filteredProducts.slice(start, end);

  tbody.innerHTML = "";
  pageData.forEach((p, i) => {
    const row = document.createElement("tr");
    let cellsHtml = `<td style="text-align: center; color: var(--text-tertiary); font-size: 0.75rem">${start + i + 1}</td>`;
    visibleCols.forEach(col => {
      const raw = col.key === "subcategory" ? (p.subcategory || "") :
                  col.key === "bin_location" ? (p.bin_location || "") :
                  col.key === "reorder_level" ? (p.reorder_level || 0) :
                  p[col.key];
      const display = col.money ? bovMoney(raw) : typeof raw === "number" ? raw.toLocaleString() : raw;
      const titleAttr = (col.key === "description" || col.key === "subcategory" || col.key === "bin_location") ? ` title="${raw}"` : "";
      cellsHtml += `<td style="${col.tdStyle}"${titleAttr}>${display}</td>`;
    });
    row.innerHTML = cellsHtml;
    tbody.appendChild(row);
  });

  tfoot.innerHTML = "";
  if (pageData.length > 0) {
    const t = invComputeTotals();
    const totalsMap = { quant_on_hand: t.onHand, total_cost: t.value, total_sold: t.sold, total_returned: t.returned, net_sold: t.net };
    const hasDesc = visibleCols.some(c => c.key === "description");

    let footHtml = `<td></td>`;
    let labelPlaced = false;
    visibleCols.forEach((col, idx) => {
      if (col.key === "description") {
        footHtml += `<td style="font-size: 0.8125rem">Totals</td>`;
        labelPlaced = true;
      } else if (!labelPlaced && !hasDesc && idx === 0) {
        footHtml += `<td style="font-size: 0.8125rem">Totals</td>`;
        labelPlaced = true;
      } else if (totalsMap[col.key] !== undefined) {
        const colorStyle = col.key === "total_returned" ? " color: var(--warning);" : "";
        const display = col.key === "total_cost" ? bovMoney(totalsMap[col.key]) : totalsMap[col.key].toLocaleString();
        const titleAttr = col.key === "total_cost" ? ' title="Inventory Value = Σ On Hand × S2S Cost"' : "";
        footHtml += `<td style="text-align: right; font-size: 0.8125rem;${colorStyle}"${titleAttr}>${display}</td>`;
      } else {
        footHtml += `<td></td>`;
      }
    });
    tfoot.innerHTML = `<tr style="font-weight: 700; border-top: 2px solid var(--border-color);">${footHtml}</tr>`;
  }

  const total = invState.filteredProducts.length;
  const totalPages = Math.max(1, Math.ceil(total / invState.pageSize));
  document.getElementById("inv-total-records").textContent = `${total.toLocaleString()} records`;
  document.getElementById("inv-page-info").textContent = `Page ${invState.currentPage + 1} of ${totalPages}`;
  document.getElementById("inv-prev-page").disabled = invState.currentPage === 0;
  document.getElementById("inv-next-page").disabled = invState.currentPage >= totalPages - 1;
  const viewLabel = invState.viewMode === "sold" ? "products sold" : invState.viewMode === "not-sold" ? "products not sold" : "products";
  document.getElementById("inv-results-count").textContent = `Showing ${total === 0 ? 0 : start + 1}-${end} of ${total.toLocaleString()} ${viewLabel}`;
  document.getElementById("inv-page-size").value = invState.pageSize;
}

function changeInvPage(delta) {
  const totalPages = Math.ceil(invState.filteredProducts.length / invState.pageSize);
  const newPage = invState.currentPage + delta;
  if (newPage >= 0 && newPage < totalPages) {
    invState.currentPage = newPage;
    renderInvTable();
  }
}

function changeInvPageSize() {
  invState.pageSize = parseInt(document.getElementById("inv-page-size").value);
  invState.currentPage = 0;
  localStorage.setItem("inv_page_size", invState.pageSize);
  renderInvTable();
}

function exportInventoryReport() {
  if (!invState.filteredProducts || invState.filteredProducts.length === 0) return;

  const isSold = invState.viewMode === "sold" || invState.viewMode === "all";
  const visibleCols = invGetVisibleColumns(isSold);
  const headers = visibleCols.map(col => col.label);

  const dataRows = invState.filteredProducts.map((p) =>
    visibleCols.map(col => {
      if (col.key === "subcategory") return p.subcategory || "";
      if (col.key === "bin_location") return p.bin_location || "";
      if (col.key === "reorder_level") return p.reorder_level || 0;
      return p[col.key];
    })
  );

  const t = invComputeTotals();
  const totalsMap = { quant_on_hand: t.onHand, total_cost: t.value, total_sold: t.sold, total_returned: t.returned, net_sold: t.net };
  const totalsRow = visibleCols.map(col => {
    if (col.key === "description") return "Totals";
    if (totalsMap[col.key] !== undefined) return totalsMap[col.key];
    return "";
  });
  dataRows.push(totalsRow);

  const wsData = [headers, ...dataRows];
  const ws = XLSX.utils.aoa_to_sheet(wsData);
  ws["!cols"] = headers.map(() => ({ wch: 18 }));

  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, "Inventory");

  const dateStr = new Date().toISOString().split("T")[0];
  XLSX.writeFile(wb, `inventory-report-${invState.viewMode}-${dateStr}.xlsx`);
}

function invSelectSellingSubcategories() {
  const sellingSubcats = new Set();
  invState.allProducts.forEach((p) => {
    if (p.net_sold > 0 && p.subcategory) sellingSubcats.add(p.subcategory);
  });
  invState.selectedSubcategories = [...sellingSubcats];
  document.querySelectorAll(".inv-subcat-cb").forEach((cb) => {
    cb.checked = sellingSubcats.has(cb.value);
  });
  invUpdateSubcatLabel();
  applyInvFilters();
}

function invBuildSubcatDropdown(subcategories) {
  const container = document.getElementById("inv-subcat-dropdown");
  if (!container) return;
  container.innerHTML = "";

  // Excluded subcategories are managed on the Sales page; applied read-only here.
  const excludedSubcats = invState.excludedSubcategories || [];
  const visibleSubcats = subcategories.filter((sc) => !excludedSubcats.includes(sc));
  invState.subcategories = visibleSubcats;

  const controls = document.createElement("div");
  controls.style.cssText = "display: flex; justify-content: space-between; align-items: center; padding: 0.375rem 0.75rem; border-bottom: 2px solid var(--border-color); gap: 0.25rem;";
  controls.innerHTML = `
    <div style="display: flex; gap: 0.375rem;">
      <button type="button" class="btn btn-secondary" onclick="invSubcatCheckAll(true)" style="font-size: 0.625rem; padding: 0.15rem 0.4rem;">All</button>
      <button type="button" class="btn btn-secondary" onclick="invSubcatCheckAll(false)" style="font-size: 0.625rem; padding: 0.15rem 0.4rem;">None</button>
    </div>
  `;
  container.appendChild(controls);

  visibleSubcats.forEach((sc) => {
    const label = document.createElement("label");
    label.style.cssText = "display: flex; align-items: center; gap: 0.5rem; padding: 0.375rem 0.75rem; cursor: pointer; font-size: 0.8125rem; border-bottom: 1px solid var(--border-color);";
    label.innerHTML = `<input type="checkbox" class="inv-subcat-cb" value="${sc}" checked onchange="onInvSubcatChange()"> ${sc}`;
    container.appendChild(label);
  });
  invState.selectedSubcategories = [...visibleSubcats];
}

function invSubcatCheckAll(checked) {
  document.querySelectorAll(".inv-subcat-cb").forEach((cb) => (cb.checked = checked));
  onInvSubcatChange();
}

function invToggleSubcatDropdown() {
  const dd = document.getElementById("inv-subcat-dropdown");
  if (dd.style.display === "none") {
    const trigger = document.getElementById("inv-subcat-trigger");
    const rect = trigger.getBoundingClientRect();
    dd.style.position = "fixed";
    dd.style.top = (rect.bottom + 2) + "px";
    dd.style.left = rect.left + "px";
    dd.style.display = "block";
  } else {
    dd.style.display = "none";
  }
}

function onInvSubcatChange() {
  invState.selectedSubcategories = Array.from(document.querySelectorAll(".inv-subcat-cb:checked")).map((cb) => cb.value);
  invUpdateSubcatLabel();
  applyInvFilters();
}

function invUpdateSubcatLabel() {
  const sel = invState.selectedSubcategories || [];
  const total = invState.subcategories ? invState.subcategories.length : 0;
  const label = document.getElementById("inv-subcat-label");
  if (!label) return;
  if (sel.length === 0 || sel.length === total) {
    label.textContent = "All";
  } else {
    const unchecked = total - sel.length;
    label.textContent = `${unchecked} excluded`;
  }
}

function invBuildReorderDropdown(levels) {
  const container = document.getElementById("inv-reorder-dropdown");
  if (!container) return;
  container.innerHTML = "";

  const controls = document.createElement("div");
  controls.style.cssText = "display: flex; justify-content: space-between; align-items: center; padding: 0.375rem 0.75rem; border-bottom: 2px solid var(--border-color); gap: 0.25rem;";
  controls.innerHTML = `
    <div style="display: flex; gap: 0.375rem;">
      <button type="button" class="btn btn-secondary" onclick="invReorderCheckAll(true)" style="font-size: 0.625rem; padding: 0.15rem 0.4rem;">All</button>
      <button type="button" class="btn btn-secondary" onclick="invReorderCheckAll(false)" style="font-size: 0.625rem; padding: 0.15rem 0.4rem;">None</button>
    </div>
  `;
  container.appendChild(controls);

  levels.forEach((lvl) => {
    const label = document.createElement("label");
    label.style.cssText = "display: flex; align-items: center; gap: 0.5rem; padding: 0.375rem 0.75rem; cursor: pointer; font-size: 0.8125rem; border-bottom: 1px solid var(--border-color);";
    label.innerHTML = `<input type="checkbox" class="inv-reorder-cb" value="${lvl}" checked onchange="onInvReorderChange()"> ${lvl}`;
    container.appendChild(label);
  });
  invState.selectedReorderLevels = [...levels];
}

function invReorderCheckAll(checked) {
  document.querySelectorAll(".inv-reorder-cb").forEach((cb) => (cb.checked = checked));
  onInvReorderChange();
}

function invToggleReorderDropdown() {
  const dd = document.getElementById("inv-reorder-dropdown");
  if (dd.style.display === "none") {
    const trigger = document.getElementById("inv-reorder-trigger");
    const rect = trigger.getBoundingClientRect();
    dd.style.position = "fixed";
    dd.style.top = (rect.bottom + 2) + "px";
    dd.style.left = rect.left + "px";
    dd.style.display = "block";
  } else {
    dd.style.display = "none";
  }
}

function onInvReorderChange() {
  invState.selectedReorderLevels = Array.from(document.querySelectorAll(".inv-reorder-cb:checked")).map((cb) => Number(cb.value));
  invUpdateReorderLabel();
  applyInvFilters();
}

function invUpdateReorderLabel() {
  const sel = invState.selectedReorderLevels || [];
  const allLevels = [...new Set(invState.allProducts.map(p => p.reorder_level || 0))];
  const total = allLevels.length;
  const label = document.getElementById("inv-reorder-label");
  if (!label) return;
  if (sel.length === 0 || sel.length === total) {
    label.textContent = "All";
  } else {
    const unchecked = total - sel.length;
    label.textContent = `${unchecked} excluded`;
  }
}

document.addEventListener("click", (e) => {
  const trigger = document.getElementById("inv-subcat-trigger");
  const dropdown = document.getElementById("inv-subcat-dropdown");
  if (trigger && dropdown && !trigger.contains(e.target) && !dropdown.contains(e.target)) {
    dropdown.style.display = "none";
  }
  const reorderTrigger = document.getElementById("inv-reorder-trigger");
  const reorderDropdown = document.getElementById("inv-reorder-dropdown");
  if (reorderTrigger && reorderDropdown && !reorderTrigger.contains(e.target) && !reorderDropdown.contains(e.target)) {
    reorderDropdown.style.display = "none";
  }
});

// ===== End BOV Inventory tab =====

// ============================================================================
// Order Sync — BackOffice ↔ Shopify shipped-order reconciliation
// ============================================================================

const OSYNC_PREFS_KEY = "order_sync_prefs";

const orderSyncState = {
  initialized: false,
  loading: false,
  data: null,
  config: null,
  allStores: [],
  filters: { status: "all", issue: null, search: "" },
  sort: { key: "date", dir: "desc" },
  diffOnly: true,
  abort: null,
  progressLog: [],
  visible: [],          // rows as currently listed (filter + sort applied)
  modalPos: -1,         // index into `visible` for the open drill-in
};

const OSYNC_STATUS_LABELS = {
  matched_ok: "Matched",
  matched_diffs: "Differences",
  shopify_unmatched: "Shopify only",
  backoffice_unmatched: "BackOffice only",
};

const OSYNC_METHOD_LABELS = {
  tracking: "Tracking",
  phone: "Phone",
  address: "Address",
  name_zip: "Name + ZIP",
  products: "Same basket",
};

const OSYNC_ISSUE_LABELS = {
  price: "Price",
  qty: "Quantity",
  product: "Product",
  total: "Order total",
  missing_in_backoffice: "Not in BackOffice",
  missing_in_shopify: "Not in Shopify",
};

function osyncLoadPrefs() {
  try {
    const p = JSON.parse(localStorage.getItem(OSYNC_PREFS_KEY) || "{}");
    if (p.sort && p.sort.key) orderSyncState.sort = p.sort;
    if (p.status) orderSyncState.filters.status = p.status;
    if (typeof p.diffOnly === "boolean") orderSyncState.diffOnly = p.diffOnly;
  } catch (e) { /* ignore bad prefs */ }
}

function osyncSavePrefs() {
  try {
    localStorage.setItem(OSYNC_PREFS_KEY, JSON.stringify({
      sort: orderSyncState.sort,
      status: orderSyncState.filters.status,
      diffOnly: orderSyncState.diffOnly,
    }));
  } catch (e) { /* ignore */ }
}

function loadOrderSyncPage() {
  if (!orderSyncState.initialized) {
    osyncLoadPrefs();
    initOrderSyncPage();
    orderSyncState.initialized = true;
  }
  osyncLoadConfig();
}

function initOrderSyncPage() {
  applyWeekPreset("osync-start-date", "osync-end-date", 0);

  document.getElementById("osync-run")?.addEventListener("click", fetchOrderSync);
  document.getElementById("osync-idle-run")?.addEventListener("click", fetchOrderSync);
  document.getElementById("osync-config-edit-btn")?.addEventListener("click", () => osyncShowConfigSetup(true));
  document.getElementById("osync-config-save-btn")?.addEventListener("click", osyncSaveConfig);
  document.getElementById("osync-config-cancel-btn")?.addEventListener("click", () => osyncApplyConfig());
  document.getElementById("osync-export")?.addEventListener("click", osyncExport);

  document.getElementById("osync-modal-close")?.addEventListener("click", () => closeModal("osync-modal"));
  document.getElementById("osync-modal-prev")?.addEventListener("click", () => osyncStepDetail(-1));
  document.getElementById("osync-modal-next")?.addEventListener("click", () => osyncStepDetail(1));
  document.addEventListener("keydown", (e) => {
    const modal = document.getElementById("osync-modal");
    if (!modal || !modal.classList.contains("active")) return;
    if (e.key === "ArrowLeft") { e.preventDefault(); osyncStepDetail(-1); }
    else if (e.key === "ArrowRight") { e.preventDefault(); osyncStepDetail(1); }
    else if (e.key === "Escape") { closeModal("osync-modal"); }
  });
  document.getElementById("osync-modal-body")?.addEventListener("click", (e) => {
    const t = e.target.closest("[data-osync-lines]");
    if (!t) return;
    orderSyncState.diffOnly = t.dataset.osyncLines === "diff";
    osyncSavePrefs();
    osyncRenderDetail();
  });

  // Date presets + manual edits invalidate a loaded result (Month End rule:
  // the report is heavy, so a changed range never refetches by itself).
  document.getElementById("osync-controls")?.addEventListener("click", (e) => {
    const day = e.target.closest("[data-osync-day]");
    const week = e.target.closest("[data-week]");
    const month = e.target.closest("[data-month]");
    if (!day && !week && !month) return;
    if (day) {
      const d = new Date();
      d.setDate(d.getDate() - parseInt(day.dataset.osyncDay, 10));
      const ymd = toYMD(d);
      document.getElementById("osync-start-date").value = ymd;
      document.getElementById("osync-end-date").value = ymd;
    } else if (week) {
      applyWeekPreset("osync-start-date", "osync-end-date", parseInt(week.dataset.week, 10));
    } else {
      applyMonthPreset("osync-start-date", "osync-end-date", parseInt(month.dataset.month, 10));
    }
    osyncInvalidate();
  });
  ["osync-start-date", "osync-end-date"].forEach((id) => {
    document.getElementById(id)?.addEventListener("change", osyncInvalidate);
  });

  let searchTimer = null;
  document.getElementById("osync-search")?.addEventListener("input", (e) => {
    clearTimeout(searchTimer);
    searchTimer = setTimeout(() => {
      orderSyncState.filters.search = e.target.value.trim().toLowerCase();
      osyncRenderTable();
    }, 200);
  });

  document.getElementById("osync-summary")?.addEventListener("click", (e) => {
    const tile = e.target.closest("[data-osync-status]");
    if (tile) {
      const f = orderSyncState.filters;
      f.status = f.status === tile.dataset.osyncStatus ? "all" : tile.dataset.osyncStatus;
      osyncSavePrefs();
      renderOrderSync();
      return;
    }
    const chip = e.target.closest("[data-osync-issue]");
    if (chip) {
      const f = orderSyncState.filters;
      f.issue = f.issue === chip.dataset.osyncIssue ? null : chip.dataset.osyncIssue;
      renderOrderSync();
    }
  });

  document.getElementById("osync-thead")?.addEventListener("click", (e) => {
    const th = e.target.closest("th.qip-sortable");
    if (!th) return;
    const key = th.dataset.sort;
    const s = orderSyncState.sort;
    if (s.key === key) {
      s.dir = s.dir === "asc" ? "desc" : "asc";
    } else {
      s.key = key;
      s.dir = ["sh_total", "bo_total", "total_delta", "date", "issues"].includes(key) ? "desc" : "asc";
    }
    osyncSavePrefs();
    osyncRenderTable();
  });

  document.getElementById("osync-tbody")?.addEventListener("click", (e) => {
    const tr = e.target.closest("tr[data-osync-pos]");
    if (tr) osyncOpenDetail(parseInt(tr.dataset.osyncPos, 10));
  });
}

function osyncShow(id, visible) {
  const el = document.getElementById(id);
  if (el) el.style.display = visible ? "" : "none";
}

function osyncInvalidate() {
  if (!orderSyncState.data && !orderSyncState.loading) return;
  if (orderSyncState.abort) orderSyncState.abort.abort();
  orderSyncState.data = null;
  orderSyncState.loading = false;
  osyncShowIdle("changed");
}

function osyncShowIdle(reason) {
  ["osync-loading", "osync-error", "osync-empty", "osync-summary", "osync-table-card"].forEach(
    (id) => osyncShow(id, false),
  );
  const title = document.getElementById("osync-idle-title");
  if (title) {
    title.textContent =
      reason === "changed"
        ? "The date range changed — run the comparison again."
        : "Pick a date range and run the comparison.";
  }
  osyncShow("osync-idle", true);
}

function osyncSetRunning(on) {
  ["osync-run", "osync-idle-run"].forEach((id) => {
    const btn = document.getElementById(id);
    if (btn) btn.disabled = on;
  });
}

function osyncSetProgress(message) {
  const el = document.getElementById("osync-loading");
  if (!el) return;
  if (message == null) {
    orderSyncState.progressLog = [];
    return;
  }
  const log = orderSyncState.progressLog;
  log.push(message);
  while (log.length > 6) log.shift();
  el.innerHTML =
    `<div class="me-progress">` +
    log
      .map(
        (m, i) =>
          `<div class="me-progress-line${i === log.length - 1 ? " is-current" : " is-done"}">` +
          `<span class="me-progress-dot"></span>${escapeHtml(m)}</div>`,
      )
      .join("") +
    `</div>`;
}

function osyncFail(message) {
  const el = document.getElementById("osync-error");
  if (el) {
    el.textContent = `Could not run Order Sync: ${message}`;
    el.style.display = "";
  }
  osyncShow("osync-loading", false);
}

// ---- Config -----------------------------------------------------------------

async function osyncLoadConfig() {
  try {
    const [config, stores] = await Promise.all([
      apiRequest("/order-sync/config"),
      orderSyncState.allStores.length
        ? Promise.resolve(orderSyncState.allStores)
        : apiRequest("/stores"),
    ]);
    orderSyncState.config = config;
    orderSyncState.allStores = stores;
    osyncApplyConfig();
  } catch (e) {
    osyncFail(e.message || e);
  }
}

function osyncConfigured() {
  const c = orderSyncState.config;
  return !!(c && c.mssql_store_id && c.shopify_store_id);
}

function osyncApplyConfig() {
  const c = orderSyncState.config;
  if (osyncConfigured()) {
    const label = document.getElementById("osync-config-label");
    if (label) {
      label.innerHTML =
        `Comparing <strong style="color: var(--text-primary)">${escapeHtml(c.mssql_store_name || "?")}</strong>` +
        ` <span style="color: var(--text-tertiary)">(BackOffice, source of truth)</span>` +
        ` <span style="color: var(--text-tertiary)">⇄</span> ` +
        `<strong style="color: var(--text-primary)">${escapeHtml(c.shopify_store_name || "?")}</strong>`;
    }
    osyncShow("osync-config-bar", true);
    osyncShow("osync-config-setup", false);
    osyncShow("osync-controls", true);
    if (!orderSyncState.data && !orderSyncState.loading) osyncShowIdle(null);
  } else {
    osyncShowConfigSetup(false);
  }
}

function osyncShowConfigSetup(isEdit) {
  const c = orderSyncState.config || {};
  const fill = (id, type, selectedId) => {
    const select = document.getElementById(id);
    if (!select) return;
    select.innerHTML = '<option value="">Select...</option>';
    orderSyncState.allStores
      .filter((s) => s.store_type === type && s.is_active)
      .forEach((s) => {
        const opt = document.createElement("option");
        opt.value = s.id;
        opt.textContent = s.name;
        if (selectedId === s.id) opt.selected = true;
        select.appendChild(opt);
      });
  };
  fill("osync-mssql-select", "mssql", c.mssql_store_id);
  fill("osync-shopify-select", "shopify", c.shopify_store_id);
  osyncShow("osync-config-cancel-btn", isEdit && osyncConfigured());
  osyncShow("osync-config-bar", false);
  osyncShow("osync-config-setup", true);
  osyncShow("osync-controls", false);
  osyncShow("osync-idle", false);
}

async function osyncSaveConfig() {
  const mssqlId = parseInt(document.getElementById("osync-mssql-select")?.value, 10) || null;
  const shopifyId = parseInt(document.getElementById("osync-shopify-select")?.value, 10) || null;
  if (!mssqlId || !shopifyId) {
    showToast("Select both a BackOffice database and a Shopify store", "error");
    return;
  }
  try {
    orderSyncState.config = await apiRequest("/order-sync/config", {
      method: "POST",
      body: JSON.stringify({ mssql_store_id: mssqlId, shopify_store_id: shopifyId }),
    });
    showToast("Order Sync configuration saved", "success");
    osyncInvalidate();
    osyncApplyConfig();
  } catch (e) {
    showToast(e.message || "Failed to save configuration", "error");
  }
}

// ---- Report fetch (SSE with plain-JSON fallback) ----------------------------

function osyncRangeParams() {
  return {
    date_from: document.getElementById("osync-start-date")?.value || "",
    date_to: document.getElementById("osync-end-date")?.value || "",
  };
}

async function fetchOrderSync() {
  const params = osyncRangeParams();
  if (!params.date_from || !params.date_to) {
    osyncFail("pick both dates first");
    return;
  }
  if (orderSyncState.abort) orderSyncState.abort.abort();
  const ctl = new AbortController();
  orderSyncState.abort = ctl;
  orderSyncState.loading = true;
  osyncShow("osync-idle", false);
  osyncShow("osync-error", false);
  osyncShow("osync-empty", false);
  osyncShow("osync-summary", false);
  osyncShow("osync-table-card", false);
  osyncSetRunning(true);
  osyncSetProgress(null);
  osyncSetProgress("Starting…");
  osyncShow("osync-loading", true);
  const finish = () => {
    if (orderSyncState.abort === ctl) {
      orderSyncState.loading = false;
      osyncShow("osync-loading", false);
      osyncSetRunning(false);
    }
  };
  const qs = new URLSearchParams(params);
  try {
    const resp = await fetch(`${API_BASE}/order-sync/report/stream?${qs}`, { signal: ctl.signal });
    if (!resp.ok || !resp.body) throw new Error(`HTTP ${resp.status}`);
    const reader = resp.body.getReader();
    const decoder = new TextDecoder();
    let buffer = "";
    let gotResult = false;
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      buffer += decoder.decode(value, { stream: true });
      const chunks = buffer.split("\n\n");
      buffer = chunks.pop();
      for (const chunk of chunks) {
        const m = chunk.match(/event: (\w+)\ndata: (.+)/s);
        if (!m) continue;
        const [, ev, dataStr] = m;
        if (ev === "progress") {
          try { osyncSetProgress(JSON.parse(dataStr).message); } catch (e) { /* malformed frame */ }
        } else if (ev === "result") {
          orderSyncState.data = JSON.parse(dataStr);
          gotResult = true;
          finish();
          renderOrderSync();
        } else if (ev === "error") {
          let msg = "server error";
          try { msg = JSON.parse(dataStr).message || msg; } catch (e) { /* keep default */ }
          throw new Error(msg);
        }
      }
    }
    if (!gotResult) throw new Error("stream ended without a result");
  } catch (e) {
    if (e.name === "AbortError" || ctl.signal.aborted) return;
    try {
      osyncSetProgress("Retrying without progress stream…");
      const resp = await fetch(`${API_BASE}/order-sync/report?${qs}`, { signal: ctl.signal });
      if (!resp.ok) {
        const err = await resp.json().catch(() => ({}));
        throw new Error(err.detail || `HTTP ${resp.status}`);
      }
      orderSyncState.data = await resp.json();
      if (ctl.signal.aborted) return;
      finish();
      renderOrderSync();
    } catch (e2) {
      if (e2.name === "AbortError" || ctl.signal.aborted) return;
      osyncFail(e2.message || e2);
      finish();
    }
  } finally {
    finish();
  }
}

// ---- Formatting helpers -----------------------------------------------------

function osyncMoney(v) {
  if (v == null || Number.isNaN(Number(v))) return "—";
  return Number(v).toLocaleString("en-US", { style: "currency", currency: "USD" });
}

function osyncSignedMoney(v) {
  if (v == null) return "—";
  const abs = osyncMoney(Math.abs(v));
  return v > 0 ? `+${abs}` : v < 0 ? `−${abs}` : abs;
}

function osyncQty(v) {
  if (v == null) return "—";
  return Number(v).toLocaleString("en-US", { maximumFractionDigits: 2 });
}

function osyncFmtDate(ymd) {
  if (!ymd) return "";
  const d = new Date(`${ymd.slice(0, 10)}T00:00:00`);
  if (Number.isNaN(d.getTime())) return ymd;
  return d.toLocaleDateString("en-US", { month: "short", day: "numeric" });
}

function osyncRowDate(r) {
  return r.sh_date || (r.bo_date ? r.bo_date.slice(0, 10) : "");
}

function osyncDash() {
  return '<span class="osync-muted">—</span>';
}

function osyncIssueChip(kind, cls = "") {
  return `<span class="osync-issue ${cls}">${escapeHtml(OSYNC_ISSUE_LABELS[kind] || kind)}</span>`;
}

function osyncMethodPill(r) {
  if (!r.match_method) return osyncDash();
  const strong = r.match_method === "tracking";
  return (
    `<span class="osync-method${strong ? " is-strong" : ""}">${escapeHtml(OSYNC_METHOD_LABELS[r.match_method] || r.match_method)}</span>` +
    (r.ambiguous
      ? ' <span class="osync-ambig" title="Several invoices were plausible — closest total and date was picked. Worth a look.">?</span>'
      : "")
  );
}

// ---- Rendering --------------------------------------------------------------

function osyncVisibleRows() {
  const { status, issue, search } = orderSyncState.filters;
  let rows = (orderSyncState.data?.rows || []).map((r, i) => ({ ...r, _idx: i }));
  if (status === "no_tracking") {
    rows = rows.filter((r) => r.sh_no_tracking || r.bo_no_tracking);
  } else if (status !== "all") {
    rows = rows.filter((r) => r.status === status);
  }
  if (issue) {
    rows = rows.filter((r) => {
      if (issue === "ambiguous") return r.ambiguous;
      if (issue === "shared") return !!r.shared_tracking;
      if (issue === "combined") return r.combined;
      return (r.issue_kinds || []).includes(issue);
    });
  }
  if (search) {
    rows = rows.filter((r) =>
      [
        r.sh_name, r.bo_invoice_number, r.sh_customer, r.bo_customer, r.bo_tracking,
        ...(r.sh_tracking || []),
      ].some((v) => v && String(v).toLowerCase().includes(search)),
    );
  }
  const { key, dir } = orderSyncState.sort;
  const val = (r) => {
    if (key === "date") return osyncRowDate(r);
    if (key === "issues") return (r.issue_kinds || []).length;
    if (key === "customer") return r.sh_customer || r.bo_customer || "";
    if (key === "status") return ["shopify_unmatched", "backoffice_unmatched", "matched_diffs", "matched_ok"].indexOf(r.status);
    const v = r[key];
    return v == null ? (["sh_total", "bo_total", "total_delta"].includes(key) ? -Infinity : "") : v;
  };
  rows.sort((a, b) => {
    const va = val(a);
    const vb = val(b);
    let cmp;
    if (typeof va === "number" || typeof vb === "number") {
      cmp = (Number(va) || 0) - (Number(vb) || 0);
    } else {
      cmp = String(va).localeCompare(String(vb));
    }
    return dir === "asc" ? cmp : -cmp;
  });
  return rows;
}

function renderOrderSync() {
  const data = orderSyncState.data;
  if (!data) return;
  if (data.configured === false) {
    osyncShowConfigSetup(false);
    return;
  }
  const s = data.summary || {};
  const f = orderSyncState.filters;
  const matchedRows = (s.matched_ok || 0) + (s.matched_diffs || 0);
  const pct = s.shopify_total ? Math.round(((s.matched_orders || 0) / s.shopify_total) * 100) : 0;
  const okPct = matchedRows ? Math.round(((s.matched_ok || 0) / matchedRows) * 100) : 0;

  const tiles = [
    ["all", "All orders", s.shopify_total || 0, `${s.backoffice_total || 0} invoices`, ""],
    ["matched_ok", "Matched", s.matched_ok || 0, `${okPct}% of matched clean`, "is-ok"],
    ["matched_diffs", "Differences", s.matched_diffs || 0, "line or total mismatch", "is-warn"],
    ["shopify_unmatched", "Shopify only", s.shopify_unmatched || 0, "no invoice found", "is-bad"],
    ["backoffice_unmatched", "BackOffice only", s.backoffice_unmatched || 0, "no Shopify order found", "is-bad"],
    ["no_tracking", "Missing tracking", (s.shopify_no_tracking || 0) + (s.backoffice_no_tracking || 0),
      `${s.shopify_no_tracking || 0} Shopify · ${s.backoffice_no_tracking || 0} BO`, "is-warn"],
  ];
  const ic = s.issue_counts || {};
  const chips = [
    ["price", "Price", ic.price], ["qty", "Quantity", ic.qty], ["product", "Product", ic.product],
    ["total", "Order total", ic.total],
    ["ambiguous", "Ambiguous match", s.ambiguous], ["shared", "Shared tracking", (data.rows || []).filter((r) => r.shared_tracking).length],
    ["combined", "Combined shipments", s.combined_groups],
  ].filter(([, , n]) => n);

  const summaryEl = document.getElementById("osync-summary");
  if (summaryEl) {
    summaryEl.innerHTML =
      `<div class="osync-context">` +
      `<div><strong>${escapeHtml(data.mssql_store_name || "BackOffice")}</strong> <span class="osync-muted">⇄</span> <strong>${escapeHtml(data.shopify_store_name || "Shopify")}</strong>` +
      ` <span class="osync-muted">·</span> ${escapeHtml(osyncFmtDate(data.date_from))}${data.date_from !== data.date_to ? ` – ${escapeHtml(osyncFmtDate(data.date_to))}` : ""}</div>` +
      `<div class="osync-context-right"><span class="osync-rate"><strong>${pct}%</strong> of Shopify orders reconciled</span>` +
      (data.timings?.fetch != null ? `<span class="osync-muted">fetched in ${data.timings.fetch}s</span>` : "") +
      `</div></div>` +
      `<div class="osync-tiles">` +
      tiles
        .map(
          ([key, label, count, sub, tone]) =>
            `<button type="button" class="osync-tile ${tone}${f.status === key ? " is-active" : ""}" data-osync-status="${key}">` +
            `<span class="osync-tile-count">${count.toLocaleString()}</span>` +
            `<span class="osync-tile-label">${escapeHtml(label)}</span>` +
            `<span class="osync-tile-sub">${escapeHtml(sub)}</span></button>`,
        )
        .join("") +
      `</div>` +
      (chips.length
        ? `<div class="osync-chips"><span class="osync-chips-label">Filter by</span>` +
          chips
            .map(
              ([key, label, n]) =>
                `<button type="button" class="sa-chip${f.issue === key ? " active" : ""}" data-osync-issue="${key}">${escapeHtml(label)} <span class="osync-chip-n">${Number(n).toLocaleString()}</span></button>`,
            )
            .join("") +
          `</div>`
        : "");
  }
  osyncShow("osync-summary", true);

  const hasRows = (data.rows || []).length > 0;
  osyncShow("osync-empty", !hasRows);
  osyncShow("osync-table-card", hasRows);
  if (hasRows) osyncRenderTable();
}

// `.data-table` is table-layout: fixed, so every column needs an explicit
// width or they all split the table evenly; Customer takes the remainder.
const OSYNC_COLUMNS = [
  { key: "date", label: "Date", width: 68 },
  { key: "sh_name", label: "Shopify order", width: 182 },
  { key: "bo_invoice_number", label: "Invoice", width: 158 },
  { key: "customer", label: "Customer" },
  { key: "match_method", label: "Matched by", width: 104 },
  { key: "issues", label: "Issues", width: 150 },
  { key: "sh_total", label: "Shopify", num: true, width: 96 },
  { key: "bo_total", label: "BackOffice", num: true, width: 96 },
  { key: "total_delta", label: "Δ", num: true, width: 86 },
  { key: "status", label: "Status", width: 108 },
];

function osyncColgroup(cols) {
  return "<colgroup>" + cols.map((c) => `<col${c.width ? ` style="width:${c.width}px"` : ""}>`).join("") + "</colgroup>";
}

function osyncRenderTable() {
  const thead = document.getElementById("osync-thead");
  const tbody = document.getElementById("osync-tbody");
  if (!thead || !tbody) return;
  const { key: sortKey, dir } = orderSyncState.sort;
  const table = document.getElementById("osync-table");
  if (table && !table.querySelector("colgroup")) table.insertAdjacentHTML("afterbegin", osyncColgroup(OSYNC_COLUMNS));
  thead.innerHTML =
    "<tr>" +
    OSYNC_COLUMNS.map((c) => {
      const cls = ["qip-sortable"];
      if (c.num) cls.push("osync-num");
      if (sortKey === c.key) cls.push(dir === "asc" ? "qip-sort-asc" : "qip-sort-desc");
      return `<th class="${cls.join(" ")}" data-sort="${c.key}"><span>${escapeHtml(c.label)}</span><span class="qip-sort-arrow"></span></th>`;
    }).join("") +
    "</tr>";

  const rows = osyncVisibleRows();
  orderSyncState.visible = rows;
  tbody.innerHTML = rows
    .map((r, pos) => {
      const tone = r.status === "matched_ok" ? "is-ok" : r.status === "matched_diffs" ? "is-warn" : "is-bad";
      const sharedBadge = r.shared_tracking
        ? ` <span class="osync-badge is-shared" title="${escapeHtml(`Tracking ${r.shared_tracking.tracking} is shared by orders ${r.shared_tracking.orders.join(", ")} and invoices ${r.shared_tracking.invoices.join(", ")}`)}">shared ×${r.shared_tracking.orders.length}</span>`
        : "";
      const nameCell = (name, noTrk, combinedN, extra = "") =>
        (name ? escapeHtml(name) : osyncDash()) +
        (combinedN > 1 ? ` <span class="osync-badge is-combined" title="${combinedN} reconciled together as one shipment">×${combinedN}</span>` : "") +
        (noTrk && name ? ' <span class="osync-flag" title="Nothing in the tracking field">no tracking</span>' : "") +
        extra;
      const issues = (r.issue_kinds || []).map((k) => osyncIssueChip(k)).join(" ");
      const delta = r.total_delta;
      const deltaCls = delta != null && Math.abs(delta) > 0.011 ? " osync-delta-bad" : "";
      return (
        `<tr data-osync-pos="${pos}" class="osync-row ${tone}">` +
        `<td class="osync-nowrap">${escapeHtml(osyncFmtDate(osyncRowDate(r)))}</td>` +
        `<td class="osync-nowrap">${nameCell(r.sh_name, r.sh_no_tracking, (r.sh_orders || []).length, sharedBadge)}</td>` +
        `<td class="osync-nowrap">${nameCell(r.bo_invoice_number, r.bo_no_tracking, (r.bo_invoices || []).length)}</td>` +
        `<td class="osync-customer" title="${escapeHtml(r.sh_customer || r.bo_customer || "")}">${escapeHtml(r.sh_customer || r.bo_customer || "")}</td>` +
        `<td class="osync-nowrap">${osyncMethodPill(r)}</td>` +
        `<td>${issues || (r.status === "matched_ok" ? '<span class="osync-muted">none</span>' : "")}</td>` +
        `<td class="osync-num">${osyncMoney(r.sh_total)}</td>` +
        `<td class="osync-num">${osyncMoney(r.bo_total)}</td>` +
        `<td class="osync-num${deltaCls}">${delta != null ? osyncSignedMoney(delta) : "—"}</td>` +
        `<td><span class="osync-status ${tone}">${escapeHtml(OSYNC_STATUS_LABELS[r.status] || r.status)}</span></td>` +
        `</tr>`
      );
    })
    .join("");

  const count = document.getElementById("osync-count");
  if (count) {
    const total = (orderSyncState.data?.rows || []).length;
    count.textContent = rows.length === total ? `${total} rows` : `${rows.length} of ${total} rows`;
  }
}

// ---- Drill-in modal ---------------------------------------------------------

function osyncOpenDetail(pos) {
  orderSyncState.modalPos = pos;
  osyncRenderDetail();
  openModal("osync-modal");
}

function osyncStepDetail(delta) {
  const next = orderSyncState.modalPos + delta;
  if (next < 0 || next >= orderSyncState.visible.length) return;
  orderSyncState.modalPos = next;
  osyncRenderDetail();
}

const OSYNC_LINE_COLUMNS = [
  { width: 118 }, {}, { width: 60 }, { width: 60 },
  { width: 84 }, { width: 84 }, { width: 92 }, { width: 92 }, { width: 112 },
];

// One metric, two columns: "Qty / Shopify" and "Qty / BackOffice".
function osyncPairTh(metric) {
  return (
    `<th class="osync-num osync-th-pair"><span class="osync-th-metric">${escapeHtml(metric)}</span><span class="osync-th-side is-shopify">Shopify</span></th>` +
    `<th class="osync-num osync-th-pair"><span class="osync-th-metric">${escapeHtml(metric)}</span><span class="osync-th-side is-backoffice">BackOffice</span></th>`
  );
}

function osyncSideCard(title, tone, items) {
  return (
    `<div class="osync-side ${tone}"><div class="osync-side-title">${escapeHtml(title)}</div>` +
    items
      .map(([label, html]) => `<div class="osync-side-row"><span class="osync-side-label">${escapeHtml(label)}</span><span class="osync-side-value">${html}</span></div>`)
      .join("") +
    `</div>`
  );
}

function osyncRenderDetail() {
  const rows = orderSyncState.visible;
  const pos = orderSyncState.modalPos;
  const r = rows[pos];
  if (!r) return;

  const title = document.getElementById("osync-modal-title");
  if (title) title.textContent = `${r.sh_name || "No Shopify order"} ⇄ ${r.bo_invoice_number ? `Invoice ${r.bo_invoice_number}` : "No invoice"}`;
  const posEl = document.getElementById("osync-modal-pos");
  if (posEl) posEl.textContent = `${pos + 1} / ${rows.length}`;
  const prev = document.getElementById("osync-modal-prev");
  const next = document.getElementById("osync-modal-next");
  if (prev) prev.disabled = pos <= 0;
  if (next) next.disabled = pos >= rows.length - 1;

  const body = document.getElementById("osync-modal-body");
  if (!body) return;

  const shItems = r.sh_orders && r.sh_orders.length
    ? [
        ["Order", r.sh_orders.map((o) => `<strong>${escapeHtml(o.name || "")}</strong>${r.sh_orders.length > 1 ? ` <span class="osync-muted">${osyncMoney(o.total)}</span>` : ""}`).join("<br>")],
        ["Placed", escapeHtml(r.sh_orders.map((o) => o.date).filter(Boolean).join(", "))],
        ["Customer", escapeHtml(r.sh_customer || "—")],
        ["Tracking", r.sh_tracking && r.sh_tracking.length ? r.sh_tracking.map((t) => `<span class="osync-mono">${escapeHtml(t)}</span>`).join("<br>") : r.sh_no_tracking ? '<span class="osync-flag">MISSING</span>' : '<span class="osync-muted">—</span>'],
        ["Total", `<strong>${osyncMoney(r.sh_total)}</strong>`],
      ]
    : [["", '<span class="osync-muted">No Shopify order matched this invoice.</span>']];

  const boItems = r.bo_invoices && r.bo_invoices.length
    ? [
        ["Invoice", r.bo_invoices.map((i) => `<strong>${escapeHtml(i.number || "")}</strong>${r.bo_invoices.length > 1 ? ` <span class="osync-muted">${osyncMoney(i.total)}</span>` : ""}`).join("<br>")],
        ["Invoiced", escapeHtml(r.bo_invoices.map((i) => (i.date || "").slice(0, 10)).filter(Boolean).join(", "))],
        ["Customer", escapeHtml(r.bo_customer || "—")],
        ["Tracking", r.bo_tracking ? r.bo_tracking.split(",").map((t) => `<span class="osync-mono">${escapeHtml(t.trim())}</span>`).join("<br>") : r.bo_no_tracking ? '<span class="osync-flag">MISSING</span>' : '<span class="osync-muted">—</span>'],
        ["Total", `<strong>${osyncMoney(r.bo_total)}</strong>`],
      ]
    : [["", '<span class="osync-muted">No BackOffice invoice matched this order.</span>']];

  const notes = [];
  if (r.shared_tracking) {
    const st = r.shared_tracking;
    notes.push(`Tracking <span class="osync-mono">${escapeHtml(st.tracking)}</span> is shared by ${st.orders.length} Shopify order(s) (${escapeHtml(st.orders.join(", "))}) and ${st.invoices.length} invoice(s) (${escapeHtml(st.invoices.join(", "))})${r.combined ? " — reconciled together as one shipment." : " — paired by closest total, lines and date."}`);
  }
  if (r.ambiguous) notes.push("Several invoices were plausible for this order; the closest total and date was picked. Verify before acting on the differences.");

  const diffs = r.line_diffs || [];
  const diffLines = diffs.filter((d) => d.issues.length);
  const showDiffOnly = orderSyncState.diffOnly && diffLines.length > 0;
  const listed = showDiffOnly ? diffLines : diffs;
  const isMatched = r.status === "matched_ok" || r.status === "matched_diffs";

  const sum = (arr, k) => arr.reduce((a, d) => a + (d[k] || 0), 0);
  const cell = (v, issueKey, fmt, d) => {
    const bad = d.issues.includes(issueKey);
    return `<td class="osync-num${bad ? " osync-diff-cell" : ""}">${v == null ? '<span class="osync-muted">—</span>' : fmt(v)}</td>`;
  };
  const linesHtml = listed
    .map((d) => {
      const bad = d.issues.length > 0;
      const totalIssue = d.issues.includes("qty") || d.issues.includes("price") ? "qty" : "";
      return (
        `<tr${bad ? ' class="osync-line-bad"' : ""}>` +
        `<td class="osync-mono osync-nowrap">${escapeHtml(d.barcode || d.sku || d.key)}</td>` +
        `<td class="osync-desc" title="${escapeHtml(d.description || "")}">${escapeHtml(d.description || "")}</td>` +
        cell(d.sh_qty, "qty", osyncQty, d) +
        cell(d.bo_qty, "qty", osyncQty, d) +
        cell(d.sh_unit_price, "price", osyncMoney, d) +
        cell(d.bo_unit_price, "price", osyncMoney, d) +
        cell(d.sh_line_total, totalIssue, osyncMoney, d) +
        cell(d.bo_line_total, totalIssue, osyncMoney, d) +
        `<td>${d.issues.map((i) => osyncIssueChip(i)).join(" ")}</td>` +
        `</tr>`
      );
    })
    .join("");

  body.innerHTML =
    `<div class="osync-sides">` +
    osyncSideCard("Shopify", "is-shopify", shItems) +
    `<div class="osync-sides-mid">` +
    (isMatched
      ? `<div class="osync-mid-method">${osyncMethodPill(r)}</div>` +
        `<div class="osync-mid-delta${r.total_delta != null && Math.abs(r.total_delta) > 0.011 ? " is-bad" : " is-ok"}">` +
        `<span class="osync-mid-delta-label">Δ total</span><span>${r.total_delta != null ? osyncSignedMoney(r.total_delta) : "—"}</span></div>` +
        `<div class="osync-mid-issues">${(r.issue_kinds || []).length ? r.issue_kinds.map((k) => osyncIssueChip(k)).join(" ") : '<span class="osync-status is-ok">All lines agree</span>'}</div>`
      : `<div class="osync-status is-bad">${escapeHtml(OSYNC_STATUS_LABELS[r.status] || r.status)}</div>`) +
    `</div>` +
    osyncSideCard("BackOffice · source of truth", "is-backoffice", boItems) +
    `</div>` +
    (notes.length ? `<div class="osync-notes">${notes.map((n) => `<div>${n}</div>`).join("")}</div>` : "") +
    (diffs.length
      ? `<div class="osync-lines-head">` +
        `<span class="osync-lines-title">${isMatched ? "Line comparison" : "Lines"}` +
        `<span class="osync-muted"> · ${diffs.length} line${diffs.length === 1 ? "" : "s"}${diffLines.length ? `, ${diffLines.length} with differences` : ""}</span></span>` +
        (diffLines.length && diffLines.length < diffs.length
          ? `<div class="osync-seg"><button type="button" class="${showDiffOnly ? "active" : ""}" data-osync-lines="diff">Differences (${diffLines.length})</button><button type="button" class="${showDiffOnly ? "" : "active"}" data-osync-lines="all">All lines (${diffs.length})</button></div>`
          : "") +
        `</div>` +
        `<div class="table-container"><table class="data-table osync-lines">` +
        osyncColgroup(OSYNC_LINE_COLUMNS) +
        `<thead><tr><th>Barcode</th><th>Description</th>` +
        osyncPairTh("Qty") + osyncPairTh("Unit price") + osyncPairTh("Line total") +
        `<th>Issue</th></tr></thead><tbody>${linesHtml}</tbody>` +
        `<tfoot><tr><td colspan="2">${showDiffOnly ? `${listed.length} of ${diffs.length} lines shown` : `All ${diffs.length} lines`}</td>` +
        `<td class="osync-num">${osyncQty(sum(listed, "sh_qty"))}</td><td class="osync-num">${osyncQty(sum(listed, "bo_qty"))}</td>` +
        `<td></td><td></td>` +
        `<td class="osync-num">${osyncMoney(sum(listed, "sh_line_total"))}</td><td class="osync-num">${osyncMoney(sum(listed, "bo_line_total"))}</td>` +
        `<td></td></tr></tfoot></table></div>`
      : `<p class="osync-muted" style="margin-top: 1rem;">No line details available for this row.</p>`);
}

// ---- Export -----------------------------------------------------------------

function osyncExport() {
  const rows = orderSyncState.visible.length ? orderSyncState.visible : osyncVisibleRows();
  if (!rows.length) {
    showToast("Nothing to export", "info");
    return;
  }
  const data = orderSyncState.data || {};
  const fname = `order-sync_${data.date_from || ""}_${data.date_to || ""}`;
  const orderHeader = ["Date", "Status", "Matched by", "Ambiguous", "Shopify order", "Invoice", "Customer",
    "Tracking", "Shopify total", "BackOffice total", "Delta", "Issues"];
  const orderRows = rows.map((r) => [
    osyncRowDate(r), OSYNC_STATUS_LABELS[r.status] || r.status, OSYNC_METHOD_LABELS[r.match_method] || "",
    r.ambiguous ? "yes" : "", r.sh_name || "", r.bo_invoice_number || "", r.sh_customer || r.bo_customer || "",
    (r.sh_tracking || []).join(", ") || r.bo_tracking || "",
    r.sh_total, r.bo_total, r.total_delta, (r.issue_kinds || []).map((k) => OSYNC_ISSUE_LABELS[k] || k).join(", "),
  ]);
  const lineHeader = ["Date", "Shopify order", "Invoice", "Barcode", "SKU", "Description",
    "Qty Shopify", "Qty BackOffice", "Price Shopify", "Price BackOffice", "Total Shopify", "Total BackOffice", "Issue"];
  const lineRows = [];
  rows.forEach((r) => {
    (r.line_diffs || []).filter((d) => d.issues.length).forEach((d) => {
      lineRows.push([osyncRowDate(r), r.sh_name || "", r.bo_invoice_number || "", d.barcode || "", d.sku || "",
        d.description || "", d.sh_qty, d.bo_qty, d.sh_unit_price, d.bo_unit_price, d.sh_line_total, d.bo_line_total,
        d.issues.map((i) => OSYNC_ISSUE_LABELS[i] || i).join(", ")]);
    });
  });

  if (typeof XLSX !== "undefined" && XLSX.utils) {
    const wb = XLSX.utils.book_new();
    const ws1 = XLSX.utils.aoa_to_sheet([orderHeader, ...orderRows]);
    ws1["!cols"] = [10, 14, 11, 9, 14, 12, 26, 22, 13, 13, 10, 28].map((w) => ({ wch: w }));
    XLSX.utils.book_append_sheet(wb, ws1, "Orders");
    const ws2 = XLSX.utils.aoa_to_sheet([lineHeader, ...lineRows]);
    ws2["!cols"] = [10, 14, 12, 16, 12, 34, 10, 12, 12, 14, 12, 14, 18].map((w) => ({ wch: w }));
    XLSX.utils.book_append_sheet(wb, ws2, "Line differences");
    XLSX.writeFile(wb, `${fname}.xlsx`);
  } else {
    bovDownloadSheet({ sheet: "Orders", header: orderHeader, data: orderRows, fname });
  }
  showToast(`Exported ${rows.length} rows and ${lineRows.length} line differences`, "success");
}

// ===== End Order Sync =====
